def _api_err(msg: str = "Request failed", e: Exception = None, code: int = 500):
    """Return a safe API error response - logs the real exception, sends generic message to client."""
    if e is not None:
        logger.warning("API error: %s", msg, exc_info=True)
    return jsonify({"error": msg, "ok": False}), code


def _rel_time(dt) -> str:
    """Human-relative timestamp: 'Today 3:42 PM', '2d ago', 'May 12'."""
    now = datetime.now(EASTERN)
    dt_et = dt.astimezone(EASTERN)
    diff = now - dt_et
    secs = diff.total_seconds()
    if secs < 60:
        return "Just now"
    if secs < 3600:
        mins = int(secs // 60)
        return f"{mins}m ago"
    today = now.date()
    if dt_et.date() == today:
        hour = dt_et.strftime("%I").lstrip("0") or "12"
        return f"Today {hour}:{dt_et.strftime('%M %p')}"
    if dt_et.date() == (now - timedelta(days=1)).date():
        return f"Yesterday"
    days = (today - dt_et.date()).days
    if days < 7:
        return f"{days}d ago"
    if days < 30:
        return f"{days // 7}w ago"
    return dt_et.strftime("%b %d")


