@app.route("/metrics")
@app.route("/<platform>/<int:season>/<league_id>/metrics")
def page_advanced_metrics(platform: str = None, season: int = None, league_id: str = None):
    """Premium Advanced Metrics leaderboard page."""
    from dashboard_services.pages.advanced_metrics_page import build_advanced_metrics_body
    from data_building.advanced_metrics import LEADERBOARD_METRICS
    user_id = session.get("viewer_username")
    body = build_advanced_metrics_body(
        True, LEADERBOARD_METRICS, league_id, season, platform
    )
    # When a shared graph link is opened (?graph=1&gx=&gy=...), give it a rich
    # social preview whose image is a server-rendered screenshot of that graph.
    og_tags = ""
    if request.args.get("graph") == "1":
        gx = request.args.get("gx") or ""
        gy = request.args.get("gy") or ""
        def _mlabel(k):
            m = LEADERBOARD_METRICS.get(k) or {}
            return m.get("label") or k
        if gx and gy:
            origin = request.host_url.rstrip("/")
            from urllib.parse import urlencode as _ue
            _og_qs = {k: request.args.get(k) for k in ("gx", "gy", "gz", "gn", "season", "metric", "pos", "minvol")
                      if request.args.get(k)}
            og_img = f"{origin}/{platform}/{season}/{league_id}/metrics/og.png?{_ue(_og_qs)}"
            og_title = f"{_mlabel(gy)} vs {_mlabel(gx)} | BR Fantasy"
            og_desc = "Advanced metrics scatter: compare efficiency and opportunity across the league."
            t = html.escape(og_title, quote=True)
            d = html.escape(og_desc, quote=True)
            img = html.escape(og_img, quote=True)
            url = html.escape(request.url, quote=True)
            og_tags = (
                f"<meta property=\"og:site_name\" content=\"BR Fantasy\">"
                f"<meta property=\"og:type\" content=\"website\">"
                f"<meta property=\"og:title\" content=\"{t}\">"
                f"<meta property=\"og:description\" content=\"{d}\">"
                f"<meta property=\"og:url\" content=\"{url}\">"
                f"<meta property=\"og:image\" content=\"{img}\">"
                f"<meta property=\"og:image:width\" content=\"1200\">"
                f"<meta property=\"og:image:height\" content=\"630\">"
                f"<meta name=\"twitter:card\" content=\"summary_large_image\">"
                f"<meta name=\"twitter:title\" content=\"{t}\">"
                f"<meta name=\"twitter:description\" content=\"{d}\">"
                f"<meta name=\"twitter:image\" content=\"{img}\">"
            )
    return render_page("Advanced Metrics", league_id, "advanced-metrics", body, platform, season, og_tags=og_tags)


@app.route("/<platform>/<int:season>/<league_id>/metrics/og.png")
def metrics_graph_og_image(platform: str, season: int, league_id: str):
    """Social-share preview image for a shared advanced-metrics graph — a
    headless screenshot of the graph rendered in og=1 mode. Falls back to the
    static logo if rendering is unavailable."""
    from dashboard_services.og_render import render_url_to_png
    from urllib.parse import urlencode as _ue
    params = {k: request.args.get(k) for k in ("gx", "gy", "gz", "gn", "season", "metric", "pos", "minvol")
              if request.args.get(k)}
    params["og"] = "1"
    render_url = f"{request.host_url.rstrip('/')}/{platform}/{season}/{league_id}/metrics?{_ue(params)}"
    cache_key = "graph:" + _ue({k: v for k, v in sorted(params.items())})
    png = render_url_to_png(
        render_url, 1200, 630,
        wait_selector="html[data-og-ready]",
        cache_key=cache_key,
    )
    if not png:
        return redirect(f"{request.host_url.rstrip('/')}/static/BR_Logo.png")
    return Response(png, mimetype="image/png",
                    headers={"Cache-Control": "public, max-age=3600"})


@app.route("/<platform>/<int:season>/<league_id>/breakouts")
def page_breakouts(platform: str, season: int, league_id: str):
    """Dedicated page for breakout candidates with detailed projections."""
    user_id = session.get("viewer_username")
    has_premium = has_premium_for_viewer(user_id, session.get("viewer_user_id"), league_id, platform, season)

    # Breakout predictions are always for the UPCOMING NFL season, not the
    # Sleeper league's season number (which lags by one year in the offseason).
    # Use the latest season for which breakout data actually exists in the DB,
    # falling back to max(league_season, current_year).
    try:
        from dashboard_services.breakout_api import get_conn as _bo_conn
        with _bo_conn() as _bc:
            with _bc.cursor() as _bcur:
                _bcur.execute("SELECT MAX(season) FROM breakout_opportunity_scores")
                _bo_row = _bcur.fetchone()
                bo_season = int((_bo_row or {}).get("max") or _bo_row[0] or season)
    except Exception:
        bo_season = max(season, datetime.now().year)

    body_html = f"""
    <div class="card central">
      <div class="card-header">
        <h2>Breakout Engine</h2>
        <div style="font-size: 14px; color: var(--text-muted); margin-top: 4px;">
          Players positioned for breakouts based on opportunity, efficiency, and roster changes
        </div>
      </div>
      <div class="card-body">
        <!-- Position Filter -->
        <div style="display: flex; gap: 8px; margin-bottom: 20px; flex-wrap: wrap;">
          <button class="breakout-filter-btn active" data-position="ALL" onclick="filterBreakouts('ALL')">All Positions</button>
          <button class="breakout-filter-btn" data-position="QB" onclick="filterBreakouts('QB')">QB</button>
          <button class="breakout-filter-btn" data-position="RB" onclick="filterBreakouts('RB')">RB</button>
          <button class="breakout-filter-btn" data-position="WR" onclick="filterBreakouts('WR')">WR</button>
          <button class="breakout-filter-btn" data-position="TE" onclick="filterBreakouts('TE')">TE</button>
        </div>

        <!-- Loading State -->
        <div id="breakoutsLoading" class="player-modal-loading" style="padding: 40px;">
          <div class="loading-spinner"></div>
          <div style="margin-top: 12px;">Loading breakout candidates...</div>
        </div>

        <!-- Breakouts Container -->
        <div id="breakoutsContainer" style="display: none;"></div>

        <!-- Empty State -->
        <div id="breakoutsEmpty" style="display: none; text-align: center; padding: 40px; color: var(--text-muted);">
          <div style="font-size: 24px; margin-bottom: 12px; opacity:0.4;"><i class="fa-solid fa-chart-bar"></i></div>
          <div>No breakout candidates found</div>
        </div>
      </div>
    </div>

    <script>
      const BO_HAS_PREMIUM = {str(has_premium).lower()};
      let breakoutCandidates = [];
      let lockedCount = 0;
      let currentFilter = 'ALL';
      let currentPage = 1;
      const PAGE_SIZE = 12;

      // Fetch breakout candidates on page load (using new BreakoutEngine API)
      fetch('/api/breakout/candidates?season={bo_season}&min_score=50&limit=15&league_id={league_id}&platform={platform}')
        .then(res => res.json())
        .then(data => {{
          breakoutCandidates = (data && data.candidates) || [];
          lockedCount = data.locked_count || 0;
          document.getElementById('breakoutsLoading').style.display = 'none';

          if (breakoutCandidates.length === 0 && lockedCount === 0) {{
            document.getElementById('breakoutsEmpty').style.display = 'block';
          }} else {{
            renderBreakouts();
          }}
        }})
        .catch(err => {{
          console.error('Error loading breakouts:', err);
          document.getElementById('breakoutsLoading').innerHTML = '<div style="color: #ef4444;">Failed to load breakout candidates</div>';
        }});

      function filterBreakouts(position) {{
        currentFilter = position;
        currentPage = 1;
        document.querySelectorAll('.breakout-filter-btn').forEach(btn => {{
          btn.classList.toggle('active', btn.getAttribute('data-position') === position);
        }});
        renderBreakouts();
      }}

      function goToPage(page) {{
        currentPage = page;
        renderBreakouts();
        document.getElementById('breakoutsContainer').scrollIntoView({{ behavior: 'smooth', block: 'start' }});
      }}

      function _boPpgRange(candidate) {{
        const s1 = parseFloat(candidate.season1_ppr || 0);
        const prevPpg = parseFloat(candidate.prev_ppr_ppg || 0);
        if (!s1) return null;
        const modelPpg = s1 / 17;
        // Confidence-adjusted spread - matches the modal formula in app.js
        const conf = Math.min(100, Math.max(30, parseFloat(candidate.confidence_score || 70)));
        const halfSpread = 0.04 + (0.12 - 0.04) * (90 - conf) / 60;
        const highRaw = modelPpg * (1 + halfSpread);
        const high = (prevPpg > 0 && highRaw > prevPpg * 1.25) ? prevPpg * 1.25 : highRaw;
        const isCapped = prevPpg > 0 && highRaw > prevPpg * 1.25;
        const rawLow = isCapped ? high * (1 - halfSpread) : modelPpg * (1 - halfSpread * 0.8);
        const lowFloor = (prevPpg > 0 && rawLow < prevPpg) ? prevPpg : rawLow;
        const low = Math.min(lowFloor, high);
        const midPpg = (low + high) / 2;
        const delta = prevPpg > 0 ? Math.round((midPpg - prevPpg) * 10) / 10 : null;
        return {{
          lowStr:  (Math.round(low  * 10) / 10).toFixed(1),
          highStr: (Math.round(high * 10) / 10).toFixed(1),
          prevPpg: prevPpg > 0 ? (Math.round(prevPpg * 10) / 10).toFixed(1) : null,
          delta,
        }};
      }}

      function _boTopComponent(candidate) {{
        const comps = [
          {{ label: 'Opportunity', val: parseFloat(candidate.opportunity_opened_score || 0), color: '#10b981' }},
          {{ label: 'Readiness',   val: parseFloat(candidate.player_readiness_score || 0),  color: '#8b5cf6' }},
          {{ label: 'Competition', val: parseFloat(candidate.competition_removed_score || 0), color: '#3b82f6' }},
          {{ label: 'Role Trend',  val: parseFloat(candidate.role_trajectory_score || 0),    color: '#f59e0b' }},
        ];
        return comps.reduce((best, c) => c.val > best.val ? c : best, comps[0]);
      }}

      function renderBreakouts() {{
        const container = document.getElementById('breakoutsContainer');
        const filtered = currentFilter === 'ALL'
          ? breakoutCandidates
          : breakoutCandidates.filter(c => c.position === currentFilter);

        if (!BO_HAS_PREMIUM) {{
          // Non-premium: API already returned only 3 preview candidates + lockedCount
          const hasContent = filtered.length > 0 || lockedCount > 0;
          if (!hasContent) {{
            document.getElementById('breakoutsEmpty').style.display = 'block';
            container.style.display = 'none';
            return;
          }}
          document.getElementById('breakoutsEmpty').style.display = 'none';
          container.style.display = 'block';
          let html = '<div class="breakout-grid">';
          filtered.forEach(candidate => {{ html += renderBreakoutCard(candidate); }});
          if (lockedCount > 0) {{
            html += `
              <div class="breakout-card" onclick="showPaywall('breakout-candidates')" style="cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;min-height:180px;border:2px dashed var(--border);">
                <i class="fa-solid fa-lock" style="font-size:22px;color:var(--text-muted);"></i>
                <div style="font-weight:700;font-size:15px;">${{lockedCount}} more candidates locked</div>
                <div style="font-size:12px;color:var(--text-muted);text-align:center;">Upgrade to PRO to see all breakout<br>candidates with full details</div>
                <span style="font-size:11px;font-weight:700;padding:4px 12px;background:linear-gradient(135deg,#667eea,#764ba2);color:white;border-radius:12px;">Upgrade &rarr;</span>
              </div>`;
          }}
          html += '</div>';
          container.innerHTML = html;
          return;
        }}

        if (filtered.length === 0) {{
          document.getElementById('breakoutsEmpty').style.display = 'block';
          container.style.display = 'none';
          return;
        }}

        document.getElementById('breakoutsEmpty').style.display = 'none';
        container.style.display = 'block';

        // Premium: paginate
        const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
        currentPage = Math.max(1, Math.min(currentPage, totalPages));
        const start = (currentPage - 1) * PAGE_SIZE;
        const visible = filtered.slice(start, start + PAGE_SIZE);

        let html = '<div class="breakout-grid">';
        visible.forEach(candidate => {{ html += renderBreakoutCard(candidate); }});
        html += '</div>';

        // Pagination controls
        if (totalPages > 1) {{
          html += '<div class="bo-pagination">';
          html += `<button class="bo-page-btn" onclick="goToPage(${{currentPage - 1}})" ${{currentPage === 1 ? 'disabled' : ''}}>&#8249;</button>`;
          for (let i = 1; i <= totalPages; i++) {{
            html += `<button class="bo-page-btn ${{i === currentPage ? 'active' : ''}}" onclick="goToPage(${{i}})">${{i}}</button>`;
          }}
          html += `<button class="bo-page-btn" onclick="goToPage(${{currentPage + 1}})" ${{currentPage === totalPages ? 'disabled' : ''}}>&#8250;</button>`;
          html += `<span class="bo-page-info">${{start + 1}}–${{Math.min(start + PAGE_SIZE, filtered.length)}} of ${{filtered.length}}</span>`;
          html += '</div>';
        }}

        container.innerHTML = html;
      }}

      function renderBreakoutCard(candidate) {{
          const name = candidate.player_name || 'Unknown';
          const team = candidate.team || '?';
          const pos = candidate.position || '?';
          const age = candidate.age ? parseFloat(candidate.age).toFixed(0) : '-';
          const score = parseFloat(candidate.breakout_opportunity_score || 0).toFixed(1);
          const pid = candidate.player_id || '';
          const hitProb = candidate.hit_probability != null ? Math.round(parseFloat(candidate.hit_probability) * 100) : null;

          let scoreColor = '#10b981';
          if (score < 65) scoreColor = '#3b82f6';
          if (score < 55) scoreColor = '#f59e0b';

          const range = _boPpgRange(candidate);
          const topComp = _boTopComponent(candidate);

          const reasons = (candidate.key_reasons || '').split('\\n')
            .filter(r => r.trim() && r.startsWith('•'))
            .map(r => r.substring(1).trim());
          const topReason = reasons[0] || '';

          const ppgHtml = range
            ? `<div style="font-size:22px;font-weight:800;letter-spacing:-0.5px;color:var(--text);line-height:1;">
                 ${{range.lowStr}}–${{range.highStr}}
                 <span style="font-size:13px;font-weight:500;color:var(--text-muted);">PPG</span>
               </div>
               ${{range.prevPpg ? `<div style="font-size:11px;color:var(--text-muted);margin-top:3px;display:flex;align-items:center;gap:5px;">
                 <span>vs ${{range.prevPpg}} last season</span>
                 ${{range.delta !== null ? `<span style="font-weight:700;color:${{range.delta >= 0 ? '#10b981' : '#f59e0b'}};">${{range.delta >= 0 ? '↑ +' : '↓ '}}${{Math.abs(range.delta).toFixed(1)}}</span>` : ''}}
               </div>` : ''}}`
            : `<div style="font-size:13px;color:var(--text-muted);font-style:italic;">No projection available</div>`;

          const hitHtml = hitProb != null
            ? `<div style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;background:${{scoreColor}}22;border:1px solid ${{scoreColor}}44;font-size:11px;font-weight:700;color:${{scoreColor}};">
                 ${{hitProb}}% hit prob
               </div>`
            : '';

          const barFill = Math.min(100, Math.max(0, topComp.val));
          return `
            <div class="breakout-card" style="cursor:pointer;" onclick="openPlayerModal('` + pid + `', '` + name + `', {{tab:'breakout'}})">
              <div class="breakout-card-header">
                <div>
                  <div class="breakout-player-name">` + name + `</div>
                  <div class="breakout-player-meta" style="font-size:12px;color:var(--text-muted);margin-top:2px;">${{age}} yr • ${{team}} • ${{pos}}</div>
                </div>
                <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;">
                  <div class="breakout-score-badge" style="background:${{scoreColor}};color:#fff;font-size:13px;font-weight:700;padding:3px 9px;border-radius:6px;">${{score}}</div>
                  ${{hitHtml}}
                </div>
              </div>
              <div style="margin-bottom:12px;">${{ppgHtml}}</div>
              <div style="margin-bottom:10px;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                  <span style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.5px;">Top Driver: ${{topComp.label}}</span>
                  <span style="font-size:11px;font-weight:700;color:${{topComp.color}};">${{topComp.val.toFixed(1)}}</span>
                </div>
                <div style="height:5px;background:var(--border-color);border-radius:3px;overflow:hidden;">
                  <div style="height:100%;width:${{barFill}}%;background:${{topComp.color}};border-radius:3px;transition:width 0.3s;"></div>
                </div>
              </div>
              ${{topReason ? `<div style="font-size:11px;color:var(--text-muted);line-height:1.4;border-top:1px solid var(--border-color);padding-top:8px;">${{topReason}}</div>` : ''}}
            </div>`;
      }}
    </script>
    """
    return render_page("Breakout Engine", league_id, "breakouts", body_html, platform, season)


