# ── Live draft sync (P5, Sleeper) ────────────────────────────────────────────
def _order_from_sleeper(draft: dict) -> str:
    """Map a Sleeper draft's type + reversal_round to our order_format."""
    dtype = str((draft or {}).get("type") or "snake").lower()
    if dtype == "linear":
        return "linear"
    rev = ((draft or {}).get("settings") or {}).get("reversal_round")
    try:
        if int(rev or 0) == 3:
            return "3rr"
    except (TypeError, ValueError):
        pass
    return "snake"


@app.route("/api/draft/detect")
def api_draft_detect():
    """List drafts for a league so the user can connect a live draft (Sleeper)."""
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or datetime.now().year)
    if not league_id:
        return jsonify({"drafts": [], "error": "league_required"})
    if platform != "sleeper":
        return jsonify({"drafts": [], "unsupported": True})
    out = []
    try:
        drafts = get_drafts(platform, league_id, season) or []
        for d in drafts:
            settings = d.get("settings") or {}
            out.append({
                "draft_id": str(d.get("draft_id") or ""),
                "status": d.get("status"),
                "type": d.get("type"),
                "season": d.get("season"),
                "teams": settings.get("teams"),
                "rounds": settings.get("rounds"),
                "order": _order_from_sleeper(d),
            })
    except Exception as exc:
        logger.warning("[draft-detect] error: %s", exc)
    return jsonify({"drafts": out})


@app.route("/api/draft/live")
def api_draft_live():
    """Current state + picks for a Sleeper draft (polled by the live board)."""
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    draft_id = (request.args.get("draft_id") or "").strip()
    if not draft_id or platform != "sleeper":
        return jsonify({"error": "unsupported"}), 400
    try:
        from dashboard_services.api import get_draft as _gd, get_draft_picks as _gdp
        draft = _gd(draft_id) or {}
        picks_raw = _gdp(draft_id) or []
    except Exception as exc:
        logger.warning("[draft-live] error: %s", exc)
        return jsonify({"error": "fetch_failed"}), 502
    settings = draft.get("settings") or {}
    picks = []
    for p in picks_raw:
        meta = p.get("metadata") or {}
        nm = (str(meta.get("first_name") or "") + " " + str(meta.get("last_name") or "")).strip()
        picks.append({
            "pick_no": p.get("pick_no"),
            "round": p.get("round"),
            "draft_slot": p.get("draft_slot"),
            "player_id": str(p.get("player_id") or ""),
            "name": nm or (meta.get("player_name") or "Unknown"),
            "position": (meta.get("position") or "").upper(),
            "team": meta.get("team") or "",
        })

    # Map draft slot -> team/owner display name (so the board shows real names).
    slot_names = {}
    draft_order = draft.get("draft_order") or {}     # {user_id: slot}
    try:
        _lid = draft.get("league_id")
        _season = int(draft.get("season") or season or datetime.now().year)
        if _lid and draft_order:
            _users = get_users(platform, _lid, _season) or []
            _by_uid = {str(u.get("user_id")): u for u in _users}
            for _uid, _slot in draft_order.items():
                _u = _by_uid.get(str(_uid)) or {}
                _name = ((_u.get("metadata") or {}).get("team_name")
                         or _u.get("display_name") or ("Team " + str(_slot)))
                slot_names[str(_slot)] = _name
    except Exception as _e_sn:
        logger.info("[draft-live] slot names skipped: %s", _e_sn)

    return jsonify({
        "status": draft.get("status"),
        "type": draft.get("type"),
        "teams": settings.get("teams"),
        "rounds": settings.get("rounds"),
        "order": _order_from_sleeper(draft),
        "draft_order": draft_order,
        "slot_names": slot_names,
        "picks": picks,
    })


_TEAMS_BUILDING: set = set()
_TEAMS_BUILDING_LOCK = threading.Lock()


def _background_build_teams(platform: str, league_id: str, season: int) -> None:
    import logging as _log
    _logger = _log.getLogger(__name__)
    build_key = f"{platform}:{season}:{league_id}"
    try:
        t0 = time.time()
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        _logger.info("Teams context ready in %.1fs, building HTML", time.time() - t0)
        body_html = build_teams_body(ctx)
        store_page_html(platform, season, league_id, "teams", body_html)
        _logger.info("Teams build complete in %.1fs", time.time() - t0)
    except Exception as exc:  # noqa: BLE001
        _log.getLogger(__name__).error("Background teams build failed: %s", exc, exc_info=True)
    finally:
        with _TEAMS_BUILDING_LOCK:
            _TEAMS_BUILDING.discard(build_key)


def _build_teams_skeleton(platform: str, season: int, league_id: str, num_teams: int) -> str:
    def _sk_row(w1, w2, w3, w4, w5, bar_pct):
        return (
            f"<tr>"
            f"<td><div class='sk-shimmer' style='width:{w1}px;height:11px;border-radius:3px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:{w2}px;height:11px;border-radius:3px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:{w3}px;height:11px;border-radius:3px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:{w4}px;height:11px;border-radius:3px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:{w5}px;height:11px;border-radius:3px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:{bar_pct}%;height:8px;border-radius:4px;'></div></td>"
            f"<td><div class='sk-shimmer' style='width:24px;height:11px;border-radius:3px;'></div></td>"
            f"</tr>"
        )
    table_rows = "".join([
        _sk_row(22, 12, 36, 32, 16, 72),
        _sk_row(22, 12, 42, 36, 16, 58),
        _sk_row(22, 12, 38, 30, 16, 65),
        _sk_row(22, 12, 30, 28, 16, 45),
        _sk_row(28, 12, 24, 22, 16, 30),
    ])
    shimmer_card = f"""
    <div class="card team-strength-card teams-sk-card">
      <div class="card-header-row">
        <div style="display:flex;align-items:center;gap:8px;min-width:0;flex:1;">
          <div class="sk-shimmer" style="width:32px;height:32px;border-radius:50%;flex-shrink:0;"></div>
          <div class="sk-shimmer" style="width:125px;height:15px;border-radius:4px;"></div>
          <div class="sk-shimmer" style="width:72px;height:12px;border-radius:4px;opacity:0.7;"></div>
        </div>
        <div style="display:flex;align-items:center;gap:6px;flex-shrink:0;">
          <div class="sk-shimmer" style="width:38px;height:24px;border-radius:6px;"></div>
          <div class="sk-shimmer" style="width:22px;height:22px;border-radius:4px;"></div>
        </div>
      </div>
      <div class="card-body">
        <div class="sk-shimmer" style="width:100%;height:120px;border-radius:6px;margin-bottom:14px;"></div>
        <div class="pos-table-wrap">
          <table class="pos-strength-table">
            <thead>
              <tr>
                <th><div class="sk-shimmer" style="width:22px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:10px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:32px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:30px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:10px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:50px;height:9px;border-radius:3px;"></div></th>
                <th><div class="sk-shimmer" style="width:24px;height:9px;border-radius:3px;"></div></th>
              </tr>
            </thead>
            <tbody>{table_rows}</tbody>
          </table>
        </div>
      </div>
    </div>"""
    cards_html = shimmer_card * max(num_teams, 4)
    return f"""
    <div class="page-layout teams-page">
      <main class="page-main">
        <div class="teams-topbar">
          <div class="teams-sort-bar">
            <span style="font-size:12px;color:var(--text-muted);margin-right:8px;">Sort by:</span>
            <button class="teams-sort-btn active" disabled>Positional Index</button>
            <button class="teams-sort-btn" disabled>Team Grade</button>
            <button class="teams-sort-btn" disabled>Archetype</button>
          </div>
          <div class="teams-loading-indicator" id="teams-sk-status">
            <div class="loading-spinner" style="width:14px;height:14px;"></div>
            <span>Building team rankings&hellip;</span>
          </div>
        </div>
        <div class="teams-grid">
          {cards_html}
        </div>
      </main>
    </div>
    <script>
    (function() {{
      var polls = 0;
      var indicator = document.getElementById('teams-sk-status');
      function check() {{
        polls++;
        fetch('/api/teams-ready?platform={platform}&league_id={league_id}&season={season}')
          .then(function(r) {{ return r.json(); }})
          .then(function(d) {{
            if (d.ready) {{
              window.location.href = window.location.pathname + '?_r=' + Date.now();
            }} else {{
              setTimeout(check, polls < 10 ? 1500 : 2500);
            }}
          }})
          .catch(function() {{ setTimeout(check, 3000); }});
      }}
      setTimeout(check, 1500);
    }})();
    </script>
    """


@app.route("/api/teams-ready")
def api_teams_ready():
    platform  = request.args.get("platform", "sleeper")
    league_id = request.args.get("league_id", "")
    try:
        season = int(request.args.get("season", datetime.now().year))
    except (TypeError, ValueError):
        season = datetime.now().year
    ready = bool(get_page_html_from_cache(platform, season, league_id, "teams"))
    return jsonify({"ready": ready})


@app.route("/<platform>/<int:season>/<league_id>/teams")
def page_teams(platform: str, season: int, league_id: str):
    cached = get_page_html_from_cache(platform, season, league_id, "teams")
    if cached:
        return render_page("BR Fantasy Teams", league_id, "teams", cached, platform, season)

    # If the league context is already warm (user visited any other page), build
    # synchronously right now - takes ~1-2s and skips the whole skeleton/polling dance.
    ctx_entry = DASHBOARD_CACHE.get(_cache_key(platform, season, league_id))
    if ctx_entry and (time.time() - ctx_entry.get("ts", 0) <= CACHE_TTL):
        try:
            body_html = build_teams_body(ctx_entry["ctx"])
            store_page_html(platform, season, league_id, "teams", body_html)
            return render_page("BR Fantasy Teams", league_id, "teams", body_html, platform, season)
        except Exception as exc:
            import logging as _log
            _log.getLogger(__name__).error("Sync teams build failed: %s", exc, exc_info=True)

    # Cold load - kick off background build and show skeleton while it runs.
    # The /tmp file written by store_page_html is visible to all gunicorn workers
    # so whichever worker handles the poll will see it as ready.
    build_key = f"{platform}:{season}:{league_id}"
    with _TEAMS_BUILDING_LOCK:
        if build_key not in _TEAMS_BUILDING:
            _TEAMS_BUILDING.add(build_key)
            threading.Thread(
                target=_background_build_teams,
                args=(platform, league_id, season),
                daemon=True,
            ).start()

    num_teams = int((ctx_entry or {}).get("ctx", {}).get("total_rosters") or 12) if ctx_entry else 12
    skeleton = _build_teams_skeleton(platform, season, league_id, num_teams)
    resp = make_response(render_page("BR Fantasy Teams", league_id, "teams", skeleton, platform, season))
    resp.headers["Cache-Control"] = "no-store"
    return resp


def _ens(career_owners: dict, uid: str) -> None:
    """Ensure uid exists in career_owners with all default fields."""
    career_owners.setdefault(uid, {
        "Wins": 0, "Losses": 0, "Ties": 0,
        "PF": 0.0, "PA": 0.0, "seasons": 0, "weekly_pts": [],
    })


def _collect_all_season_data(platform: str, league_id: str, season: int):
    """
    Load ctx for every available historical season and return aggregated data:
      career_owners  – dict  user_id -> {Wins, Losses, Ties, PF, PA, seasons, weekly_pts}
      championships  – dict  user_id -> [season, ...]
      season_records – list  of per-season summary dicts
      user_id_to_name – dict user_id -> latest display name (for rendering)
    Keyed by user_id (stable) rather than team name (changes across seasons).
    """
    cached = get_awards_agg_from_cache(platform, season, league_id)
    if cached is not None:
        return cached

    available = get_available_history_seasons(platform, league_id, season)
    career_owners: dict = {}
    championships: dict = {}
    season_records: list = []
    user_id_to_name: dict = {}  # user_id → latest known display name

    for hist_s in available:
        rid = resolve_league_id_for_season(platform, league_id, season, hist_s)
        try:
            ctx = get_league_ctx_from_cache(platform, rid, hist_s)
        except Exception:
            continue

        df = ctx.get("df_weekly", pd.DataFrame())
        if df.empty or "owner" not in df.columns:
            continue

        # Build user_id → display_name for this season (later seasons overwrite earlier)
        season_users = ctx.get("users") or []
        for u in season_users:
            uid = str(u.get("user_id") or "").strip()
            if not uid:
                continue
            metadata = u.get("metadata") or {}
            name = (
                u.get("display_name")  # Prioritize actual username
                or metadata.get("team_name")  # Fall back to team name
                or metadata.get("username")  # Check username in metadata too
                or u.get("username")
                or uid
            )
            user_id_to_name[uid] = name

        # roster_id → user_id for this season
        season_rosters = ctx.get("rosters") or []
        roster_map = ctx.get("roster_map") or {}
        roster_to_uid: dict[str, str] = {
            str(r["roster_id"]): str(r.get("owner_id") or "")
            for r in season_rosters
        }
        # team_name → user_id reverse lookup (for championship mapping)
        name_to_uid: dict[str, str] = {
            roster_map.get(str(r["roster_id"]), ""): str(r.get("owner_id") or "")
            for r in season_rosters
        }

        # df_weekly has roster_id column - use it as the stable team key.
        # Team names can collide in larger leagues, which can hide/merge users.
        has_roster_id = "roster_id" in df.columns
        df_for_stats = df
        if has_roster_id:
            df_for_stats = df.copy()
            df_for_stats["owner"] = df_for_stats["roster_id"].astype(str)

        mock_league = ctx.get("league") or {}
        ts = build_regular_season_team_stats(df_for_stats, mock_league)

        for _, row in ts.iterrows():
            owner_key = str(row.get("owner", "Unknown"))
            if has_roster_id:
                uid = roster_to_uid.get(owner_key) or owner_key
            else:
                # Fallback path when roster_id is unavailable.
                uid = name_to_uid.get(owner_key) or owner_key
            if uid not in career_owners:
                career_owners[uid] = {
                    "Wins": 0, "Losses": 0, "Ties": 0,
                    "PF": 0.0, "PA": 0.0, "seasons": 0,
                    "weekly_pts": [],
                }
            career_owners[uid]["Wins"]   += int(row.get("Wins", 0))
            career_owners[uid]["Losses"] += int(row.get("Losses", 0))
            career_owners[uid]["Ties"]   += int(row.get("Ties", 0))
            career_owners[uid]["PF"]     += float(row.get("PF", 0))
            career_owners[uid]["PA"]     += float(row.get("PA", 0))
            career_owners[uid]["seasons"] += 1

        # Collect weekly scores per user_id
        sub_cols = ["owner", "points"] + (["roster_id"] if "roster_id" in df.columns else [])
        if {"owner", "points", "finalized"}.issubset(df.columns):
            sub = df[df["finalized"] == True][sub_cols].copy()
        elif {"owner", "points"}.issubset(df.columns):
            sub = df[sub_cols].copy()
        else:
            sub = pd.DataFrame()
        group_col = "roster_id" if has_roster_id and "roster_id" in sub.columns else "owner"
        for owner_key, grp in sub.groupby(group_col):
            if group_col == "roster_id":
                uid = roster_to_uid.get(str(owner_key)) or str(owner_key)
            else:
                uid = name_to_uid.get(str(owner_key)) or str(owner_key)
            career_owners.setdefault(uid, {
                "Wins": 0, "Losses": 0, "Ties": 0,
                "PF": 0.0, "PA": 0.0, "seasons": 0, "weekly_pts": [],
            })["weekly_pts"].extend(grp["points"].tolist())

        # ── Barely Breathing: wins by <5 pts ───────────────────────────────
        if {"owner", "points", "points_against"}.issubset(df.columns):
            margins = (df["points"] - df["points_against"]).astype(float)
            close_win_mask = (margins > 0) & (margins < 5)
            for owner, grp in df[close_win_mask].groupby("owner"):
                uid = name_to_uid.get(str(owner)) or str(owner)
                _ens(career_owners, uid)
                career_owners[uid]["close_wins"] = career_owners[uid].get("close_wins", 0) + len(grp)

        # ── Playoff Riser: avg pts regular season vs playoffs ──────────────
        _league_settings = mock_league.get("settings") or {}
        _po_start = int(_league_settings.get("playoff_week_start") or 15)
        if {"owner", "week", "points"}.issubset(df.columns):
            _reg = df[df["week"] < _po_start]
            _po = df[df["week"] >= _po_start]
            for owner, reg_grp in _reg.groupby("owner"):
                uid = name_to_uid.get(str(owner)) or str(owner)
                po_grp = _po[_po["owner"] == owner]
                if reg_grp.empty or po_grp.empty:
                    continue
                reg_avg = float(reg_grp["points"].mean())
                po_avg = float(po_grp["points"].mean())
                _ens(career_owners, uid)
                career_owners[uid]["playoff_delta_sum"] = career_owners[uid].get("playoff_delta_sum", 0.0) + (po_avg - reg_avg)
                career_owners[uid]["playoff_delta_n"] = career_owners[uid].get("playoff_delta_n", 0) + 1

        # ── Transactions: Main Character + Waiver Wire Demon ───────────────
        try:
            from dashboard_services.service import get_transactions_by_week as _gtxw
            _tx_data = _gtxw(rid, list(range(1, 19)), platform=platform, season=hist_s)
            for _week_txs in _tx_data.values():
                for _t in (_week_txs or []):
                    _ttype = _t.get("type")
                    if _ttype in ("waiver", "waiver_add", "free_agent"):
                        _adds = _t.get("adds") or {}
                        for _pid, _rid_t in _adds.items():
                            _uid = roster_to_uid.get(str(_rid_t), "")
                            if _uid:
                                _ens(career_owners, _uid)
                                career_owners[_uid]["waiver_adds"] = career_owners[_uid].get("waiver_adds", 0) + 1
                                career_owners[_uid]["activity"] = career_owners[_uid].get("activity", 0) + 1
                    elif _ttype == "trade":
                        _trade_rids = set(str(r) for r in (_t.get("roster_ids") or []))
                        _trade_rids |= {str(v) for v in (_t.get("adds") or {}).values()}
                        for _rid_t in _trade_rids:
                            _uid = roster_to_uid.get(_rid_t, "")
                            if _uid:
                                _ens(career_owners, _uid)
                                career_owners[_uid]["trade_count"] = career_owners[_uid].get("trade_count", 0) + 1
                                career_owners[_uid]["activity"] = career_owners[_uid].get("activity", 0) + 2
        except Exception as _e:
            pass  # transaction data unavailable; skip these awards

        # ── Bench Warmer MVP: points left on bench ─────────────────────────
        try:
            from dashboard_services.platform_api import get_matchups as _gmu
            from concurrent.futures import ThreadPoolExecutor as _BW_TPE

            def _fetch_bw_week(_w):
                try:
                    return _w, _gmu(platform, rid, _w, hist_s) or []
                except Exception:
                    return _w, []

            _bw_weeks = list(range(1, _po_start))
            with _BW_TPE(max_workers=min(len(_bw_weeks), 8)) as _bw_pool:
                _bw_results = dict(_bw_pool.map(_fetch_bw_week, _bw_weeks))

            for _w_mus in _bw_results.values():
                for _mu in _w_mus:
                    _roster_id = str(_mu.get("roster_id", ""))
                    _uid = roster_to_uid.get(_roster_id, "")
                    if not _uid:
                        continue
                    _starters = {str(s) for s in (_mu.get("starters") or []) if s and str(s) != "0"}
                    _all_pts = _mu.get("players_points") or {}
                    _bench = sum(float(p) for pid, p in _all_pts.items() if str(pid) not in _starters and str(pid) != "0")
                    _ens(career_owners, _uid)
                    career_owners[_uid]["bench_pts"] = career_owners[_uid].get("bench_pts", 0.0) + _bench
        except Exception as _e:
            pass  # matchup data unavailable; skip bench award

        champ_name, runner_up_name = get_champion_and_runner_up(ctx)
        champ_uid = name_to_uid.get(champ_name) or champ_name
        runner_up_uid = name_to_uid.get(runner_up_name) or runner_up_name
        if champ_name != "–":
            championships.setdefault(champ_uid, []).append(hist_s)

        summary = _build_history_summary(ctx)
        season_records.append({
            "season": hist_s,
            "champion": champ_name,
            "champion_uid": champ_uid,
            "runner_up": runner_up_name,
            "runner_up_uid": runner_up_uid,
            "champion_record": summary.get("champion_record", "–"),
            "top_pf_team": summary.get("top_scorer_team", "–"),
            "top_pf": float(summary.get("top_scorer_value") or 0),
            "highest_week_team": summary.get("highest_week_team", "–"),
            "highest_week_value": float(summary.get("highest_week_value") or 0),
            "closest_matchup": summary.get("closest_matchup", "–"),
            "closest_margin": float(summary.get("closest_margin") or 0),
        })

    payload = (available, career_owners, championships, season_records, user_id_to_name)
    store_awards_agg(platform, season, league_id, payload)
    return payload


def _build_awards_html(career_owners: dict, championships: dict, season_records: list, user_id_to_name: Optional[dict] = None, platform: str = "", season: int = 0, league_id: str = "", league_name: str = "") -> str:
    """Render the All-Time Awards page body HTML."""
    name_map = user_id_to_name or {}

    def _display_name(uid: str) -> str:
        return name_map.get(uid) or uid


    # Build career standings DataFrame
    rows = []
    for uid, d in career_owners.items():
        games = d["Wins"] + d["Losses"] + d["Ties"]
        pts = d["weekly_pts"]
        n = len(pts)
        mean = sum(pts) / n if n > 0 else 0.0
        variance = sum((x - mean) ** 2 for x in pts) / (n - 1) if n > 1 else 0.0
        std = variance ** 0.5
        delta_n = d.get("playoff_delta_n", 0)
        rows.append({
            "owner": uid,
            "display_name": _display_name(uid),
            "Championships": len(championships.get(uid, [])),
            "Wins": d["Wins"],
            "Losses": d["Losses"],
            "PF": d["PF"],
            "PA": d["PA"],
            "Win%": d["Wins"] / games if games > 0 else 0.0,
            "AVG": d["PF"] / games if games > 0 else 0.0,
            "MAX": max(pts) if pts else 0.0,
            "Seasons": d["seasons"],
            "STD": std,
            "CloseWins": d.get("close_wins", 0),
            "BenchPts": d.get("bench_pts", 0.0),
            "WaiverAdds": d.get("waiver_adds", 0),
            "Activity": d.get("activity", 0),
            "PlayoffDelta": d.get("playoff_delta_sum", 0.0) / delta_n if delta_n > 0 else None,
        })

    career_df = pd.DataFrame(rows).sort_values(
        ["Championships", "Wins", "Win%", "PF"],
        ascending=[False, False, False, False],
    ).reset_index(drop=True)

    # ── Render helpers ──────────────────────────────────────────────────────
    _MEDALS = {
        1: '<span class="rank rank-first">1</span>',
        2: '<span class="rank rank-second">2</span>',
        3: '<span class="rank rank-third">3</span>',
    }

    def _rank_badge(i: int) -> str:
        return _MEDALS.get(i, f'<span class="rank-plain">{i}</span>')

    def _record_style(wins: int, losses: int) -> str:
        if wins > losses:
            return "color:#16a34a;font-weight:700;"
        if losses > wins:
            return "color:#ef4444;font-weight:700;"
        return "font-weight:700;"

    def _winpct_bar(pct: float) -> str:
        w = max(2, int(pct * 100))
        color = "#16a34a" if pct >= 0.5 else "#ef4444"
        return f'<div class="winpct-bar"><div class="winpct-fill" style="width:{w}%;background:{color};"></div></div>'

    def _hist_card(label: str, value: str, sub: str = "", icon: str = "") -> str:
        icon_html = f'<div class="history-card-icon">{icon}</div>' if icon else ""
        sub_html = f"<div class='history-card-sub'>{sub}</div>" if sub else ""
        return f"""
        <div class="history-card">
          {icon_html}
          <div class="history-card-label">{label}</div>
          <div class="history-card-value">{value}</div>
          {sub_html}
        </div>"""

    def _fun_award(title: str, icon: str, winner: str, sub: str, accent: str) -> str:
        return f"""
        <div class="fun-award-item" style="--award-accent:{accent};">
          <div class="fun-award-title">{title}</div>
          <div class="fun-award-icon">{icon}</div>
          <div class="fun-award-winner">{winner}</div>
          <div class="fun-award-sub">{sub}</div>
        </div>"""

    # ── Career standings table ──────────────────────────────────────────────
    table_rows_html = ""
    for i, (_, row) in enumerate(career_df.iterrows()):
        rank = i + 1
        rings = (
            '<i class="fa-solid fa-trophy" style="color:#f59e0b;" aria-hidden="true"></i> ' * int(row["Championships"])
        ) if row["Championships"] > 0 else ""
        rec_style = _record_style(int(row["Wins"]), int(row["Losses"]))
        table_rows_html += f"""
        <tr>
          <td>{_rank_badge(rank)}</td>
          <td>{html.escape(str(row['display_name']))} {rings}</td>
          <td style="font-weight:700;color:var(--accent);">{int(row['Championships'])}</td>
          <td style="{rec_style}">{int(row['Wins'])}-{int(row['Losses'])}</td>
          <td>
            <span>{row['Win%']:.1%}</span>
            {_winpct_bar(row['Win%'])}
          </td>
          <td>{row['PF']:,.1f}</td>
          <td>{row['PA']:,.1f}</td>
          <td>{row['AVG']:.1f}</td>
          <td>{row['MAX']:.1f}</td>
          <td>{int(row['Seasons'])}</td>
        </tr>"""

    standings_table = f"""
    <div class="card">
      <div class="card-header"><h2>All-Time Standings</h2></div>
      <div class="card-body" style="padding-top:0;">
        <div class="history-table-wrap">
          <table class="history-table">
            <thead><tr>
              <th>#</th><th>Team</th><th>Titles</th><th>Record</th>
              <th>Win%</th><th>PF</th><th>PA</th><th>Avg/Wk</th><th>Best Wk</th><th>Seasons</th>
            </tr></thead>
            <tbody>{table_rows_html}</tbody>
          </table>
        </div>
      </div>
    </div>"""

    # ── Championship timeline ───────────────────────────────────────────────
    def _cell(v: str) -> str:
        return html.escape(v) if v and v != "–" else "<span style='color:var(--text-muted)'>–</span>"

    sorted_records = sorted(season_records, key=lambda x: x["season"], reverse=True)
    most_recent_season = sorted_records[0]["season"] if sorted_records else None

    champ_rows_html = ""
    for rec in sorted_records:
        champ_display = _display_name(rec.get("champion_uid") or rec["champion"]) if rec.get("champion_uid") else rec["champion"]
        runner_display = _display_name(rec.get("runner_up_uid") or rec["runner_up"]) if rec.get("runner_up_uid") else rec["runner_up"]
        row_cls = ' class="champ-recent"' if rec["season"] == most_recent_season else ""
        champ_rows_html += f"""
        <tr{row_cls}>
          <td><strong>{rec['season']}</strong></td>
          <td style="font-weight:700;"><i class="fa-solid fa-trophy" style="color:#f59e0b;margin-right:5px;" aria-hidden="true"></i>{_cell(champ_display)}</td>
          <td>{html.escape(rec['champion_record'])}</td>
          <td>{_cell(runner_display)}</td>
        </tr>"""

    champ_table = f"""
    <div class="card champ-history-card">
      <div class="card-header"><h2>Championship History</h2></div>
      <div class="card-body champ-history-body" style="padding-top:0;">
        <div class="history-table-wrap champ-history-scroll">
          <table class="history-table">
            <thead><tr><th>Season</th><th>Champion</th><th>Record</th><th>Runner-Up</th></tr></thead>
            <tbody>{champ_rows_html}</tbody>
          </table>
        </div>
      </div>
    </div>"""

    # ── League Records cards ────────────────────────────────────────────────
    if season_records:
        best_pf_rec = max(season_records, key=lambda x: x["top_pf"])
        best_wk_rec = max(season_records, key=lambda x: x["highest_week_value"])
    else:
        best_pf_rec = best_wk_rec = None

    highlights_html = ""
    if best_pf_rec:
        highlights_html += _hist_card(
            "Highest Season PF",
            html.escape(best_pf_rec["top_pf_team"]),
            f"{best_pf_rec['top_pf']:.1f} pts in {best_pf_rec['season']}",
            '<i class="fa-solid fa-fire" style="color:#f97316;"></i>',
        )
    if best_wk_rec:
        highlights_html += _hist_card(
            "Highest Single Week",
            html.escape(best_wk_rec["highest_week_team"]),
            f"{best_wk_rec['highest_week_value']:.1f} pts in {best_wk_rec['season']}",
            '<i class="fa-solid fa-bolt" style="color:#facc15;"></i>',
        )

    if not career_df.empty and int(career_df.iloc[0]["Championships"]) > 0:
        most_champ_owner = str(career_df.iloc[0]["display_name"])
        most_champ_n = int(career_df.iloc[0]["Championships"])
        highlights_html += _hist_card(
            "Most Championships",
            html.escape(most_champ_owner),
            f"{most_champ_n} title{'s' if most_champ_n > 1 else ''}",
            '<i class="fa-solid fa-trophy" style="color:#f59e0b;"></i>',
        )

    # Best all-time win% (min 2 seasons)
    eligible = career_df[career_df["Seasons"] >= 2]
    if not eligible.empty:
        best_winpct_row = eligible.loc[eligible["Win%"].idxmax()]
        highlights_html += _hist_card(
            "Best Win%",
            html.escape(str(best_winpct_row["display_name"])),
            f"{best_winpct_row['Win%']:.1%} over {int(best_winpct_row['Seasons'])} seasons",
            '<i class="fa-solid fa-chart-line" style="color:#22c55e;"></i>',
        )

    # Most seasons played
    if not career_df.empty:
        most_seasons_row = career_df.loc[career_df["Seasons"].idxmax()]
        highlights_html += _hist_card(
            "Most Seasons",
            html.escape(str(most_seasons_row["display_name"])),
            f"{int(most_seasons_row['Seasons'])} seasons played",
            '<i class="fa-solid fa-calendar-days"></i>',
        )

    # Most points, no ring
    no_titles = career_df[career_df["Championships"] == 0]
    if not no_titles.empty:
        unlucky_row = no_titles.loc[no_titles["PF"].idxmax()]
        highlights_html += _hist_card(
            "Most Points, No Ring",
            html.escape(str(unlucky_row["display_name"])),
            f"{unlucky_row['PF']:,.1f} career points",
            '<i class="fa-solid fa-heart-crack"></i>',
        )

    highlights_section = ""
    if highlights_html:
        highlights_section = f"""
    <div class="card">
      <div class="card-header"><h2>League Records</h2></div>
      <div class="card-body">
        <div class="history-cards-grid awards-records-grid">{highlights_html}</div>
      </div>
    </div>"""

    # ── Fun Awards ──────────────────────────────────────────────────────────
    fun_awards_html = ""

    # The Bridesmaid - most runner-up appearances without a title
    runner_up_counts: dict = {}
    for rec in season_records:
        ru_uid = rec.get("runner_up_uid")
        ru_display = _display_name(ru_uid) if ru_uid else rec.get("runner_up", "")
        if ru_display and ru_display != "–":
            runner_up_counts[ru_display] = runner_up_counts.get(ru_display, 0) + 1
    no_title_names = set(career_df[career_df["Championships"] == 0]["display_name"].astype(str).tolist())
    bridesmaid_candidates = {k: v for k, v in runner_up_counts.items() if k in no_title_names and v >= 1}
    if bridesmaid_candidates:
        bridesmaid_name = max(bridesmaid_candidates, key=bridesmaid_candidates.get)
        bridesmaid_count = bridesmaid_candidates[bridesmaid_name]
        fun_awards_html += _fun_award(
            "The Bridesmaid",
            '<i class="fa-solid fa-ring"></i>',
            html.escape(bridesmaid_name),
            f"{bridesmaid_count}× runner-up, 0 titles",
            "#f59e0b",
        )

    # Most Dominant - best career win% (2+ seasons)
    if not eligible.empty:
        dominant_row = eligible.loc[eligible["Win%"].idxmax()]
        fun_awards_html += _fun_award(
            "Most Dominant",
            '<i class="fa-solid fa-crown"></i>',
            html.escape(str(dominant_row["display_name"])),
            f"{dominant_row['Win%']:.1%} all-time win rate",
            "#f59e0b",
        )

    # The Punching Bag - most PA with a losing record
    losing = career_df[career_df["Losses"] > career_df["Wins"]]
    if not losing.empty:
        punching_bag_row = losing.loc[losing["PA"].idxmax()]
        fun_awards_html += _fun_award(
            "The Punching Bag",
            '<i class="fa-solid fa-dumbbell"></i>',
            html.escape(str(punching_bag_row["display_name"])),
            f"{punching_bag_row['PA']:,.1f} points allowed",
            "#94a3b8",
        )

    # Boom or Bust - highest weekly score std dev
    boom_eligible = career_df[career_df["Seasons"] >= 1].copy()
    if not boom_eligible.empty:
        boom_row = boom_eligible.loc[boom_eligible["STD"].idxmax()]
        fun_awards_html += _fun_award(
            "Boom or Bust",
            '<i class="fa-solid fa-dice"></i>',
            html.escape(str(boom_row["display_name"])),
            f"σ {boom_row['STD']:.1f} pts/week variance",
            "#f97316",
        )

    # Barely Breathing - most wins by <5 points
    if "CloseWins" in career_df.columns and career_df["CloseWins"].sum() > 0:
        close_row = career_df.loc[career_df["CloseWins"].idxmax()]
        if int(close_row["CloseWins"]) > 0:
            fun_awards_html += _fun_award(
                "Barely Breathing",
                '<i class="fa-solid fa-heart-crack"></i>',
                html.escape(str(close_row["display_name"])),
                f"{int(close_row['CloseWins'])} wins by fewer than 5 pts",
                "#ef4444",
            )

    # Consistency King - lowest weekly score std dev (2+ seasons)
    if not eligible.empty:
        consistent_row = eligible.loc[eligible["STD"].idxmin()]
        fun_awards_html += _fun_award(
            "Consistency King",
            '<i class="fa-solid fa-snowflake"></i>',
            html.escape(str(consistent_row["display_name"])),
            f"σ {consistent_row['STD']:.1f} pts/week",
            "#60a5fa",
        )

    # Main Character - most total league activity (trades + pickups)
    if "Activity" in career_df.columns and career_df["Activity"].sum() > 0:
        main_row = career_df.loc[career_df["Activity"].idxmax()]
        if int(main_row["Activity"]) > 0:
            trades = int(main_row.get("Activity", 0) // 3)  # rough trade count from weighted activity
            pickups = int(main_row.get("WaiverAdds", 0))
            fun_awards_html += _fun_award(
                "Main Character",
                '<i class="fa-solid fa-star"></i>',
                html.escape(str(main_row["display_name"])),
                f"{pickups} pickups · {int(main_row['Activity'])} activity pts",
                "#a855f7",
            )

    # Bench Warmer MVP - most career points left on bench
    if "BenchPts" in career_df.columns and career_df["BenchPts"].sum() > 0:
        bench_row = career_df.loc[career_df["BenchPts"].idxmax()]
        if float(bench_row["BenchPts"]) > 0:
            fun_awards_html += _fun_award(
                "Bench Warmer MVP",
                '<i class="fa-solid fa-clipboard-list"></i>',
                html.escape(str(bench_row["display_name"])),
                f"{bench_row['BenchPts']:,.1f} pts left on bench",
                "#64748b",
            )

    # Waiver Wire Demon - most FA/waiver pickups
    if "WaiverAdds" in career_df.columns and career_df["WaiverAdds"].sum() > 0:
        waiver_row = career_df.loc[career_df["WaiverAdds"].idxmax()]
        if int(waiver_row["WaiverAdds"]) > 0:
            fun_awards_html += _fun_award(
                "Waiver Wire Demon",
                '<i class="fa-solid fa-magnifying-glass"></i>',
                html.escape(str(waiver_row["display_name"])),
                f"{int(waiver_row['WaiverAdds'])} career pickups",
                "#22c55e",
            )

    # Playoff Riser - biggest avg pts jump from regular season to playoffs
    po_eligible = career_df[career_df["PlayoffDelta"].notna()].copy() if "PlayoffDelta" in career_df.columns else pd.DataFrame()
    if not po_eligible.empty:
        riser_row = po_eligible.loc[po_eligible["PlayoffDelta"].idxmax()]
        delta = float(riser_row["PlayoffDelta"])
        if delta > 0:
            fun_awards_html += _fun_award(
                "Playoff Riser",
                '<i class="fa-solid fa-arrow-trend-up"></i>',
                html.escape(str(riser_row["display_name"])),
                f"+{delta:.1f} pts/wk in playoffs",
                "#16a34a",
            )

    fun_awards_section = ""
    if fun_awards_html:
        fun_awards_section = f"""
    <div class="card">
      <div class="card-header"><h2>League Superlatives</h2></div>
      <div class="card-body">
        <div class="fun-awards-grid">{fun_awards_html}</div>
      </div>
    </div>"""

    history_url = f"/{platform}/{season}/{league_id}/history" if platform and league_id else "#"

    nav_row = f"""
    <div style="display:flex;justify-content:flex-end;margin-bottom:4px;">
      <a href="{history_url}" class="awards-page-nav-link">
        <i class="fa-solid fa-clipboard-list"></i>
        Season History
      </a>
    </div>"""

    return f"""
    <div class="overview-layout">
      <div class="overview-main">
        {nav_row}
        {highlights_section}
        <div class="awards-two-col">
          {fun_awards_section}
          {champ_table}
        </div>
        {standings_table}
      </div>
    </div>"""


@app.route("/<platform>/<int:season>/<league_id>/awards")
def page_awards(platform: str, season: int, league_id: str):
    cached = get_page_html_from_cache(platform, season, league_id, "awards")
    if cached:
        return render_page("League Awards", league_id, "awards", cached, platform, season)

    available, career_owners, championships, season_records, user_id_to_name = \
        _collect_all_season_data(platform, league_id, season)

    if not available or not career_owners:
        body_html = """
        <div class="card central">
          <div class="card-body">
            <div class="bract-empty-state">
              <div class="bract-empty-title">No History Yet</div>
              <div class="bract-empty-copy">
                All-time awards will appear after your first completed season.
              </div>
            </div>
          </div>
        </div>"""
        store_page_html(platform, season, league_id, "awards", body_html)
        return render_page("League Awards", league_id, "awards", body_html, platform, season)

    try:
        ctx = get_league_ctx_from_cache(platform, league_id, season)
        _league_name = (ctx.get("league") or {}).get("name") or ""
    except Exception:
        _league_name = ""
    body_html = _build_awards_html(
        career_owners, championships, season_records, user_id_to_name,
        platform=platform, season=season, league_id=league_id, league_name=_league_name,
    )
    store_page_html(platform, season, league_id, "awards", body_html)
    return render_page("League Awards", league_id, "awards", body_html, platform, season)


@app.route("/<platform>/<int:season>/<league_id>/history")
def page_history(platform: str, season: int, league_id: str):
    # Tour preview: render with mock data, bypass real league fetch
    if request.args.get("tour"):
        try:
            mock_ctx = _build_tour_mock_history_ctx()
            body_html = build_history_body(
                history_ctx=mock_ctx,
                available_seasons=[datetime.now().year - 1],
                base_platform=platform,
                base_season=season,
                base_league_id=league_id,
                selected_history_season=datetime.now().year - 1,
                resolved_history_league_id="tour_mock",
            )
        except Exception as exc:
            body_html = f"<div class='card central'><div class='card-body'><p>History preview unavailable: {exc}</p></div></div>"
        return render_page("League History", league_id, "history", body_html, platform, season)

    selected_history_season_param = request.args.get("history_season")
    page_cache_key = f"history:{selected_history_season_param}" if selected_history_season_param else "history"
    cached = get_page_html_from_cache(platform, season, league_id, page_cache_key)
    if cached:
        return render_page("League History", league_id, "history", cached, platform, season)

    available_seasons = get_available_history_seasons(platform, league_id, season)

    # Handle first-year league case
    if not available_seasons:
        body_html = """
        <div class="card central">
          <div class="card-body">
            <div class="bract-empty-state">
              <div class="bract-empty-title">Welcome to Your First Season!</div>
              <div class="bract-empty-copy">This is the first year of your league. Historical season data, AI-powered recaps, and year-over-year comparisons will appear here after your current season completes. Check back after championship week!</div>
            </div>
          </div>
        </div>
        """
        return render_page(
            "League History",
            league_id,
            "history",
            body_html,
            platform,
            season,
        )

    default_history_season = get_default_history_season(available_seasons, season)

    selected_history_season = int(
        request.args.get("history_season") or default_history_season
    )

    if selected_history_season not in available_seasons:
        selected_history_season = default_history_season

    resolved_history_league_id = resolve_league_id_for_season(
        platform=platform,
        league_id=league_id,
        current_season=season,
        target_season=selected_history_season,
    )

    history_ctx = get_league_ctx_from_cache(
        platform,
        resolved_history_league_id,
        selected_history_season,
    )

    body_html = build_history_body(
        history_ctx=history_ctx,
        available_seasons=available_seasons,
        base_platform=platform,
        base_season=season,
        base_league_id=league_id,
        selected_history_season=selected_history_season,
        resolved_history_league_id=resolved_history_league_id,
    )
    store_page_html(platform, season, league_id, page_cache_key, body_html)

    return render_page(
        "League History",
        league_id,
        "history",
        body_html,
        platform,
        season,
    )


# ══════════════════════════════════════════════════════════════════════════════
# OPTIMAL LINEUP TRACKER
# ══════════════════════════════════════════════════════════════════════════════

def _compute_optimal_lineup(pts_map, player_positions, roster_positions, all_pids):
    """
    Greedy optimal-lineup solver.
    Returns (set_of_optimal_starter_ids, optimal_total_pts).
    """
    from collections import defaultdict as _dd
    slot_counts = _dd(int)
    for s in roster_positions:
        slot_counts[str(s).upper()] += 1

    by_pos = _dd(list)
    for pid in all_pids:
        pos = str(player_positions.get(pid) or "").upper()
        by_pos[pos].append((pid, float(pts_map.get(pid) or 0)))
    for pos in by_pos:
        by_pos[pos].sort(key=lambda x: x[1], reverse=True)

    used, starters = set(), []

    # Fill mandatory single-position slots first
    for pos in ["QB", "RB", "WR", "TE", "K", "DEF", "DL", "LB", "DB"]:
        n = slot_counts.get(pos, 0)
        for pid, _ in by_pos[pos]:
            if n <= 0:
                break
            if pid not in used:
                starters.append(pid)
                used.add(pid)
                n -= 1

    # FLEX: RB / WR / TE
    flex_n = slot_counts.get("FLEX", 0)
    flex_pool = sorted(
        [(pid, pts) for pos in ["RB", "WR", "TE"] for pid, pts in by_pos[pos] if pid not in used],
        key=lambda x: x[1], reverse=True
    )
    for pid, _ in flex_pool[:flex_n]:
        starters.append(pid); used.add(pid)

    # SUPER_FLEX / SFLEX: QB / RB / WR / TE
    sf_n = slot_counts.get("SUPER_FLEX", 0) + slot_counts.get("SFLEX", 0)
    sf_pool = sorted(
        [(pid, pts) for pos in ["QB", "RB", "WR", "TE"] for pid, pts in by_pos[pos] if pid not in used],
        key=lambda x: x[1], reverse=True
    )
    for pid, _ in sf_pool[:sf_n]:
        starters.append(pid); used.add(pid)

    opt_set = set(starters)
    opt_pts = sum(float(pts_map.get(pid) or 0) for pid in opt_set)
    return opt_set, round(opt_pts, 2)


_OPT_POS_COLORS = {"QB": "#3b82f6", "RB": "#22c55e", "WR": "#f59e0b", "TE": "#a855f7"}


def _opt_player_badges(players_out: list) -> str:
    parts = []
    for p in players_out:
        if p["actual_start"] == p["optimal_start"]:
            badge_style = "background:var(--surface);border:1px solid var(--border);"
            icon = ""
        elif p["actual_start"] and not p["optimal_start"]:
            badge_style = "background:#ef444420;border:1px solid #ef4444;color:#ef4444;"
            icon = "&#9660; "
        else:
            badge_style = "background:#22c55e20;border:1px solid #22c55e;color:#22c55e;"
            icon = "&#9650; "
        pos_color = _OPT_POS_COLORS.get(p["pos"], "#6b7280")
        parts.append(
            f"<span style='padding:4px 8px;border-radius:6px;font-size:12px;{badge_style}'>"
            f"<span style='color:{pos_color};font-weight:700;'>{p['pos']}</span> "
            f"{html.escape(p['name'])} {icon}<b>{p['pts']:.1f}</b></span>"
        )
    return "".join(parts)


def _opt_pos_breakdown(weeks_data: list) -> str:
    pos_left: dict = {}
    pos_misses: dict = {}
    for wd in weeks_data:
        for p in wd["players"]:
            if not p["actual_start"] and p["optimal_start"]:
                bucket = p["pos"] if p["pos"] in ("QB", "RB", "WR", "TE") else "OTHER"
                pos_left[bucket] = pos_left.get(bucket, 0.0) + p["pts"]
                pos_misses[bucket] = pos_misses.get(bucket, 0) + 1
    if not pos_left:
        return ""
    rows_html = ""
    for pos in ["QB", "RB", "WR", "TE", "OTHER"]:
        if pos not in pos_left:
            continue
        left = round(pos_left[pos], 1)
        misses = pos_misses[pos]
        pos_color = _OPT_POS_COLORS.get(pos, "#6b7280")
        label = "K/DEF/FLEX" if pos == "OTHER" else pos
        rows_html += (
            f"<tr>"
            f"<td style='padding:8px 12px;'><span style='font-weight:700;color:{pos_color};'>{label}</span></td>"
            f"<td style='padding:8px 12px;font-weight:600;color:#ef4444;'>+{left}</td>"
            f"<td style='padding:8px 12px;color:var(--muted);'>{misses}×</td>"
            f"</tr>"
        )
    return (
        "<div class='card' style='margin-top:16px;'>"
        "<div class='card-header'><h3>Points Left by Position</h3></div>"
        "<table style='width:100%;border-collapse:collapse;'>"
        "<thead><tr style='border-bottom:1px solid var(--border);'>"
        "<th style='padding:8px 12px;text-align:left;font-size:11px;color:var(--muted);'>POS</th>"
        "<th style='padding:8px 12px;text-align:left;font-size:11px;color:var(--muted);'>LEFT ON BENCH</th>"
        "<th style='padding:8px 12px;text-align:left;font-size:11px;color:var(--muted);'>MISSED STARTS</th>"
        "</tr></thead>"
        f"<tbody>{rows_html}</tbody>"
        "</table>"
        "</div>"
    )


def build_optimal_body(ctx):
    from dashboard_services.platform_api import get_matchups as _gm

    platform = ctx.get("platform") or "sleeper"
    season   = ctx.get("season") or datetime.now().year
    league_id = ctx.get("league_id") or ""
    viewer_rid = str((ctx.get("viewer") or {}).get("viewer_roster_id") or "")
    roster_positions = ctx.get("roster_positions") or []
    settings  = (ctx.get("league") or {}).get("settings") or {}
    playoff_start = int(settings.get("playoff_week_start") or 14)
    # current_week lives on ctx directly; build_league_context never exposes a
    # "state" key, so reading ctx.get("state") here would pin current_week to 0
    # and make the page render "No completed weeks yet" all season.
    current_week  = int(ctx.get("current_week") or 0)
    players_idx   = get_players_index_global() or {}
    roster_map    = ctx.get("roster_map") or {}
    rosters       = ctx.get("rosters") or []

    view   = request.args.get("view", "user")
    period = request.args.get("period", "season")
    try:
        sel_week = int(request.args.get("week", 0))
    except (ValueError, TypeError):
        sel_week = 0

    max_week = min(current_week - 1, playoff_start - 1)
    if max_week < 1:
        return ("<div style='padding:32px;text-align:center;color:var(--muted);'>"
                "<p>No completed weeks yet. Optimal lineup data will appear here once the season starts.</p>"
                "</div>")

    if sel_week < 1 or sel_week > max_week:
        sel_week = max_week

    base_url = f"/{platform}/{season}/{league_id}/optimal"

    # ── Navigation ────────────────────────────────────────────────────────────
    def _tab(label, tv, tp, active):
        wk = f"&week={sel_week}" if tp == "weekly" else ""
        cls = "opt-tab active" if active else "opt-tab"
        return f"<a class='{cls}' href='{base_url}?view={tv}&period={tp}{wk}'>{label}</a>"

    week_opts = "".join(
        f"<option value='{w}'{' selected' if w == sel_week else ''}>Week {w}</option>"
        for w in range(1, max_week + 1)
    )
    week_picker = (
        f"<select class='opt-week-select' "
        f"onchange=\"window.location='{base_url}?view={view}&period=weekly&week='+this.value\">"
        f"{week_opts}</select>"
    ) if period == "weekly" else ""

    nav_html = (
        "<div class='opt-nav'>"
        f"  <div class='opt-tab-group'>"
        f"    {_tab('My Team', 'user', period, view == 'user')}"
        f"    {_tab('League', 'league', period, view == 'league')}"
        f"  </div>"
        f"  <div class='opt-tab-group'>"
        f"    {_tab('Season', view, 'season', period == 'season')}"
        f"    {_tab('Weekly', view, 'weekly', period == 'weekly')}"
        f"  </div>"
        f"  {week_picker}"
        "</div>"
    )

    # ── Fetch only the weeks this view actually needs ─────────────────────────
    # Weekly views need exactly one week; season views need all completed weeks.
    weeks_to_fetch = [sel_week] if period == "weekly" else list(range(1, max_week + 1))

    def _fetch_opt_week(w):
        try:
            return w, _gm(platform, league_id, w, season) or []
        except Exception:
            return w, []

    from concurrent.futures import ThreadPoolExecutor as _OPT_TPE
    with _OPT_TPE(max_workers=min(len(weeks_to_fetch), 8)) as _opt_pool:
        all_matchups: dict = dict(_opt_pool.map(_fetch_opt_week, weeks_to_fetch))

    def _roster_weeks(rid: str) -> list:
        weeks = []
        for w in range(1, max_week + 1):
            try:
                row = next((m for m in all_matchups[w] if str(m.get("roster_id")) == str(rid)), None)
                if not row:
                    continue
                starters_raw = [str(p) for p in (row.get("starters") or []) if p and str(p) != "0"]
                all_pids     = [str(p) for p in (row.get("players")  or []) if p and str(p) != "0"]
                pts_map      = {str(k): float(v or 0) for k, v in (row.get("players_points") or {}).items()}
                if not starters_raw or not all_pids:
                    continue
                actual_pts = float(row.get("points") or 0)
                pos_map    = {pid: (players_idx.get(pid) or {}).get("pos") or "" for pid in all_pids}
                opt_set, opt_pts = _compute_optimal_lineup(pts_map, pos_map, roster_positions, all_pids)
                left = round(max(opt_pts - actual_pts, 0), 1)
                starter_set = set(starters_raw)
                players_out = sorted([
                    {
                        "pid": pid,
                        "name": (players_idx.get(pid) or {}).get("name") or pid,
                        "pos":  ((players_idx.get(pid) or {}).get("pos") or "").upper(),
                        "pts":  float(pts_map.get(pid) or 0),
                        "actual_start": pid in starter_set,
                        "optimal_start": pid in opt_set,
                    }
                    for pid in all_pids
                ], key=lambda p: -p["pts"])
                weeks.append({"week": w, "actual_pts": round(actual_pts, 2),
                               "opt_pts": round(opt_pts, 2), "left": left, "players": players_out})
            except Exception:
                continue
        return weeks

    def _wk_table_row(wd: dict) -> str:
        left_color = "#ef4444" if wd["left"] > 15 else ("#f59e0b" if wd["left"] > 7 else "#22c55e")
        badges = _opt_player_badges(wd["players"])
        return (
            f"<tr style='cursor:pointer;' onclick='this.nextElementSibling.style.display="
            f"this.nextElementSibling.style.display===\"none\"?\"table-row\":\"none\"'>"
            f"<td style='padding:10px 12px;font-weight:600;'>Week {wd['week']}</td>"
            f"<td style='padding:10px 12px;'>{wd['actual_pts']}</td>"
            f"<td style='padding:10px 12px;'>{wd['opt_pts']}</td>"
            f"<td style='padding:10px 12px;font-weight:700;color:{left_color};'>+{wd['left']}</td>"
            f"</tr>"
            f"<tr style='display:none;background:var(--surface2);'>"
            f"<td colspan='4' style='padding:12px;'>"
            f"<div style='font-size:12px;color:var(--muted);margin-bottom:8px;'>"
            f"<span style='color:#ef4444'>&#9660; Should have benched</span> &nbsp; "
            f"<span style='color:#22c55e'>&#9650; Should have started</span></div>"
            f"<div style='display:flex;flex-wrap:wrap;gap:6px;'>{badges}</div>"
            f"</td></tr>"
        )

    _TH = "<th style='padding:10px 12px;text-align:left;font-size:11px;color:var(--muted);'>"
    _no_data = ("<div class='card'><div class='card-body' style='padding:24px;text-align:center;"
                "color:var(--muted);'>No data available.</div></div>")

    # ── League season view ────────────────────────────────────────────────────
    if view == "league" and period == "season":
        team_rows = []
        for r in rosters:
            rid = str(r.get("roster_id") or "")
            if not rid:
                continue
            tname = roster_map.get(rid) or f"Team {rid}"
            weeks = _roster_weeks(rid)
            if not weeks:
                continue
            s_actual = sum(w["actual_pts"] for w in weeks)
            s_opt    = sum(w["opt_pts"]    for w in weeks)
            s_left   = round(sum(w["left"] for w in weeks), 1)
            eff = round((s_actual / s_opt * 100) if s_opt else 0, 1)
            team_rows.append({"name": tname, "actual": round(s_actual, 1),
                               "opt": round(s_opt, 1), "left": s_left, "eff": eff})
        team_rows.sort(key=lambda x: -x["eff"])

        rows_html = ""
        for i, tr in enumerate(team_rows):
            eff_color = "#22c55e" if tr["eff"] >= 92 else ("#f59e0b" if tr["eff"] >= 86 else "#ef4444")
            rows_html += (
                f"<tr style='border-bottom:1px solid var(--border);'>"
                f"<td style='padding:10px 12px;color:var(--muted);font-weight:600;'>#{i+1}</td>"
                f"<td style='padding:10px 12px;font-weight:600;'>{html.escape(tr['name'])}</td>"
                f"<td style='padding:10px 12px;font-weight:700;color:{eff_color};'>{tr['eff']}%</td>"
                f"<td style='padding:10px 12px;'>{tr['actual']}</td>"
                f"<td style='padding:10px 12px;'>{tr['opt']}</td>"
                f"<td style='padding:10px 12px;color:#ef4444;font-weight:600;'>+{tr['left']}</td>"
                f"</tr>"
            )
        body_html = (
            f"<div class='card' style='overflow:auto;'>"
            f"<div class='card-header'><h3>League Lineup Efficiency - Season</h3></div>"
            f"<table style='width:100%;min-width:520px;border-collapse:collapse;'>"
            f"<thead><tr style='border-bottom:2px solid var(--border);'>"
            f"{_TH}#</th>{_TH}TEAM</th>{_TH}EFFICIENCY</th>"
            f"{_TH}ACTUAL PTS</th>{_TH}OPTIMAL PTS</th>{_TH}LEFT ON BENCH</th>"
            f"</tr></thead><tbody>{rows_html}</tbody></table></div>"
        ) if team_rows else _no_data
        return nav_html + body_html

    # ── League weekly view ────────────────────────────────────────────────────
    if view == "league" and period == "weekly":
        wk_rows = []
        for r in rosters:
            rid = str(r.get("roster_id") or "")
            if not rid:
                continue
            tname = roster_map.get(rid) or f"Team {rid}"
            row = next((m for m in all_matchups.get(sel_week, []) if str(m.get("roster_id")) == str(rid)), None)
            if not row:
                continue
            try:
                starters_raw = [str(p) for p in (row.get("starters") or []) if p and str(p) != "0"]
                all_pids     = [str(p) for p in (row.get("players")  or []) if p and str(p) != "0"]
                pts_map      = {str(k): float(v or 0) for k, v in (row.get("players_points") or {}).items()}
                if not starters_raw or not all_pids:
                    continue
                actual_pts = float(row.get("points") or 0)
                pos_map    = {pid: (players_idx.get(pid) or {}).get("pos") or "" for pid in all_pids}
                opt_set, opt_pts = _compute_optimal_lineup(pts_map, pos_map, roster_positions, all_pids)
                left = round(max(opt_pts - actual_pts, 0), 1)
                starter_set = set(starters_raw)
                players_out = sorted([
                    {"pid": pid, "name": (players_idx.get(pid) or {}).get("name") or pid,
                     "pos": ((players_idx.get(pid) or {}).get("pos") or "").upper(),
                     "pts": float(pts_map.get(pid) or 0),
                     "actual_start": pid in starter_set, "optimal_start": pid in opt_set}
                    for pid in all_pids
                ], key=lambda p: -p["pts"])
                wk_rows.append({"name": tname, "actual": round(actual_pts, 2),
                                 "opt": round(opt_pts, 2), "left": left, "players": players_out})
            except Exception:
                continue
        wk_rows.sort(key=lambda x: -x["left"])

        rows_html = ""
        for tr in wk_rows:
            left_color = "#ef4444" if tr["left"] > 15 else ("#f59e0b" if tr["left"] > 7 else "#22c55e")
            badges = _opt_player_badges(tr["players"])
            rows_html += (
                f"<tr style='cursor:pointer;border-bottom:1px solid var(--border);' "
                f"onclick='this.nextElementSibling.style.display="
                f"this.nextElementSibling.style.display===\"none\"?\"table-row\":\"none\"'>"
                f"<td style='padding:10px 12px;font-weight:600;'>{html.escape(tr['name'])}</td>"
                f"<td style='padding:10px 12px;'>{tr['actual']}</td>"
                f"<td style='padding:10px 12px;'>{tr['opt']}</td>"
                f"<td style='padding:10px 12px;font-weight:700;color:{left_color};'>+{tr['left']}</td>"
                f"</tr>"
                f"<tr style='display:none;background:var(--surface2);'>"
                f"<td colspan='4' style='padding:12px;'>"
                f"<div style='font-size:12px;color:var(--muted);margin-bottom:8px;'>"
                f"<span style='color:#ef4444'>&#9660; Should have benched</span> &nbsp; "
                f"<span style='color:#22c55e'>&#9650; Should have started</span></div>"
                f"<div style='display:flex;flex-wrap:wrap;gap:6px;'>{badges}</div>"
                f"</td></tr>"
            )
        body_html = (
            f"<div class='card' style='overflow:auto;'>"
            f"<div class='card-header'><h3>Week {sel_week} - League Efficiency</h3></div>"
            f"<table style='width:100%;min-width:520px;border-collapse:collapse;'>"
            f"<thead><tr style='border-bottom:2px solid var(--border);'>"
            f"{_TH}TEAM</th>{_TH}ACTUAL</th>{_TH}OPTIMAL</th>{_TH}LEFT ON BENCH</th>"
            f"</tr></thead><tbody>{rows_html}</tbody></table></div>"
        ) if wk_rows else _no_data
        return nav_html + body_html

    # ── User views ────────────────────────────────────────────────────────────
    if not viewer_rid:
        return (nav_html +
                "<div class='card central'><div class='card-body' style='padding:24px;text-align:center'>"
                "<p style='color:var(--muted)'>Sign in to see your optimal lineup history.</p>"
                "</div></div>")

    weeks_data = _roster_weeks(viewer_rid)
    if not weeks_data:
        return (nav_html +
                "<div class='card central'><div class='card-body' style='padding:24px;text-align:center'>"
                "<p style='color:var(--muted)'>No lineup data found.</p></div></div>")

    # ── User weekly view ──────────────────────────────────────────────────────
    if period == "weekly":
        wd = next((w for w in weeks_data if w["week"] == sel_week), None)
        if not wd:
            return nav_html + _no_data
        left_color = "#ef4444" if wd["left"] > 15 else ("#f59e0b" if wd["left"] > 7 else "#22c55e")
        badges = _opt_player_badges(wd["players"])
        pos_html = _opt_pos_breakdown([wd])
        summary = (
            f"<div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));"
            f"gap:12px;margin-bottom:16px;'>"
            f"<div class='card' style='padding:16px;text-align:center;'>"
            f"<div style='font-size:22px;font-weight:700;'>{wd['actual_pts']}</div>"
            f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>ACTUAL PTS</div></div>"
            f"<div class='card' style='padding:16px;text-align:center;'>"
            f"<div style='font-size:22px;font-weight:700;'>{wd['opt_pts']}</div>"
            f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>OPTIMAL PTS</div></div>"
            f"<div class='card' style='padding:16px;text-align:center;'>"
            f"<div style='font-size:22px;font-weight:700;color:{left_color};'>+{wd['left']}</div>"
            f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>LEFT ON BENCH</div></div>"
            f"</div>"
        )
        detail = (
            f"<div class='card'>"
            f"<div class='card-header'><h3>Week {sel_week} - Player Breakdown</h3></div>"
            f"<div style='padding:12px;'>"
            f"<div style='font-size:12px;color:var(--muted);margin-bottom:8px;'>"
            f"<span style='color:#ef4444'>&#9660; Should have benched</span> &nbsp; "
            f"<span style='color:#22c55e'>&#9650; Should have started</span></div>"
            f"<div style='display:flex;flex-wrap:wrap;gap:6px;'>{badges}</div>"
            f"</div></div>"
        )
        return nav_html + summary + detail + pos_html

    # ── User season view ──────────────────────────────────────────────────────
    season_actual  = sum(w["actual_pts"] for w in weeks_data)
    season_optimal = sum(w["opt_pts"]    for w in weeks_data)
    season_left    = round(sum(w["left"] for w in weeks_data), 1)
    efficiency     = round((season_actual / season_optimal * 100) if season_optimal else 0, 1)
    worst_week     = max(weeks_data, key=lambda x: x["left"])
    best_week      = min(weeks_data, key=lambda x: x["left"])

    summary_html = (
        f"<div style='display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));"
        f"gap:12px;margin-bottom:20px;'>"
        f"<div class='card' style='padding:16px;text-align:center;'>"
        f"<div style='font-size:24px;font-weight:700;color:var(--accent);'>{season_left}</div>"
        f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>PTS LEFT ON BENCH</div></div>"
        f"<div class='card' style='padding:16px;text-align:center;'>"
        f"<div style='font-size:24px;font-weight:700;color:var(--text);'>{efficiency}%</div>"
        f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>LINEUP EFFICIENCY</div></div>"
        f"<div class='card' style='padding:16px;text-align:center;'>"
        f"<div style='font-size:24px;font-weight:700;color:#ef4444;'>Wk {worst_week['week']}</div>"
        f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>WORST (+{worst_week['left']} left)</div></div>"
        f"<div class='card' style='padding:16px;text-align:center;'>"
        f"<div style='font-size:24px;font-weight:700;color:#22c55e;'>Wk {best_week['week']}</div>"
        f"<div style='font-size:11px;color:var(--muted);margin-top:4px;'>BEST (+{best_week['left']} left)</div></div>"
        f"</div>"
    )

    rows_html = "".join(_wk_table_row(wd) for wd in reversed(weeks_data))
    table_html = (
        f"<div class='card' style='overflow:auto;'>"
        f"<div class='card-header' style='display:flex;justify-content:space-between;align-items:center;'>"
        f"<h3>Week-by-Week Breakdown</h3>"
        f"<span style='font-size:12px;color:var(--muted);'>Click row to expand</span></div>"
        f"<table style='width:100%;border-collapse:collapse;'>"
        f"<thead><tr style='border-bottom:1px solid var(--border);'>"
        f"{_TH}WEEK</th>{_TH}ACTUAL PTS</th>{_TH}OPTIMAL PTS</th>{_TH}LEFT ON BENCH</th>"
        f"</tr></thead><tbody>{rows_html}</tbody></table></div>"
    )

    pos_html = _opt_pos_breakdown(weeks_data)

    return nav_html + summary_html + table_html + pos_html


@app.route("/<platform>/<int:season>/<league_id>/optimal")
def page_optimal(platform: str, season: int, league_id: str):
    ctx = get_league_ctx_from_cache(platform, league_id, season)
    body = build_optimal_body(ctx)
    return render_page("Lineup Efficiency Tracker", league_id, "optimal", body, platform, season)


# ══════════════════════════════════════════════════════════════════════════════
# PLAYOFF SCHEDULE HIGHLIGHTER
# ══════════════════════════════════════════════════════════════════════════════

_FPTS_AGAINST_CACHE: dict = {}
_FPTS_AGAINST_CACHE_TS: dict = {}
_FPTS_AGAINST_TTL = 3600  # 1 hour

_MATCHUP_RATINGS_CACHE: dict = {}
_MATCHUP_RATINGS_TS: dict = {}
_MATCHUP_RATINGS_TTL = 3600  # 1 hour

def _compute_fpts_against(season: int) -> dict:
    """
    Compute fantasy points allowed per game by each NFL defense, broken down by position.
    Uses cached weekly stats (pts_ppr per player) + schedule files to attribute
    each player's output to the opposing defense.

    Returns: {
      "NE": {"QB": 22.1, "RB": 18.4, "WR": 28.6, "TE": 9.2, "games": 9},
      ...
    }
    """
    import glob as _glob
    global _FPTS_AGAINST_CACHE, _FPTS_AGAINST_CACHE_TS

    cache_key = str(season)
    now = time.time()
    if _FPTS_AGAINST_CACHE.get(cache_key) and now - _FPTS_AGAINST_CACHE_TS.get(cache_key, 0) < _FPTS_AGAINST_TTL:
        return _FPTS_AGAINST_CACHE[cache_key]

    players_idx = get_players_index_global() or {}
    # Build fast pid→(team, pos) lookup
    pid_to_info: dict = {}
    for pid, info in players_idx.items():
        team = (info.get("team") or "").upper()
        pos  = (info.get("pos") or "").upper()
        if team and pos in {"QB", "RB", "WR", "TE", "K"}:
            pid_to_info[str(pid)] = (team, pos)

    # Weekly stats files: sleeper_stats_s{year}_w{week}_*.json
    stat_files = sorted(_glob.glob(
        os.path.join("cache", "sleeper_stats", f"sleeper_stats_s{season}_w*.json")
    ))

    # totals[team][pos] = list of fpts scored against them
    from collections import defaultdict as _dd
    totals: dict = _dd(lambda: _dd(list))
    games_played: dict = _dd(set)   # games_played[team] = set of (week, opponent) seen

    for stat_file in stat_files:
        try:
            import re as _re
            basename = os.path.basename(stat_file)
            m = _re.match(r"sleeper_stats_s(\d+)_w(\d+)", basename)
            if not m:
                continue
            week = int(m.group(2))

            # Load schedule for this week to build team→opponent map
            sched_files = _glob.glob(
                os.path.join("cache", "schedule", f"schedule_s{season}_w{week}.json")
            )
            if not sched_files:
                continue
            games = json.load(open(sched_files[0]))
            _alias = {"WSH": "WAS"}
            def _n(t): return _alias.get(t, t)
            opp_map: dict = {}  # team → opponent for this week
            for g in games:
                home = _n((g.get("home") or "").upper())
                away = _n((g.get("away") or "").upper())
                if home and away:
                    opp_map[home] = away
                    opp_map[away] = home
                    games_played[home].add((week, away))
                    games_played[away].add((week, home))

            # Load stats
            stats_data = json.load(open(stat_file))
            if not isinstance(stats_data, dict):
                continue

            for pid, stats in stats_data.items():
                info = pid_to_info.get(str(pid))
                if not info:
                    continue
                player_team, pos = info
                opp = opp_map.get(player_team)
                if not opp:
                    continue  # on bye or no schedule data
                pts = float(stats.get("pts_ppr") or 0)
                if pts == 0:
                    continue
                totals[opp][pos].append(pts)
        except Exception:
            continue

    result = {}
    for team, pos_dict in totals.items():
        n_games = max(len(games_played.get(team, set())), 1)
        result[team] = {"games": n_games}
        for pos, pts_list in pos_dict.items():
            result[team][pos] = round(sum(pts_list) / n_games, 1)

    _FPTS_AGAINST_CACHE[cache_key] = result
    _FPTS_AGAINST_CACHE_TS[cache_key] = now
    return result

_SCHED_POS_COLORS = {"QB": "#3b82f6", "RB": "#22c55e", "WR": "#f59e0b",
                     "TE": "#a855f7", "K": "#6b7280", "DEF": "#6b7280"}
_SCHED_POS_ORDER = {"QB": 0, "RB": 1, "WR": 2, "TE": 3, "K": 4, "DEF": 5}

# Normalize schedule-file team codes to the abbreviations used everywhere else
# (e.g. the schedule uses WSH; players_index and the ratings use WAS).
_SCHED_TEAM_ALIAS = {"WSH": "WAS", "JAC": "JAX", "LA": "LAR", "OAK": "LV",
                     "SD": "LAC", "STL": "LAR", "ARZ": "ARI", "BLT": "BAL",
                     "CLV": "CLE", "HST": "HOU"}


def _norm_sched_team(t):
    t = (t or "").upper().strip()
    return _SCHED_TEAM_ALIAS.get(t, t)


def _sched_rank_color(rank, total):
    """Color for a matchup by opponent's fpts-allowed rank (1 = easiest)."""
    if not rank or not total:
        return "#6b7280", "transparent"
    pct = rank / total
    if pct <= 0.25:
        return "#22c55e", "#22c55e18"   # elite (most pts allowed)
    if pct <= 0.50:
        return "#84cc16", "#84cc1618"
    if pct <= 0.75:
        return "#f59e0b", "#f59e0b18"
    return "#ef4444", "#ef444418"        # brutal (fewest pts allowed)


def _load_matchup_ratings(season: int) -> dict:
    """Load the cron-precomputed z-score matchup ratings table.

    Shape: {team: {pos: {"z": float, "ease": 0-100, "n": int, "fpts": float}}}.
    Returns {} when the cache file is absent so callers fall back to raw
    fpts-allowed (the table is produced by data_building/matchup_ratings.py via
    the daily cron)."""
    key = str(season)
    now = time.time()
    if (_MATCHUP_RATINGS_CACHE.get(key) is not None
            and now - _MATCHUP_RATINGS_TS.get(key, 0) < _MATCHUP_RATINGS_TTL):
        return _MATCHUP_RATINGS_CACHE[key]
    data: dict = {}
    try:
        path = os.path.join("cache", f"matchup_ratings_s{season}.json")
        if os.path.exists(path):
            blob = json.load(open(path))
            data = blob.get("ratings") or {}
    except Exception:
        data = {}
    _MATCHUP_RATINGS_CACHE[key] = data
    _MATCHUP_RATINGS_TS[key] = now
    return data


def _matchup_rank_table(season: int, position: str):
    """Return (rank_map, total_teams, info_by_team, is_z).

    rank_map[team] -> rank where 1 = easiest matchup for `position`. Uses the
    strength-of-schedule-adjusted z-score ratings when available, otherwise
    falls back to raw fpts-allowed so the schedule views keep working before
    the first cron build. info_by_team[team] carries {"z","ease","fpts"}."""
    ratings = _load_matchup_ratings(season)
    pairs = []
    info: dict = {}
    if ratings:
        for team, posd in ratings.items():
            r = posd.get(position)
            if not r:
                continue
            pairs.append((team, r.get("z", 0.0)))
            info[team] = r
    if pairs:
        pairs.sort(key=lambda x: -x[1])   # highest z = easiest = rank 1
        return {t: i + 1 for i, (t, _) in enumerate(pairs)}, len(pairs), info, True

    # Fallback: raw fantasy points allowed (pre-z behavior)
    fa = _compute_fpts_against(season)
    fpairs = [(t, d.get(position, 0)) for t, d in fa.items() if position in d]
    fpairs.sort(key=lambda x: -x[1])
    finfo = {t: {"fpts": fa.get(t, {}).get(position, 0)} for t, _ in fpairs}
    return {t: i + 1 for i, (t, _) in enumerate(fpairs)}, len(fpairs), finfo, False


def _matchup_cell_ease(rank, total, info):
    """Per-cell ease (0-100). Prefer the z-derived ease; fall back to rank percentile."""
    if info and info.get("ease") is not None:
        return float(info["ease"])
    if rank and total and total > 1:
        return round((total - rank) / (total - 1) * 100, 1)
    return 0.0


def _compute_schedule_grid(season: int, pids, weeks):
    """For each pid over the given weeks, return matchup + difficulty cells.
    Reuses the cached fpts-allowed table so this is cheap per request."""
    players_idx = get_players_index_global() or {}

    # Per-position z-score matchup tables (falls back to raw fpts when uncomputed)
    _pos_rank_cache: dict = {}
    def _fpts_rank(team: str, pos: str):
        if pos not in _pos_rank_cache:
            _pos_rank_cache[pos] = _matchup_rank_table(season, pos)
        rank_map, total, info, _is_z = _pos_rank_cache[pos]
        rinfo = info.get(team, {})
        fpts_val = rinfo.get("fpts", 0)
        rank = rank_map.get(team)
        return rank, (total if rank else None), fpts_val

    schedules: dict = {}
    for w in weeks:
        try:
            games = load_week_schedule(season, w) or []
        except Exception:
            games = []
        lookup = {}
        for g in games:
            home = _norm_sched_team(g.get("home"))
            away = _norm_sched_team(g.get("away"))
            if home:
                lookup[home] = {"opp": away, "is_home": True}
            if away:
                lookup[away] = {"opp": home, "is_home": False}
        schedules[w] = lookup

    # Per-position team strength-of-schedule over the selected weeks (rank 1 =
    # easiest schedule among all NFL teams), so each player shows where their
    # team's schedule ranks for their position.
    _team_sos_cache: dict = {}
    def _team_sos(pos: str):
        if pos in _team_sos_cache:
            return _team_sos_cache[pos]
        if pos not in _pos_rank_cache:
            _pos_rank_cache[pos] = _matchup_rank_table(season, pos)
        rank_map, total, info, _is_z = _pos_rank_cache[pos]
        team_ease: dict = {}
        for t in rank_map.keys():
            eases = []
            for w in weeks:
                game = schedules.get(w, {}).get(t)
                if not game:
                    continue
                r = rank_map.get(game["opp"])
                eases.append(_matchup_cell_ease(r, total, info.get(game["opp"], {})))
            if eases:
                team_ease[t] = sum(eases) / len(eases)
        ranked = sorted(team_ease.items(), key=lambda x: -x[1])
        sos = {t: (i + 1, len(ranked), round(e, 1)) for i, (t, e) in enumerate(ranked)}
        _team_sos_cache[pos] = sos
        return sos

    out = []
    for pid in pids:
        info = players_idx.get(str(pid)) or {}
        pos = (info.get("pos") or "").upper()
        nfl = _norm_sched_team(info.get("team"))
        cells = []
        for w in weeks:
            game = schedules.get(w, {}).get(nfl)
            if not game:
                cells.append({"week": w, "bye": True})
                continue
            opp = game["opp"]
            rank, total, fpts_val = _fpts_rank(opp, pos)
            txt, bg = _sched_rank_color(rank, total)
            cells.append({
                "week": w, "bye": False, "opp": opp,
                "at": "" if game["is_home"] else "@",
                "rank": rank, "total": total,
                "fpts": round(fpts_val, 1) if fpts_val else 0,
                "txt": txt, "bg": bg,
            })
        _sos = _team_sos(pos).get(nfl)
        sos_rank, sos_total, sos_ease = _sos if _sos else (None, None, None)
        out.append({
            "pid": str(pid),
            "name": info.get("name") or str(pid),
            "pos": pos,
            "color": _SCHED_POS_COLORS.get(pos, "#6b7280"),
            "nfl": nfl,
            "cells": cells,
            "sos_rank": sos_rank,
            "sos_total": sos_total,
            "sos_ease": sos_ease,
        })
    out.sort(key=lambda p: (_SCHED_POS_ORDER.get(p["pos"], 9), p["name"]))
    return out


def build_schedule_body(ctx):
    import json as _json
    season     = int(ctx.get("season") or datetime.now().year)
    league_id  = ctx.get("league_id") or ""
    platform   = ctx.get("platform") or "sleeper"
    viewer_rid = str((ctx.get("viewer") or {}).get("viewer_roster_id") or "")
    rosters    = ctx.get("rosters") or []
    players_idx = get_players_index_global() or {}

    current_week = int(ctx.get("current_week") or 0)
    max_week   = 18
    start_week = current_week if current_week >= 1 else 1
    def_start  = start_week
    def_end    = min(start_week + 3, max_week)

    viewer_roster = next((r for r in rosters if str(r.get("roster_id")) == viewer_rid), None)
    roster_pids = [str(p) for p in (viewer_roster.get("players") if viewer_roster else []) or []]
    init_pids = [
        pid for pid in roster_pids
        if ((players_idx.get(pid) or {}).get("pos") or "").upper() in ("QB", "RB", "WR", "TE", "K", "DEF")
    ]

    cfg = _json.dumps({
        "season": season, "leagueId": league_id, "platform": platform,
        "startWeek": start_week, "maxWeek": max_week,
        "defStart": def_start, "defEnd": def_end,
        "initPids": init_pids,
    })

    shell = """
    <div class="card central schedule-card">
      <div class="card-header" style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px;">
        <div>
          <h2>Schedule Assistant</h2>
          <div style="font-size:14px;color:var(--text-muted);margin-top:4px;">
            Matchup difficulty by week. Add or remove players and pick a single week or a range.
          </div>
        </div>
        <div class="sched-view-toggle" id="schedViewToggle">
          <button class="sched-view-btn active" data-view="my-players">My Players</button>
          <button class="sched-view-btn" data-view="rankings">Schedule Rankings</button>
        </div>
      </div>

      <!-- Shared controls: week range always; player search vs. rank controls flip per tab -->
      <div class="sched-controls sched-shared-controls">
        <div class="sched-week-range">
          <span class="sched-ctrl-label">Weeks</span>
          <select id="schedWkStart" class="sched-select"></select>
          <span class="sched-ctrl-sep">to</span>
          <select id="schedWkEnd" class="sched-select"></select>
        </div>

        <!-- My Players: player search -->
        <div class="sched-add" id="schedAddWrap">
          <span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);font-size:13px;color:var(--text-muted);pointer-events:none;"><i class="fa-solid fa-magnifying-glass"></i></span>
          <input id="schedAddInput" type="text" placeholder="Add a player..." autocomplete="off"
            style="width:100%;padding:8px 32px 8px 34px;border-radius:8px;
                   border:1px solid var(--border);background:var(--card-bg);
                   color:var(--text);font-size:13px;outline:none;box-sizing:border-box;">
          <button id="schedAddClear" type="button"
            style="display:none;position:absolute;right:8px;top:50%;transform:translateY(-50%);
                   background:none;border:none;cursor:pointer;color:var(--text-muted);
                   font-size:16px;line-height:1;padding:2px;" aria-label="Clear search">&#x2715;</button>
          <div id="schedAddResults" class="sched-add-results" style="display:none;"></div>
        </div>

        <!-- Schedule Rankings: position pills + sort -->
        <div class="sched-rank-controls" id="schedRankControls" style="display:none;">
          <div class="sched-pos-pills" id="schedRankPosPills">
            <button class="sched-rank-pos active" data-pos="QB">QB</button>
            <button class="sched-rank-pos" data-pos="RB">RB</button>
            <button class="sched-rank-pos" data-pos="WR">WR</button>
            <button class="sched-rank-pos" data-pos="TE">TE</button>
            <button class="sched-rank-pos" data-pos="K">K</button>
          </div>
          <button class="sched-sort-btn" id="schedRankSort">
            Easiest First <i class="fa-solid fa-arrow-up-short-wide" aria-hidden="true"></i>
          </button>
        </div>
      </div>

      <!-- My Players view -->
      <div id="schedMyPlayersSection">
        <div class="sched-legend">
          <span><span class="sched-chip" style="background:#22c55e;"></span>Elite (top 25%)</span>
          <span><span class="sched-chip" style="background:#84cc16;"></span>Good</span>
          <span><span class="sched-chip" style="background:#f59e0b;"></span>Tough</span>
          <span><span class="sched-chip" style="background:#ef4444;"></span>Brutal (bottom 25%)</span>
          <span class="sched-legend-note">Rank = fantasy pts allowed per game at that position (PPR). #1 = easiest matchup.</span>
        </div>

        <div id="schedGrid" class="sched-grid-wrap">
          <div class="sched-empty">Loading schedule&#8230;</div>
        </div>
      </div>

      <!-- Schedule Rankings view -->
      <div id="schedRankingsSection" style="display:none;">
        <div class="sched-legend" style="padding-top:0;">
          <span><span class="sched-chip" style="background:#22c55e;"></span>Elite</span>
          <span><span class="sched-chip" style="background:#84cc16;"></span>Good</span>
          <span><span class="sched-chip" style="background:#f59e0b;"></span>Tough</span>
          <span><span class="sched-chip" style="background:#ef4444;"></span>Brutal</span>
          <span class="sched-legend-note">Ease score: 100 = easiest schedule, 0 = hardest. Rank = fpts allowed rank vs. that position.</span>
        </div>
        <div id="schedRankingsGrid" class="sched-grid-wrap">
          <div class="sched-empty">Loading&#8230;</div>
        </div>
      </div>
    </div>
    """

    script = """
    <script>
    (function() {
      var CFG = __CFG__;
      var LS_PIDS = 'sched_pids_' + CFG.leagueId;
      var LS_WKS  = 'sched_wks_'  + CFG.leagueId;

      var selPids = [];
      try { selPids = JSON.parse(localStorage.getItem(LS_PIDS) || 'null'); } catch (e) {}
      if (!Array.isArray(selPids) || !selPids.length) selPids = CFG.initPids.slice();

      var wkStart = CFG.defStart, wkEnd = CFG.defEnd;
      try {
        var saved = JSON.parse(localStorage.getItem(LS_WKS) || 'null');
        if (saved && saved.s) { wkStart = saved.s; wkEnd = saved.e; }
      } catch (e) {}
      if (wkStart < CFG.startWeek) wkStart = CFG.startWeek;
      if (wkEnd > CFG.maxWeek) wkEnd = CFG.maxWeek;
      if (wkEnd < wkStart) wkEnd = wkStart;

      var currentView  = 'my-players';
      var rankPos      = 'QB';
      var rankHardFirst = false;
      var rankingsCache = null;   // last fetched rankings data
      var _myKey   = null;        // week range My Players last rendered at
      var _rankKey = null;        // week range Rankings last rendered at

      var pool      = [];
      var poolReady = false;

      var startSel   = document.getElementById('schedWkStart');
      var endSel     = document.getElementById('schedWkEnd');
      var addInput   = document.getElementById('schedAddInput');
      var addResults = document.getElementById('schedAddResults');
      var addClear   = document.getElementById('schedAddClear');
      var gridEl     = document.getElementById('schedGrid');

      function fillWeekSelects() {
        var optsS = '', optsE = '';
        for (var w = CFG.startWeek; w <= CFG.maxWeek; w++) {
          optsS += '<option value="' + w + '"' + (w === wkStart ? ' selected' : '') + '>Week ' + w + '</option>';
          optsE += '<option value="' + w + '"' + (w === wkEnd   ? ' selected' : '') + '>Week ' + w + '</option>';
        }
        startSel.innerHTML = optsS;
        endSel.innerHTML   = optsE;
      }

      function persist() {
        try { localStorage.setItem(LS_PIDS, JSON.stringify(selPids)); } catch (e) {}
        try { localStorage.setItem(LS_WKS,  JSON.stringify({s: wkStart, e: wkEnd})); } catch (e) {}
      }

      function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"]/g, function(c) {
          return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];
        });
      }

      // ── My Players view ─────────────────────────────────────────────────────
      function renderGrid() {
        _myKey = wkStart + '-' + wkEnd;
        if (!selPids.length) {
          gridEl.innerHTML = '<div class="sched-empty">No players yet. Use the search above to add players.</div>';
          return;
        }
        gridEl.innerHTML = '<div class="sched-empty">Loading…</div>';
        var url = '/api/schedule?season=' + CFG.season +
                  '&week_start=' + wkStart + '&week_end=' + wkEnd +
                  '&pids=' + encodeURIComponent(selPids.join(','));
        fetch(url).then(function(r) { return r.json(); }).then(function(data) {
          var weeks   = data.weeks   || [];
          var players = data.players || [];
          if (!players.length) {
            gridEl.innerHTML = '<div class="sched-empty">No matchup data for this selection.</div>';
            return;
          }
          var head = '<th class="sched-th sched-th-player">Player</th>' +
                     '<th class="sched-th sched-th-sos" title="Strength of schedule rank for this position over the selected weeks (1 = easiest)">SoS</th>';
          for (var i = 0; i < weeks.length; i++) head += '<th class="sched-th">WK ' + weeks[i] + '</th>';
          var rows = '';
          players.forEach(function(p) {
            var cells = '';
            (p.cells || []).forEach(function(c) {
              if (c.bye) { cells += '<td class="sched-td sched-bye">BYE</td>'; return; }
              var rankLabel = c.rank ? ('#' + c.rank) : '–';
              var fptsLabel = c.fpts ? (c.fpts + ' pts') : '';
              cells += '<td class="sched-td" style="background:' + c.bg + ';">' +
                         '<div class="sched-opp">'  + esc(c.at + c.opp) + '</div>' +
                         '<div class="sched-rank" style="color:' + c.txt + ';">' + rankLabel + '</div>' +
                         '<div class="sched-fpts">' + esc(fptsLabel) + '</div>' +
                       '</td>';
            });
            var sosCell;
            if (p.sos_rank) {
              var sosFrac = p.sos_rank / (p.sos_total || 32);
              var sc = sosFrac <= 0.25 ? '#22c55e' : sosFrac <= 0.50 ? '#84cc16' : sosFrac <= 0.75 ? '#f59e0b' : '#ef4444';
              sosCell = '<td class="sched-td sched-sos-td" style="color:' + sc + ';">#' + p.sos_rank +
                        '<span class="sched-sos-total">/' + (p.sos_total || 32) + '</span></td>';
            } else {
              sosCell = '<td class="sched-td sched-sos-td">–</td>';
            }
            rows += '<tr>' +
              '<td class="sched-td sched-td-player">' +
                '<button class="sched-remove" data-pid="' + esc(p.pid) + '" title="Remove">&times;</button>' +
                '<span class="sched-pos" style="background:' + p.color + '22;color:' + p.color + ';">' + esc(p.pos) + '</span>' +
                '<span class="player-clickable sched-pname" data-player-id="' + esc(p.pid) + '">' + esc(p.name) + '</span>' +
                '<span class="sched-nfl">' + esc(p.nfl) + '</span>' +
              '</td>' + sosCell + cells + '</tr>';
          });
          gridEl.innerHTML =
            '<table class="sched-table"><thead><tr>' + head + '</tr></thead><tbody>' + rows + '</tbody></table>';
        }).catch(function() {
          gridEl.innerHTML = '<div class="sched-empty" style="color:#ef4444;">Failed to load schedule.</div>';
        });
      }

      // ── Schedule Rankings view ────────────────────────────────────────────────────
      function switchView(v) {
        currentView = v;
        document.getElementById('schedMyPlayersSection').style.display  = v === 'my-players' ? '' : 'none';
        document.getElementById('schedRankingsSection').style.display   = v === 'rankings'   ? '' : 'none';
        // Flip the shared controls to match the active tab
        document.getElementById('schedAddWrap').style.display      = v === 'my-players' ? '' : 'none';
        document.getElementById('schedRankControls').style.display = v === 'rankings'   ? '' : 'none';
        document.querySelectorAll('.sched-view-btn').forEach(function(b) {
          b.classList.toggle('active', b.getAttribute('data-view') === v);
        });
        // Re-render the target view if the (shared) week range changed since it
        // last rendered, so switching tabs always reflects the current weeks.
        var key = wkStart + '-' + wkEnd;
        if (v === 'rankings') {
          if (_rankKey !== key) { rankPage = 0; rankingsCache = null; renderRankings(); }
        } else {
          if (_myKey !== key) renderGrid();
        }
      }

      function renderRankings() {
        _rankKey = wkStart + '-' + wkEnd;
        rankingsCache = null;
        var rankGrid = document.getElementById('schedRankingsGrid');
        rankGrid.innerHTML = '<div class="sched-empty">Loading…</div>';
        var url = '/api/schedule-rankings?season=' + CFG.season +
                  '&week_start=' + wkStart + '&week_end=' + wkEnd +
                  '&position=' + rankPos +
                  '&league_id=' + encodeURIComponent(CFG.leagueId) +
                  '&platform='  + encodeURIComponent(CFG.platform);
        fetch(url).then(function(r) { return r.json(); }).then(function(data) {
          rankingsCache = data;
          buildRankingsTable(data);
        }).catch(function() {
          rankGrid.innerHTML = '<div class="sched-empty" style="color:#ef4444;">Failed to load rankings.</div>';
        });
      }

      var rankPage = 0;

      function buildRankingsTable(data) {
        var rankGrid  = document.getElementById('schedRankingsGrid');
        var weeks     = data.weeks    || [];
        var total     = data.total_teams || 32;
        var rankings  = (data.rankings || []).slice();
        if (rankHardFirst) rankings.reverse();

        if (!rankings.length) {
          rankGrid.innerHTML = '<div class="sched-empty">No data for this position/week range.</div>';
          return;
        }

        // Group players from the same NFL team into one row - their schedule,
        // avg rank and ease are identical, so separate rows just repeat values.
        var groups = [];
        var byTeam = {};
        rankings.forEach(function(p) {
          var g = byTeam[p.team];
          if (!g) { g = { team: p.team, rep: p, players: [] }; byTeam[p.team] = g; groups.push(g); }
          g.players.push(p);
        });

        var head = '<th class="sched-th sched-th-player">Team</th>';
        for (var i = 0; i < weeks.length; i++) head += '<th class="sched-th">WK ' + weeks[i] + '</th>';
        head += '<th class="sched-th">Avg</th><th class="sched-th" style="min-width:90px;">Ease</th>';

        var rows = '';
        groups.forEach(function(g, idx) {
          var p = g.rep;
          var rank = idx + 1;
          var medalHtml;
          if (rank === 1)      medalHtml = '<span class="sched-rank-medal sched-rank-medal-1">1</span>';
          else if (rank === 2) medalHtml = '<span class="sched-rank-medal sched-rank-medal-2">2</span>';
          else if (rank === 3) medalHtml = '<span class="sched-rank-medal sched-rank-medal-3">3</span>';
          else                 medalHtml = '<span class="sched-rank-num">' + rank + '</span>';

          var namesHtml = g.players.map(function(pl) {
            var badge = pl.owner
              ? '<span class="sched-roster-badge sched-roster-badge--owner">' + esc(pl.owner) + '</span>'
              : (pl.on_roster ? '<span class="sched-roster-badge">Rostered</span>' : '');
            return '<div class="sched-rank-player-line">' +
                     '<span class="player-clickable sched-pname" data-player-id="' + esc(pl.pid) + '">' + esc(pl.name) + '</span>' +
                     badge +
                   '</div>';
          }).join('');

          var cells = '';
          (p.cells || []).forEach(function(c) {
            if (c.bye) { cells += '<td class="sched-td sched-bye">BYE</td>'; return; }
            var rankLabel = c.rank ? ('#' + c.rank) : '–';
            cells += '<td class="sched-td" style="background:' + c.bg + ';">' +
                       '<div class="sched-opp">'  + esc((c.at || '') + c.opp) + '</div>' +
                       '<div class="sched-rank" style="color:' + c.txt + ';">' + rankLabel + '</div>' +
                     '</td>';
          });

          var ar = p.avg_rank;
          var avgTxt   = ar < 900 ? ('#' + ar) : '–';
          var avgColor = ar <= total * 0.25 ? '#22c55e'
                       : ar <= total * 0.50 ? '#84cc16'
                       : ar <= total * 0.75 ? '#f59e0b' : '#ef4444';

          var ease      = p.ease_score || 0;
          var easeColor = ease >= 75 ? '#22c55e'
                        : ease >= 50 ? '#84cc16'
                        : ease >= 25 ? '#f59e0b' : '#ef4444';
          var easeBar = '<div class="sched-ease-wrap">' +
                          '<div class="sched-ease-bar" style="width:' + Math.round(ease) + '%;background:' + easeColor + ';"></div>' +
                        '</div>' +
                        '<div class="sched-ease-num" style="color:' + easeColor + ';">' + Math.round(ease) + '</div>';

          rows += '<tr>' +
            '<td class="sched-td sched-td-player">' +
              '<div class="sched-rank-player-cell sched-rank-player-cell--group">' +
                medalHtml +
                '<span class="sched-pos" style="background:' + p.color + '22;color:' + p.color + ';">' + esc(p.pos) + '</span>' +
                '<div class="sched-rank-name-wrap">' + namesHtml + '</div>' +
                '<span class="sched-nfl">' + esc(g.team) + '</span>' +
              '</div>' +
            '</td>' +
            cells +
            '<td class="sched-td" style="font-size:12px;font-weight:700;color:' + avgColor + ';white-space:nowrap;">' + avgTxt + '</td>' +
            '<td class="sched-td sched-ease-td">' + easeBar + '</td>' +
          '</tr>';
        });

        rankGrid.innerHTML =
          '<table class="sched-table"><thead><tr>' + head + '</tr></thead><tbody>' + rows + '</tbody></table>';
      }

      // ── Player search / pool ────────────────────────────────────────────────────────────────
      function loadPool() {
        fetch('/api/league-players').then(function(r) { return r.json(); }).then(function(resp) {
          var arr = Array.isArray(resp) ? resp : (resp.players || []);
          pool = arr.filter(function(p) {
            var pos = String(p.position || '').toUpperCase();
            return ['QB','RB','WR','TE','K','DEF'].indexOf(pos) !== -1 && p.team && p.team !== 'FA';
          }).map(function(p) {
            return {id: String(p.id), name: p.name || '', pos: String(p.position || '').toUpperCase(), team: p.team || ''};
          });
          poolReady = true;
        }).catch(function() {});
      }

      function showAddResults(q) {
        if (!poolReady || !q) { addResults.style.display = 'none'; return; }
        var ql  = q.toLowerCase();
        var sel = {};
        selPids.forEach(function(id) { sel[id] = 1; });
        var matches = pool.filter(function(p) {
          return !sel[p.id] && p.name.toLowerCase().indexOf(ql) !== -1;
        }).slice(0, 8);
        if (!matches.length) { addResults.style.display = 'none'; return; }
        addResults.innerHTML = matches.map(function(p) {
          var col = ({QB:'#3b82f6',RB:'#22c55e',WR:'#f59e0b',TE:'#a855f7'})[p.pos] || '#6b7280';
          return '<div class="sched-add-row" data-pid="' + esc(p.id) + '">' +
                   '<span class="sched-pos" style="background:' + col + '22;color:' + col + ';">' + esc(p.pos) + '</span>' +
                   '<span>' + esc(p.name) + '</span>' +
                   '<span class="sched-nfl">' + esc(p.team) + '</span>' +
                 '</div>';
        }).join('');
        addResults.style.display = 'block';
      }

      // ── Wire up controls ──────────────────────────────────────────────────────────────────
      fillWeekSelects();

      startSel.addEventListener('change', function() {
        wkStart = parseInt(this.value, 10);
        if (wkEnd < wkStart) wkEnd = wkStart;
        fillWeekSelects(); persist();
        if (currentView === 'my-players') renderGrid(); else { rankPage = 0; rankingsCache = null; renderRankings(); }
      });
      endSel.addEventListener('change', function() {
        wkEnd = parseInt(this.value, 10);
        if (wkStart > wkEnd) wkStart = wkEnd;
        fillWeekSelects(); persist();
        if (currentView === 'my-players') renderGrid(); else { rankPage = 0; rankingsCache = null; renderRankings(); }
      });

      addInput.addEventListener('input', function() {
        showAddResults(this.value.trim());
        if (addClear) addClear.style.display = this.value ? '' : 'none';
      });
      addInput.addEventListener('focus', function() { showAddResults(this.value.trim()); });
      if (addClear) {
        addClear.addEventListener('click', function() {
          addInput.value = '';
          addResults.style.display = 'none';
          addClear.style.display = 'none';
          addInput.focus();
        });
      }

      document.addEventListener('click', function(e) {
        var row = e.target.closest ? e.target.closest('.sched-add-row') : null;
        if (row && addResults.contains(row)) {
          var pid = row.getAttribute('data-pid');
          if (pid && selPids.indexOf(pid) === -1) { selPids.push(pid); persist(); renderGrid(); }
          addInput.value = '';
          addResults.style.display = 'none';
          if (addClear) addClear.style.display = 'none';
          return;
        }
        if (!addResults.contains(e.target) && e.target !== addInput) {
          addResults.style.display = 'none';
        }
      });

      gridEl.addEventListener('click', function(e) {
        var btn = e.target.closest ? e.target.closest('.sched-remove') : null;
        if (btn) {
          e.stopPropagation();
          var pid = btn.getAttribute('data-pid');
          selPids = selPids.filter(function(id) { return id !== pid; });
          persist(); renderGrid();
        }
      });

      // View toggle
      document.getElementById('schedViewToggle').addEventListener('click', function(e) {
        var btn = e.target.closest ? e.target.closest('.sched-view-btn') : null;
        if (btn) switchView(btn.getAttribute('data-view'));
      });

      // Rankings position filter
      document.getElementById('schedRankPosPills').addEventListener('click', function(e) {
        var btn = e.target.closest ? e.target.closest('.sched-rank-pos') : null;
        if (!btn) return;
        rankPos = btn.getAttribute('data-pos');
        rankPage = 0;
        document.querySelectorAll('.sched-rank-pos').forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        renderRankings();
      });

      // Sort toggle
      document.getElementById('schedRankSort').addEventListener('click', function() {
        rankHardFirst = !rankHardFirst;
        this.innerHTML = rankHardFirst
          ? 'Hardest First <i class="fa-solid fa-arrow-down-short-wide" aria-hidden="true"></i>'
          : 'Easiest First <i class="fa-solid fa-arrow-up-short-wide" aria-hidden="true"></i>';
        rankPage = 0;
        if (rankingsCache) buildRankingsTable(rankingsCache);
      });

      loadPool();
      renderGrid();
    })();
    </script>
    """.replace("__CFG__", cfg)

    return shell + script


@app.route("/api/schedule")
def api_schedule():
    try:
        season = int(request.args.get("season") or 0)
        pids = [p for p in (request.args.get("pids") or "").split(",") if p]
        ws = int(request.args.get("week_start") or 1)
        we = int(request.args.get("week_end") or ws)
        if we < ws:
            ws, we = we, ws
        ws = max(1, min(ws, 18))
        we = max(1, min(we, 18))
        weeks = list(range(ws, we + 1))
        if not pids:
            return jsonify({"weeks": weeks, "players": []})
        players = _compute_schedule_grid(season, pids, weeks)
        return jsonify({"weeks": weeks, "players": players})
    except Exception as e:
        return _api_err("Schedule unavailable", e)


@app.route("/api/schedule-rankings")
def api_schedule_rankings():
    try:
        import glob as _glob
        season    = int(request.args.get("season") or datetime.now().year)
        ws        = int(request.args.get("week_start") or 1)
        we        = int(request.args.get("week_end") or ws)
        position  = (request.args.get("position") or "RB").upper().strip()
        league_id = (request.args.get("league_id") or "").strip()
        platform  = (request.args.get("platform") or "sleeper").strip()

        ws = max(1, min(ws, 18))
        we = max(ws, min(we, 18))
        weeks = list(range(ws, we + 1))
        if position not in {"QB", "RB", "WR", "TE", "K"}:
            position = "RB"

        players_idx  = get_players_index_global() or {}

        # Build schedule lookup for requested weeks
        schedules = {}
        for w in weeks:
            try:
                from utils.utils import load_week_schedule as _lws
                games = _lws(season, w) or []
            except Exception:
                games = []
            lookup = {}
            for g in games:
                if not isinstance(g, dict): continue
                home = _norm_sched_team(g.get("home"))
                away = _norm_sched_team(g.get("away"))
                if home:
                    lookup[home] = {"opp": away, "is_home": True}
                if away:
                    lookup[away] = {"opp": home, "is_home": False}
            schedules[w] = lookup

        # Rank teams by strength-of-schedule-adjusted z-score (rank 1 = easiest).
        # Falls back to raw fpts-allowed until the cron builds the ratings table.
        rank_map, total_teams, rating_info, _is_z = _matchup_rank_table(season, position)

        # Get roster pids (+ owning team name) for the on-roster badge
        roster_pids: set = set()
        owner_by_pid: dict = {}
        if league_id:
            try:
                ctx = get_league_ctx_from_cache(platform, league_id, season)
                users_by_id = {str(u.get("user_id")): u for u in (ctx.get("users") or [])}
                for r in (ctx.get("rosters") or []):
                    owner = users_by_id.get(str(r.get("owner_id"))) or {}
                    meta = owner.get("metadata") or {}
                    tname = meta.get("team_name") or owner.get("display_name") or owner.get("username")
                    for pid in (r.get("players") or []):
                        roster_pids.add(str(pid))
                        if tname:
                            owner_by_pid[str(pid)] = tname
            except Exception:
                pass

        # Build value lookup once - used for depth-chart cap and final sort
        value_by_pid: dict = {}
        for _p in (get_model_value_table_cached() or []):
            _pid = str(_p.get("id") or "")
            if _pid:
                value_by_pid[_pid] = max(
                    float(_p.get("value") or 0),
                    float(_p.get("value_1qb") or 0),
                    float(_p.get("value_sf") or 0),
                )

        # Depth-chart cap: keep only the top N at this position per NFL team
        # (ranked by model value), plus any rostered players. Removes the long
        # tail of backups that share an identical schedule row.
        _POS_CAP = {"QB": 2, "RB": 3, "WR": 3, "TE": 2}
        cap = _POS_CAP.get(position)
        keep_pids: set = set(roster_pids)
        if cap:
            from collections import defaultdict as _dd_team
            by_team: dict = _dd_team(list)
            for _pid, _info in players_idx.items():
                if (_info.get("pos") or "").upper() != position:
                    continue
                _team = _norm_sched_team(_info.get("team"))
                if not _team or _team == "FA":
                    continue
                by_team[_team].append((str(_pid), value_by_pid.get(str(_pid), 0.0)))
            for _team, _lst in by_team.items():
                _lst.sort(key=lambda x: -x[1])
                for _pid, _ in _lst[:cap]:
                    keep_pids.add(_pid)

        # Load per-player actual points (completed weeks) and projections (future weeks)
        player_pts_actual: dict = {}
        weeks_with_stats: set  = set()
        for w in weeks:
            sfiles = _glob.glob(os.path.join("cache", "sleeper_stats", f"sleeper_stats_s{season}_w{w}*.json"))
            if not sfiles:
                continue
            weeks_with_stats.add(w)
            try:
                sd = json.load(open(sfiles[0]))
                if isinstance(sd, dict):
                    for _pid, _stats in sd.items():
                        _pts = float(_stats.get("pts_ppr") or 0)
                        if _pts > 0:
                            player_pts_actual.setdefault(str(_pid), {})[w] = round(_pts, 1)
            except Exception:
                pass

        player_pts_proj: dict = {}
        try:
            from utils.utils import load_week_projection as _lp
            for w in weeks:
                if w in weeks_with_stats:
                    continue
                _proj = _lp(season, w) or {}
                for _pid, _val in _proj.items():
                    _v = float(_val or 0)
                    if _v > 0:
                        player_pts_proj.setdefault(str(_pid), {})[w] = round(_v, 1)
        except Exception:
            pass

        results = []
        for pid, info in players_idx.items():
            pos  = (info.get("pos") or "").upper()
            if pos != position:
                continue
            team = (info.get("team") or "").upper()
            if not team or team == "FA":
                continue
            if cap and str(pid) not in keep_pids:
                continue

            cells = []
            rank_sum  = 0
            ease_sum  = 0.0
            valid_wks = 0
            for w in weeks:
                game = schedules.get(w, {}).get(team)
                if not game:
                    cells.append({"week": w, "bye": True})
                    continue
                opp      = game["opp"]
                rank     = rank_map.get(opp)
                rinfo    = rating_info.get(opp, {})
                fpts_val = rinfo.get("fpts", 0)
                txt, bg  = _sched_rank_color(rank, total_teams) if rank else ("#94a3b8", "transparent")
                actual   = player_pts_actual.get(str(pid), {}).get(w)
                proj     = player_pts_proj.get(str(pid), {}).get(w)
                p_pts    = actual if actual is not None else proj
                p_type   = "actual" if actual is not None else ("proj" if proj is not None else None)
                cells.append({
                    "week": w, "bye": False,
                    "opp": opp,
                    "at": "" if game["is_home"] else "@",
                    "rank": rank, "total": total_teams,
                    "fpts": round(fpts_val, 1) if fpts_val else 0,
                    "txt": txt, "bg": bg,
                    "pts": p_pts, "pts_type": p_type,
                })
                if rank:
                    rank_sum  += rank
                    ease_sum  += _matchup_cell_ease(rank, total_teams, rinfo)
                    valid_wks += 1

            avg_rank   = round(rank_sum / valid_wks, 1) if valid_wks else 999
            # Ease from the z-score scale (avg over scheduled weeks); higher = easier
            ease_score = round(ease_sum / valid_wks, 1) if valid_wks else 0

            results.append({
                "pid":        str(pid),
                "name":       info.get("name") or str(pid),
                "pos":        pos,
                "color":      _SCHED_POS_COLORS.get(pos, "#6b7280"),
                "team":       team,
                "value":      value_by_pid.get(str(pid), 0.0),
                "on_roster":  str(pid) in roster_pids,
                "owner":      owner_by_pid.get(str(pid)),
                "cells":      cells,
                "avg_rank":   avg_rank,
                "ease_score": ease_score,
                "valid_weeks": valid_wks,
            })

        # Sort by ease first, then group teammates together under the best player
        # on that team.  Rank #1 = the most valuable player with the easiest
        # schedule; teammates follow immediately after.
        _team_max_ease: dict = {}
        _team_max_val:  dict = {}
        for r in results:
            t = r["team"]
            if r["ease_score"] > _team_max_ease.get(t, -1):
                _team_max_ease[t] = r["ease_score"]
            if r["value"] > _team_max_val.get(t, -1):
                _team_max_val[t] = r["value"]
        results.sort(key=lambda x: (
            -_team_max_ease.get(x["team"], 0.0),  # teams with easiest schedule first
            x["team"],                             # tie-break: keep same team together
            -x["value"],                           # within team: most valuable first
        ))
        return jsonify({
            "weeks":       weeks,
            "position":    position,
            "total_teams": total_teams,
            "rankings":    results,
        })
    except Exception as e:
        return _api_err("Schedule rankings unavailable", e)


@app.route("/<platform>/<int:season>/<league_id>/schedule")
def page_schedule(platform: str, season: int, league_id: str):
    ctx = get_league_ctx_from_cache(platform, league_id, season)
    body = build_schedule_body(ctx)
    return render_page("Schedule Assistant", league_id, "schedule", body, platform, season)


