@app.before_request
def maybe_run_daily():
    global daily_completed
    try:
        today_et: date = datetime.now(EASTERN).date()

        if daily_completed == today_et:
            return

        if daily_lock.acquire(blocking=False):
            try:
                if daily_completed != today_et:
                    logger.info("[daily] Running daily data process for %s (ET)...", today_et)

                    state = get_nfl_state() or {}
                    season = int(state.get("season") or datetime.now().year)
                    week = int(state.get("week") or 0)

                    daily_thread = threading.Thread(
                        target=run_daily_data_async,
                        args=(season, week),
                        daemon=True
                    )
                    daily_thread.start()

                    daily_completed = today_et
            finally:
                daily_lock.release()
    except Exception as _daily_exc:
        logger.warning("[daily] before_request check failed (non-fatal): %s", _daily_exc)




@app.route("/", methods=["GET", "POST"])
def index():
    nfl_state = get_nfl_state() or {}
    current_season = int(nfl_state.get("season") or datetime.now().year)
    viewed_season = current_season

    if request.method == "POST":
        platform = (request.form.get("platform") or "sleeper").strip().lower()
        league_id = (request.form.get("league") or "").strip()
        season = int(request.form.get("season") or viewed_season)
        username = (request.form.get("username") or "").strip()

        ok, err = validate_league_id(platform, league_id)
        if not ok:
            body_html = render_template_string(
                FORM_BODY,
                username=username,
                viewed_season=viewed_season,
                error=err,
                recent_updates=generate_recent_updates_html(),
            )
            return render_page("BR Fantasy Dashboard", None, "home", body_html, lite_js=True)

        # If username/team-name provided, set viewer session
        # For ESPN leagues the "username" field holds the team owner's name or team name
        if username:
            ctx = get_league_ctx_from_cache(platform, league_id, season)
            viewer = resolve_viewer_for_league(ctx["users"], ctx["rosters"], username)

            if viewer:
                save_viewer_session(viewer)
                if platform == "sleeper" and viewer.get("viewer_user_id"):
                    _background_seed_user(viewer["viewer_user_id"], viewer.get("viewer_username"))
            else:
                # For ESPN, skip the hard error - viewer matching is optional
                if platform != "espn":
                    body_html = render_template_string(
                        FORM_BODY,
                        username=username,
                        viewed_season=viewed_season,
                        error="Could not match that username to a team in this league.",
                        recent_updates=generate_recent_updates_html(),
                    )
                    return render_page("BR Fantasy Dashboard", None, "home", body_html, lite_js=True)

        key = _cache_key(platform, season, league_id)
        entry = DASHBOARD_CACHE.get(key)
        if entry and (time.time() - entry["ts"] < CACHE_TTL):
            return redirect(url_for(
                "page_dashboard",
                platform=platform,
                season=season,
                league_id=league_id,
            ))

        ctx = build_league_context(
            platform=platform,
            league_id=league_id,
            season=season,
        )
        DASHBOARD_CACHE[key] = {"ctx": ctx, "ts": time.time(), "page_html": {}}

        # Preload historical season contexts in the background so History/Awards/Graphs
        # pages are fast on first click.
        def _preload_history(p: str, lid: str, s: int) -> None:
            try:
                time.sleep(3)  # let the foreground redirect complete first
                hist_seasons = get_available_history_seasons(p, lid, s)
                for hist_s in hist_seasons[:3]:  # cap at 3 most-recent seasons
                    rid = resolve_league_id_for_season(p, lid, s, hist_s)
                    get_league_ctx_from_cache(p, rid, hist_s)
                    time.sleep(2)  # spread out API load to avoid rate limiting
            except Exception:
                pass

        threading.Thread(
            target=_preload_history, args=(platform, league_id, season), daemon=True
        ).start()

        next_url = (request.form.get("next") or "").strip()
        if next_url and next_url.startswith("/") and not next_url.startswith("//"):
            return redirect(next_url)
        return redirect(url_for(
            "page_dashboard",
            platform=platform,
            season=season,
            league_id=league_id,
        ))

    next_url = (request.args.get("next") or "").strip()
    # Reject open redirects - only allow local paths
    if not (next_url.startswith("/") and not next_url.startswith("//")):
        next_url = ""

    # Signed-in users skip the guest landing page entirely — otherwise they'd see
    # the logged-out "Get started" onboarding underneath their logged-in nav.
    # Send them to ?next= if provided, else their last league dashboard.
    if session.get("viewer_username"):
        if next_url:
            return redirect(next_url)
        _lid = session.get("last_league_id")
        _plt = session.get("last_platform")
        _ssn = session.get("last_season")
        if _lid and _plt and _ssn:
            return redirect(url_for(
                "page_dashboard", platform=_plt, season=int(_ssn), league_id=_lid,
            ))

    body_html = render_template_string(
        FORM_BODY,
        username="",
        viewed_season=viewed_season,
        error=None,
        next_url=next_url,
        recent_updates=generate_recent_updates_html(),
    )
    return render_page(
        "BR Fantasy - Free Fantasy Football Trade Calculator & Dynasty Tools",
        None, "home", body_html,
        description=(
            "Free fantasy football tools for Sleeper, ESPN, and Yahoo: a dynasty and "
            "redraft trade calculator, daily player trade values, real-trade market data, "
            "power rankings, breakout candidates, and advanced metrics."
        ),
        lite_js=True,
    )


@app.route("/api/weekly-week")
def api_weekly_week():
    platform = (request.args.get("platform") or "").strip().lower()
    league_id = (request.args.get("league_id") or "").strip()
    season = int(request.args.get("season") or 0)

    try:
        week = int(request.args.get("week") or 0)
    except ValueError:
        week = 0

    if not league_id or not week:
        return jsonify({"ok": False, "error": "Missing league_id or week"}), 400

    ctx = get_league_ctx_from_cache(platform, league_id, season)

    ensure_weekly_bits(ctx)

    df_weekly = ctx["df_weekly"]
    roster_map = ctx["roster_map"]
    players_map = ctx["players_map"]
    proj_by_week = ctx["proj_by_week"]
    rosters = ctx["rosters"]
    users = ctx["users"]

    team_game_lookup = ctx["team_game_lookup"]
    matchups_by_week = ctx["matchups_by_week"]
    statuses = ctx["statuses"]
    players_index = ctx["players_index"]
    teams_index = ctx["teams_index"]
    season = ctx["season"]
    current_week = ctx["current_week"]
    max_weeks = int(ctx.get("weeks") or 0) or 18

    if week < 1 or week > max_weeks:
        return jsonify({"ok": False, "error": f"Week {week} out of range"}), 400

    if (
            df_weekly is not None
            and not df_weekly.empty
            and "finalized" in df_weekly.columns
            and "week" in df_weekly.columns
    ):
        finalized_df = df_weekly[df_weekly["finalized"] == True].copy()
    else:
        finalized_df = pd.DataFrame()

    if not finalized_df.empty:
        last_final_week = int(finalized_df["week"].max())
    else:
        last_final_week = 0  # no finalized weeks → all weeks show projections

    resolved_league_id = ctx.get("resolved_league_id", league_id)

    top_html = render_weekly_top_scorers_for_week(
        resolved_league_id,
        df_weekly,
        roster_map,
        players_map,
        proj_by_week,
        rosters,
        week,
        users,
        platform,
        season,
        roster_positions=ctx.get("roster_positions") or [],
    )
    _api_proj_by_roster = ctx.get("proj_by_roster") or {}
    highlights_html = _render_weekly_highlights(
        df_weekly, week,
        proj_by_roster=_api_proj_by_roster,
        matchups_by_week=matchups_by_week,
    )

    _api_vid = str((ctx.get("viewer") or {}).get("viewer_roster_id") or "")
    matchups = sorted(
        matchups_by_week.get(week, []) or [],
        key=lambda m: 0 if _api_vid and _api_vid in (str((m.get("left") or {}).get("roster_id", "")), str((m.get("right") or {}).get("roster_id", ""))) else 1,
    )
    status_by_pid = (statuses.get(week) or {}).get("statuses", {}) or {}
    _fpts_against_api = _compute_fpts_against(season)

    # Attach H2H records for this week's matchups
    for _m in matchups:
        _la = str((_m.get("left") or {}).get("roster_id", ""))
        _ra = str((_m.get("right") or {}).get("roster_id", ""))
        if _la and _ra:
            _aw = _bw = 0
            for _wk, _wms in matchups_by_week.items():
                if int(_wk) >= week:
                    continue
                for _wm in _wms:
                    _wla = str((_wm.get("left") or {}).get("roster_id", ""))
                    _wra = str((_wm.get("right") or {}).get("roster_id", ""))
                    if {_wla, _wra} == {_la, _ra}:
                        _lp = (_wm.get("left") or {}).get("pts_total") or 0
                        _rp = (_wm.get("right") or {}).get("pts_total") or 0
                        if _lp == 0 and _rp == 0:
                            continue
                        if (_wla == _la and _lp > _rp) or (_wra == _la and _rp > _lp):
                            _aw += 1
                        else:
                            _bw += 1
            _m["h2h"] = {"left_wins": _aw, "right_wins": _bw}

    slides = [
        render_matchup_slide(
            season,
            m,
            week,
            last_final_week,
            status_by_pid=status_by_pid,
            projections=proj_by_week,
            players=players_index,
            teams=teams_index,
            team_game_lookup=team_game_lookup,
            fpts_against=_fpts_against_api,
        )
        for m in matchups
    ]

    slides_html = "".join(slides) if slides else "<div class='m-empty'>No matchups</div>"
    slides_by_week = {week: slides_html}

    matchups_html = render_matchup_carousel_weeks(
        slides_by_week,
        dashboard=False,
        active_week=week,
    )

    return jsonify({
        "ok": True,
        "top_html": top_html,
        "highlights_html": highlights_html,
        "matchups_html": matchups_html,
    })




@app.route("/api/refresh-page", methods=["POST"])
@limiter.limit("4 per minute")
def api_refresh_page():
    payload = request.get_json(silent=True) or {}
    league_id = (payload.get("league_id") or "").strip()
    platform = (payload.get("platform") or "").strip().lower()
    season = int(payload.get("season") or 0)
    page = (payload.get("page") or "").strip().lower()

    if not league_id or not page:
        return jsonify({"ok": False, "error": "Missing league_id or page"}), 400

    valid_pages = {"activity", "standings", "teams", "weekly", "dashboard", "graphs", "trade"}
    if page not in valid_pages:
        return jsonify({"ok": False, "error": f"Unknown page '{page}'"}), 400

    try:
        ctx = refresh_league_ctx_section(platform, league_id, page, season)

        if page == "dashboard":
            if ctx.get("offseason_mode"):
                body_html = build_offseason_dashboard_body(ctx)
            else:
                ensure_weekly_bits(ctx)
                body_html = build_dashboard_body(ctx)

        elif page == "standings":
            body_html = _build_offseason_standings_body(ctx) if ctx.get("offseason_mode") else build_standings_body(ctx)

        elif page == "weekly":
            if ctx.get("offseason_mode"):
                body_html = """
                <div class="card central">
                  <div class="card-header"><h2>Weekly Hub Unavailable</h2></div>
                  <div class="card-body">
                    <p>The Weekly Hub becomes active once the season begins.</p>
                    <p>Use the dashboard, teams, activity, and trade tools for offseason planning.</p>
                  </div>
                </div>
                """
            else:
                ensure_weekly_bits(ctx)
                body_html = build_weekly_hub_body(ctx)

        elif page == "graphs":
            if ctx.get("offseason_mode"):
                body_html = """
                <div class="card central">
                  <div class="card-header"><h2>Graphs Unavailable</h2></div>
                  <div class="card-body">
                    <p>Weekly scoring graphs will appear once the season begins.</p>
                    <p>During the offseason, use Dashboard, Teams, Activity, and Trade Calc for roster planning.</p>
                  </div>
                </div>
                """
            else:
                body_html = build_graphs_body(ctx)
                store_page_html(platform, season, league_id, "graphs", body_html)

        elif page == "activity":
            body_html = build_activity_body(ctx)
            store_page_html(platform, season, league_id, "activity", body_html)

        elif page == "teams":
            body_html = build_teams_body(ctx)
            store_page_html(platform, season, league_id, "teams", body_html)

        elif page == "trade":
            league_id_safe = ctx.get("league_id") or league_id
            season_safe = int(ctx.get("season") or season or datetime.now().year)
            num_teams = ctx.get("total_rosters") or None
            _ss = ctx.get("scoring_settings") or {}
            rec = float(_ss.get("rec") or 0)
            scoring_format = "ppr" if rec >= 1.0 else "half" if rec >= 0.5 else "std"
            te_premium = float(_ss.get("bonus_rec_te") or 0)
            body_html = build_trade_calculator_body(league_id_safe, season_safe, num_teams=num_teams,
                                                    scoring_format=scoring_format,
                                                    te_premium=te_premium,
                                                    platform=platform)

        else:
            body_html = ""

        return jsonify({
            "ok": True,
            "refreshed_at": datetime.now().isoformat(timespec="seconds"),
            "current_week": ctx.get("current_week"),
            "offseason_mode": bool(ctx.get("offseason_mode")),
            "body_html": body_html,
        })
    except Exception as e:
        return jsonify({
            "ok": False,
            "error": f"Refresh failed: {e}",
        }), 500




# ---------- global cache for model value table used by trade eval ----------
_MODEL_VALUE_CACHE = None
_MODEL_VALUE_CACHE_TS = 0
_MODEL_VALUE_TTL = 60 * 15  # 15 minutes (short enough to reflect daily cron updates promptly)

# Caches for advanced-metrics endpoints (10-minute TTL)
_ROLE_PLAYERS_CACHE: dict = {}
_ROLE_PLAYERS_CACHE_TS: dict = {}
_BREAKOUT_CACHE = None
_BREAKOUT_CACHE_TS = 0.0
_ADVANCED_METRICS_TTL = 600

# Cache for player-details available-years scan (5-minute TTL)
_PLAYER_DETAIL_YEARS_CACHE: set = set()
_PLAYER_DETAIL_YEARS_CACHE_TS = 0.0
_PLAYER_DETAIL_YEARS_TTL = 300

# Cache for per-season usage_rows files (5-minute TTL). One file per season
# (~2 MB) holds every player's season usage; used for the cheap "has game logs"
# rookie signal and PPG ranks in player-details, so we parse each file at most
# once per window instead of on every modal open.
_USAGE_ROWS_CACHE: dict = {}   # season(int) → list[dict]
_USAGE_ROWS_CACHE_TS: dict = {}  # season(int) → float
_USAGE_ROWS_TTL = 300


def _load_usage_rows_cached(season_year: int):
    """Load cache/player_history/usage_rows_<season>.json with a short TTL.

    Returns the parsed list (possibly empty) or None when the file is absent.
    """
    import os as _os, json as _json, time as _time
    now = _time.time()
    ts = _USAGE_ROWS_CACHE_TS.get(season_year, 0.0)
    if season_year in _USAGE_ROWS_CACHE and now - ts < _USAGE_ROWS_TTL:
        return _USAGE_ROWS_CACHE[season_year]
    path = _os.path.join("cache", "player_history", f"usage_rows_{season_year}.json")
    if not _os.path.exists(path):
        return None
    try:
        with open(path) as _f:
            data = _json.load(_f)
    except Exception:
        return None
    _USAGE_ROWS_CACHE[season_year] = data
    _USAGE_ROWS_CACHE_TS[season_year] = now
    return data

# Cache for bulk PPG stats (2-hour TTL) - computed from sleeper_stats files
_PPG_STATS_CACHE: dict = {}   # player_id → {ppg, total_pts, games, season}
_PPG_STATS_CACHE_TS = 0.0
_PPG_STATS_CACHE_TTL = 7200


def _score_stats(s: dict, ss: dict) -> float:
    """Compute fantasy points from a Sleeper stats dict using Sleeper key names."""
    p = 0.0
    p += (s.get("pass_yd") or 0) * (ss.get("pass_yd") or 0.04)
    p += (s.get("pass_td") or 0) * (ss.get("pass_td") or 4.0)
    p += (s.get("pass_int") or 0) * (ss.get("pass_int") or -2.0)
    p += (s.get("rush_yd") or 0) * (ss.get("rush_yd") or 0.1)
    p += (s.get("rush_td") or 0) * (ss.get("rush_td") or 6.0)
    p += (s.get("rec") or 0) * (ss.get("rec") or 0)
    p += (s.get("rec_yd") or 0) * (ss.get("rec_yd") or 0.1)
    p += (s.get("rec_td") or 0) * (ss.get("rec_td") or 6.0)
    p += (s.get("fum_lost") or 0) * (ss.get("fum_lost") or -2.0)
    py = s.get("pass_yd") or 0
    ry = s.get("rush_yd") or 0
    ey = s.get("rec_yd") or 0
    rr = ry + ey
    if py >= 400: p += (ss.get("bonus_pass_yd_400") or 0)
    elif py >= 300: p += (ss.get("bonus_pass_yd_300") or 0)
    if ry >= 200: p += (ss.get("bonus_rush_yd_200") or 0)
    elif ry >= 100: p += (ss.get("bonus_rush_yd_100") or 0)
    if ey >= 200: p += (ss.get("bonus_rec_yd_200") or 0)
    elif ey >= 100: p += (ss.get("bonus_rec_yd_100") or 0)
    if rr >= 200: p += (ss.get("bonus_rush_rec_yd_200") or 0)
    elif rr >= 100: p += (ss.get("bonus_rush_rec_yd_100") or 0)
    return p


def get_model_value_table_cached():
    global _MODEL_VALUE_CACHE, _MODEL_VALUE_CACHE_TS
    now = time.time()
    if _MODEL_VALUE_CACHE is not None and now - _MODEL_VALUE_CACHE_TS < _MODEL_VALUE_TTL:
        return _MODEL_VALUE_CACHE
    # Prefer DB (player_values table) so all endpoints use the same source.
    tbl = None
    try:
        from dashboard_services.player_value_history import load_current_values_from_db
        tbl = load_current_values_from_db() or None
    except Exception as _e:
        logger.info(f"[model-value-cache] DB load failed: {_e}")
    if not tbl:
        tbl = list(load_model_value_table() or [])

    # Snapshot raw player_values data before FC zeroing so the rookie append
    # block can recover values for rookies that get zeroed (not in FC list).
    _pv_raw: dict = {str(p.get("id") or ""): dict(p) for p in (tbl or []) if p.get("id")}

    # Zero out players not tracked by any external market source (FC or DP).
    # The ML model assigns some value to every player in the index; without this
    # guard, washed-up vets and low-usage players leak into the rankings.
    # We only do the presence check - DB values for tracked players are untouched.
    if tbl:
        try:
            from data_building.external_data.external_values_scraper import (
                load_fantasycalc_api_values, load_dynastyprocess_values,
            )
            from utils.utils import normalize_name as _nn

            _fc_sids: set = set()
            for _r in (load_fantasycalc_api_values() or []):
                _sid = str(_r.get("sleeper_id") or "").strip()
                if _sid:
                    _fc_sids.add(_sid)

            _dp_names: set = set()
            for _r in (load_dynastyprocess_values() or []):
                _nm = str(_r.get("player") or "").strip()
                if _nm:
                    _dp_names.add(_nn(_nm))

            if _fc_sids or _dp_names:
                try:
                    from utils.utils import load_players_index as _lpi2
                    _pid_to_name = {str(k): (v.get("name") or "") for k, v in (_lpi2() or {}).items()}
                except Exception:
                    _pid_to_name = {}

                _zeroed = 0
                for _p in tbl:
                    _pid  = str(_p.get("id") or "")
                    _pos  = str(_p.get("position") or "").upper()
                    if _pos == "PICK":
                        continue  # picks have no FC entry, always keep
                    if _pid in _fc_sids:
                        continue  # tracked by FC - keep DB value as-is
                    _p["value"]    = 0
                    _p["sf_value"] = 0
                    _zeroed += 1
                if _zeroed:
                    logger.info(f"[model-value-cache] zeroed {_zeroed} players not in FC")
        except Exception as _e:
            logger.info(f"[model-value-cache] FC/DP presence filter skipped: {_e}")

    # Append rookie prospects for players not already tracked in player_values.
    # player_values (EMA-synced from player_value_history) takes priority when a
    # rookie already has a history value - this keeps rankings consistent with
    # the values shown everywhere else on the site.  The pipeline only fills in
    # true gaps: undrafted prospects or newly-signed players not yet in the DB.
    try:
        from data_building.rookie_pipeline.pipeline import get_rookie_rankings_from_db, get_active_rookie_class
        from utils.utils import load_players_index as _mvc_lpi
        draft_year = get_active_rookie_class()
        rk_rows = list(get_rookie_rankings_from_db(draft_year))
        if rk_rows:
            _mvc_idx = _mvc_lpi() or {}
            # IDs already present in player_values with a real value after FC zeroing
            _existing_ids = {str(p.get("id") or "") for p in tbl if float(p.get("value") or 0) > 0}
            for r in rk_rows:
                sid  = str(r.get("sleeper_id")) if r.get("sleeper_id") else None
                name = r.get("name") or ""
                _rid = sid if sid else (r.get("player_id") or f"rookie_{name}")
                # Skip if already showing with a real value
                if str(_rid) in _existing_ids:
                    continue
                _idx_team = _mvc_idx.get(sid, {}).get("team", "") if sid else ""
                _team = r.get("actual_nfl_team") or _idx_team or r.get("team") or "FA"
                # Prefer raw player_values (may have been zeroed by FC filter but
                # the DB value is still correct). Fall back to rookie_value.
                _pv = _pv_raw.get(sid or "") if sid else None
                _v1  = float((_pv or {}).get("value") or 0) or float(r.get("rookie_value") or 0)
                _vsf = float((_pv or {}).get("sf_value") or 0) or float(r.get("rookie_sf_value") or r.get("rookie_value") or 0)
                tbl.append({
                    "id":        _rid,
                    "name":      name,
                    "team":      _team,
                    "position":  r.get("position") or "UNK",
                    "age":       r.get("age"),
                    "value":     _v1,
                    "sf_value":  _vsf,
                    "is_rookie": True,
                })
    except Exception as e:
        logger.info(f"[model-value-cache] rookies skipped: {e}")

    # Recompute pos_rank after rookies are appended (rookies were added after the
    # earlier rank pass, so they would otherwise always have pos_rank=None)
    if tbl:
        from collections import defaultdict as _dd2
        def _rerank(table, val_key, rank_key, label_key):
            _grp = _dd2(list)
            for _i, _p in enumerate(table):
                _pos = str(_p.get("position") or "").upper()
                if _pos and _pos != "PICK":
                    _grp[_pos].append(_i)
            for _pos, _idxs in _grp.items():
                _idxs.sort(key=lambda _i: float(table[_i].get(val_key) or 0), reverse=True)
                for _rank, _i in enumerate(_idxs, 1):
                    table[_i][rank_key]  = _rank
                    table[_i][label_key] = f"{_pos}{_rank}"
        _rerank(tbl, "value",    "pos_rank",    "pos_rank_label")
        _rerank(tbl, "sf_value", "sf_pos_rank", "sf_pos_rank_label")

    _MODEL_VALUE_CACHE = tbl
    _MODEL_VALUE_CACHE_TS = now
    return tbl


@app.route("/api/flush-value-cache", methods=["POST"])
@limiter.limit("10 per minute")
def api_flush_value_cache():
    """
    Clear the in-memory model value cache so the next request fetches fresh data
    from the DB. Useful right after a cron run without restarting the app.

    Caller must pass the correct CRON_SECRET (same env var used by the cron job).
    """
    secret = os.environ.get("CRON_SECRET", "")
    provided = (request.get_json(force=True, silent=True) or {}).get("secret", "")
    # Require the secret to be set AND match - when CRON_SECRET is unset the
    # old `if secret and …` guard would pass any request (short-circuit on falsy).
    if not secret or provided != secret:
        return jsonify({"error": "unauthorized"}), 403

    global _MODEL_VALUE_CACHE, _MODEL_VALUE_CACHE_TS
    _MODEL_VALUE_CACHE    = None
    _MODEL_VALUE_CACHE_TS = 0
    # Also drop the advanced-metrics daily caches (value table, position ranks,
    # metric leaderboards) so the page/modals serve freshly rebuilt values.
    try:
        from data_building.advanced_metrics import clear_daily_caches
        clear_daily_caches()
    except Exception:
        logger.debug("[flush-value-cache] adv-metrics cache clear failed", exc_info=True)
    return jsonify({"ok": True, "message": "Model value + advanced-metrics caches cleared - next request will reload from DB."})


@app.route("/api/run-daily-cron", methods=["POST"])
@limiter.limit("5 per hour")
def api_run_daily_cron():
    """
    Trigger a full cron_daily run in a background thread.

    Caller must pass the correct CRON_SECRET:
        curl -X POST /api/run-daily-cron -H 'Content-Type: application/json' \\
             -d '{"secret": "<CRON_SECRET>"}'

    Optional: pass "force": true to delete model_values.json first so all
    freshness guards are bypassed and values are fully rebuilt from scratch.

    Returns immediately; the cron runs in the background (check server logs).
    """
    secret   = os.environ.get("CRON_SECRET", "")
    body     = request.get_json(force=True, silent=True) or {}
    provided = body.get("secret", "")
    if not secret or provided != secret:
        return jsonify({"error": "unauthorized"}), 403

    force = bool(body.get("force", False))

    def _run_cron(force_rebuild: bool):
        from utils.paths import DATA_DIR
        try:
            if force_rebuild:
                # Remove model_values.json so freshness guards are all bypassed
                _mv = DATA_DIR / "model_values.json"
                if _mv.exists():
                    _mv.unlink()
                    logger.info("[run-daily-cron] Deleted %s to force full rebuild", _mv)
                # The board anchors the top-5 average to 999.9 fresh each run (no
                # basket EMA state to reset). Deleting model_values.json above also
                # means this forced run rebuilds unclamped, then subsequent daily
                # runs apply the ±10% per-player move clamp from there.
                # Set env var so cron_daily.main() also bypasses freshness guards
                os.environ["CRON_FORCE_REBUILD"] = "1"
            from cron_daily import main as _cron_main
            logger.info("[run-daily-cron] Starting (force=%s)", force_rebuild)
            _cron_main()
            # Flush the in-memory cache so the fresh values are served immediately
            global _MODEL_VALUE_CACHE, _MODEL_VALUE_CACHE_TS
            _MODEL_VALUE_CACHE    = None
            _MODEL_VALUE_CACHE_TS = 0
            try:
                from data_building.advanced_metrics import clear_daily_caches
                clear_daily_caches()
            except Exception:
                logger.debug("[run-daily-cron] adv-metrics cache clear failed", exc_info=True)
            logger.info("[run-daily-cron] Completed - cache flushed")
        except Exception as _e:
            logger.error("[run-daily-cron] Failed: %s", _e, exc_info=True)

    threading.Thread(target=_run_cron, args=(force,), daemon=True).start()
    return jsonify({
        "ok":     True,
        "force":  force,
        "message": "Daily cron triggered in background - check server logs for progress.",
    })


@app.route("/api/debug-values")
@limiter.limit("30 per minute")
def api_debug_values():
    """
    Diagnostic endpoint: returns DB values vs calibrated values for the top 10
    players by value_1qb. Useful for confirming whether WLS calibration is
    actually being written to the DB and whether values are changing.
    """
    try:
        from dashboard_services.db import get_conn as _gc
        with _gc() as _conn:
            rows = _conn.execute(
                """
                SELECT
                    player_id,
                    position,
                    value_1qb,
                    calibrated_value_1qb,
                    calibrated_value_sf,
                    calibration_source,
                    calibration_weight,
                    last_updated
                FROM player_values
                WHERE value_1qb IS NOT NULL AND value_1qb > 0
                  AND (position IS NULL OR position != 'PICK')
                ORDER BY value_1qb DESC NULLS LAST
                LIMIT 20
                """
            ).fetchall()
        from pathlib import Path as _Path
        import time as _time
        from utils.paths import DATA_DIR
        _mv_path = DATA_DIR / "model_values.json"
        _mv_mtime = (
            datetime.fromtimestamp(_mv_path.stat().st_mtime).isoformat()
            if _mv_path.exists() else "missing"
        )
        _cache_age = round(_time.time() - _MODEL_VALUE_CACHE_TS) if _MODEL_VALUE_CACHE_TS else None
        _basket_state = None
        _headroom_state = None
        try:
            from data_building.value_model_training import _load_state, _BASKET_STATE_KEY, _HEADROOM_STATE_KEY
            _basket_state = _load_state(_BASKET_STATE_KEY)
            _headroom_state = _load_state(_HEADROOM_STATE_KEY)
        except Exception:
            pass
        return jsonify({
            "model_values_json_mtime": _mv_mtime,
            "in_memory_cache_age_seconds": _cache_age,
            "in_memory_cache_size": len(_MODEL_VALUE_CACHE) if _MODEL_VALUE_CACHE else 0,
            "pipeline_state": {
                "basket_1qb": _basket_state,
                "headroom_1qb": _headroom_state,
                "note": "basket near 999.9 means _1qb_scale≈1.0 → top players capped at 999.9; reset via POST /api/run-daily-cron with force:true",
            },
            "top_players": [
                {
                    "player_id":              str(r["player_id"]),
                    "position":               str(r["position"] or ""),
                    "value_1qb":              float(r["value_1qb"] or 0),
                    "calibrated_value_1qb":   float(r["calibrated_value_1qb"]) if r["calibrated_value_1qb"] is not None else None,
                    "calibrated_value_sf":    float(r["calibrated_value_sf"])  if r["calibrated_value_sf"]  is not None else None,
                    "calibration_source":     str(r["calibration_source"] or ""),
                    "calibration_weight":     float(r["calibration_weight"]) if r["calibration_weight"] is not None else None,
                    "last_updated":           r["last_updated"].isoformat() if r["last_updated"] else None,
                    "coalesce_gives":         float(r["calibrated_value_1qb"] if r["calibrated_value_1qb"] is not None else r["value_1qb"] or 0),
                }
                for r in rows
            ],
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500


