@app.route("/api/trade-outcome", methods=["POST"])
@limiter.limit("10 per minute")
def api_trade_outcome():
    """
    Compare the value delta of a past trade vs current values.
    Expects: {assets_received: [{id, name}], assets_sent: [{id, name}], trade_date: 'YYYY-MM-DD'}
    """
    from dashboard_services.player_value_history import get_player_value_history
    from dashboard_services.db import get_conn

    payload = request.get_json(force=True)
    assets_received = payload.get("assets_received") or []
    assets_sent = payload.get("assets_sent") or []

    if not assets_received and not assets_sent:
        logger.warning("[api-trade-outcome] 400 error: No assets provided. Payload: %s", payload)
        return jsonify({"error": "No assets provided", "debug": payload}), 400

    try:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        from dashboard_services.picks import load_pick_value_table
        
        # Use the same value source as the player modal so all values are consistent.
        value_table = get_model_value_table_cached() or []
        values_now = {
            str(p["id"]): float(p.get("value") or 0)
            for p in value_table
            if isinstance(p, dict) and p.get("id") and float(p.get("value") or 0) > 0
        }
        
        # Load pick values for pick asset handling
        pick_values = load_pick_value_table()

        trade_date = str(payload.get("trade_date") or "")

        def get_value_at_trade(pid: str):
            """Return the closest historical value to trade_date within 30 days, or None."""
            if not trade_date:
                return None
            from datetime import date as _date
            try:
                target = _date.fromisoformat(trade_date[:10])
            except ValueError:
                return None
            history = get_player_value_history(pid, days=800)
            if not history:
                return None

            best_val = None
            best_diff = float("inf")
            for snap in history:
                snap_date_str = str(snap.get("as_of_date") or "")[:10]
                if not snap_date_str:
                    continue
                try:
                    diff = abs((_date.fromisoformat(snap_date_str) - target).days)
                    if diff < best_diff:
                        best_diff = diff
                        best_val = float(snap.get("value") or 0)
                except (ValueError, TypeError):
                    continue

            # No snapshot within 30 days of the trade date - too stale to compare
            if best_diff > 30 or not best_val:
                return None
            return round(best_val, 1)
        
        def get_pick_value(asset: dict) -> float:
            """Get current pick value, preferring WLS-derived bucket values."""
            try:
                rd = int(asset.get("pick_round") or 4)
            except (ValueError, TypeError):
                rd = 4
            try:
                year = int(asset.get("pick_season") or asset.get("pick_year") or
                           (trade_date[:4] if trade_date else datetime.now().year))
            except (ValueError, TypeError):
                year = datetime.now().year

            # Exact slot lookup (e.g. "2026_1_06")
            slot = asset.get("pick_slot")
            if slot:
                try:
                    key = f"{year}_{rd}_{int(slot):02d}"
                    if key in pick_values:
                        return float(pick_values[key])
                except (ValueError, TypeError):
                    pass

            # Bucket lookup - derive bucket from slot if pick_order is absent
            order = asset.get("pick_order")
            if not order and slot:
                try:
                    s = int(slot)
                    order = "early" if s <= 4 else ("mid" if s <= 8 else "late")
                except (ValueError, TypeError):
                    pass
            order = order or "mid"

            if order in ("early", "mid", "late"):
                key = f"{year}_{rd}_{order}"
                if key in pick_values:
                    return float(pick_values[key])

            key = f"{year}_{rd}"
            if key in pick_values:
                return float(pick_values[key])

            return 10.0

        all_assets = [("received", a) for a in assets_received] + [("sent", a) for a in assets_sent]
        all_pids = [(side, str(a.get("id") or ""), str(a.get("name") or a.get("id") or "")) for side, a in all_assets]

        # Fetch historical values in parallel - only store when we found a reliable snapshot
        then_values: dict[str, float] = {}
        if trade_date:
            with ThreadPoolExecutor(max_workers=min(len(all_pids), 8)) as pool:
                futures = {pool.submit(get_value_at_trade, pid): pid for _, pid, _ in all_pids if pid}
                for fut in as_completed(futures):
                    pid = futures[fut]
                    try:
                        result = fut.result()
                        if result is not None:
                            then_values[pid] = result
                    except Exception:
                        pass  # Leave absent - _build_row treats missing pid as None

        received_rows = []
        sent_rows = []
        total_received_now = 0.0
        total_sent_now = 0.0
        total_received_then = 0.0
        total_sent_then = 0.0

        def _pick_now_value(pid: str, asset: dict) -> float:
            """Look up calibrated pick value trying multiple ID formats."""
            # Try as-is (e.g. "2026 1.01")
            v = values_now.get(pid, 0.0)
            if v:
                return v
            # Try underscore format (e.g. "2026_1_01")
            underscore_pid = pid.replace(" ", "_", 1).replace(".", "_", 1)
            v = values_now.get(underscore_pid, 0.0)
            if v:
                return v
            # Fall back to pick table
            return get_pick_value(asset)

        def _build_row(asset: dict, side: str) -> dict:
            pid = str(asset.get("id") or "")
            name = str(asset.get("name") or pid)
            is_pick = asset.get("asset_type") == "pick"
            if is_pick:
                now = _pick_now_value(pid, asset)
                then = None
            else:
                now = values_now.get(pid, 0.0)
                then = then_values.get(pid, None) if trade_date else None
            return {
                "id": pid, "name": name, "is_pick": is_pick,
                "value_now": round(now, 1),
                "value_then": round(then, 1) if then is not None else None,
                "delta": round(now - then, 1) if then is not None else None,
                "_now": now, "_then": then,
            }

        for asset in assets_received:
            row = _build_row(asset, "received")
            total_received_now += row["_now"]
            if row["_then"] is not None:
                total_received_then += row["_then"]
            del row["_now"], row["_then"]
            received_rows.append(row)

        for asset in assets_sent:
            row = _build_row(asset, "sent")
            total_sent_now += row["_now"]
            if row["_then"] is not None:
                total_sent_then += row["_then"]
            del row["_now"], row["_then"]
            sent_rows.append(row)

        net_delta_now = round(total_received_now - total_sent_now, 1)
        net_delta_then = round(total_received_then - total_sent_then, 1)

        if net_delta_now > 150:
            verdict = "WIN"
        elif net_delta_now < -150:
            verdict = "LOSS"
        else:
            verdict = "EVEN"

        return jsonify({
            "success": True,
            "verdict": verdict,
            "net_delta_now": net_delta_now,
            "net_delta_then": net_delta_then,
            "total_received_now": round(total_received_now, 1),
            "total_sent_now": round(total_sent_now, 1),
            "received": received_rows,
            "sent": sent_rows,
        })
    except Exception as e:
        logger.exception("[api-trade-outcome] Error: %s", e)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/trade-eval", methods=["POST"])
@limiter.limit("30 per minute")
def api_trade_eval():
    try:
        payload = request.get_json(force=True) or {}
    except Exception:
        return jsonify({"error": "Invalid JSON payload"}), 400

    league_id = str(payload.get("league_id") or "").strip()
    season = int(payload.get("season") or datetime.now().year)
    platform = str(payload.get("platform") or "sleeper").strip().lower()
    league_type = str(payload.get("league_type") or "1qb").strip().lower()
    league_size = int(payload.get("league_size") or 10)
    scoring_format = str(payload.get("scoring_format") or "ppr").strip().lower()
    scoring_type = str(payload.get("scoring_type") or "dynasty").strip().lower()
    try:
        te_premium = float(payload.get("te_premium") or 0)
    except Exception:
        te_premium = 0.0
    viewer_side = (payload.get("viewer_side") or "a").strip().lower()

    # Position-based multipliers for non-PPR formats.
    # RBs gain value in standard (rush-heavy); WRs/TEs lose value (fewer receptions).
    _SCORING_MULTS = {
        "ppr": {"QB": 1.00, "RB": 1.00, "WR": 1.00, "TE": 1.00},
        "half": {"QB": 1.00, "RB": 1.06, "WR": 0.97, "TE": 0.94},
        "std": {"QB": 1.00, "RB": 1.13, "WR": 0.93, "TE": 0.87},
    }
    scoring_mults = _SCORING_MULTS.get(scoring_format, _SCORING_MULTS["ppr"])

    side_a_players = [str(pid) for pid in payload.get("side_a_players", [])]
    side_b_players = [str(pid) for pid in payload.get("side_b_players", [])]
    side_a_picks = payload.get("side_a_picks", []) or []
    side_b_picks = payload.get("side_b_picks", []) or []

    # Use DB as primary source (same as api_league_players) so chip values and
    # team totals always draw from the same number.  Fall back to JSON if DB unavailable.
    try:
        from dashboard_services.player_value_history import load_current_values_from_db as _lcvdb
        value_table = _lcvdb() or get_model_value_table_cached()
    except Exception:
        value_table = get_model_value_table_cached()

    if not isinstance(value_table, list):
        raise ValueError("model_value_table must be a list of player objects")

    players_by_id = {
        str(p["id"]): p
        for p in value_table
        if isinstance(p, dict) and "id" in p
    }

    pick_values = load_pick_value_table()

    def value_pick(pk: str) -> float:
        try:
            yr_str, rnd_str, slot_str = pk.split("_")
            year = int(yr_str)
            rnd = int(rnd_str)
        except Exception:
            return 0.0

        key = f"{year}_{rnd}_{slot_str}"

        val = pick_values.get(key)
        if val is not None:
            return float(val)

        generic_key = f"any_{rnd}_{slot_str}"
        if generic_key in pick_values:
            return float(pick_values[generic_key])

        return 0.0

    def build_side(players_ids, picks_ids):
        raw_players_total = 0.0
        raw_picks_total = 0.0
        player_values = []
        breakdown = []
        assets = []

        for pid in players_ids:
            pid_str = str(pid)
            player = players_by_id.get(pid_str)

            if not player:
                breakdown.append({
                    "type": "player",
                    "id": pid_str,
                    "name": f"Player {pid_str}",
                    "value": 0.0,
                    "position": None,
                    "team": None,
                })
                assets.append({
                    "id": pid_str,
                    "name": f"Player {pid_str}",
                    "value": 0.0,
                    "position": None,
                    "team": None,
                    "age": None,
                })
                continue

            # Use size/type-specific value, falling back to 10-team then base value.
            # Redraft values are league-size agnostic (1QB vs SF only).
            if scoring_type == "redraft":
                val = float(
                    player.get("redraft_value_sf") or player.get("redraft_value_1qb") or 0.0
                ) if league_type == "sf" else float(player.get("redraft_value_1qb") or 0.0)
            elif league_type == "sf":
                size_key = "sf_value" if league_size == 10 else f"sf_value_{league_size}"
                val = float(player.get(size_key) or player.get("sf_value") or player.get("value") or 0.0)
            else:
                size_key = "value" if league_size == 10 else f"value_{league_size}"
                val = float(player.get(size_key) or player.get("value") or 0.0)

            name = player.get("name")
            pos = player.get("position")

            # Apply scoring format multiplier, plus TE-premium boost for tight ends.
            _mult = scoring_mults.get((pos or "").upper(), 1.0)
            if te_premium and (pos or "").upper() == "TE":
                _mult *= (1 + te_premium * 0.20)
            val = round(val * _mult, 1)
            team = player.get("team")
            age = player.get("age")

            breakdown.append({
                "type": "player",
                "id": pid_str,
                "name": name,
                "value": val,
                "position": pos,
                "team": team,
            })
            assets.append({
                "id": pid_str,
                "name": name,
                "value": val,
                "position": pos,
                "team": team,
                "age": age,
                "pos_rank_label": player.get("pos_rank_label") or "",
                "rank_change_7d": player.get("rank_change_7d"),
            })

            raw_players_total += val
            player_values.append(val)

        for pk in picks_ids:
            pk_str = str(pk)
            val = float(value_pick(pk_str))
            breakdown.append({
                "type": "pick",
                "id": pk_str,
                "value": val,
            })
            raw_picks_total += val
            # Also add pick to assets array
            assets.append({
                "id": pk_str,
                "name": pk_str,  # Will be cleaned up in renderer
                "position": "PICK",
                "team": "",
                "age": None,
                "value": val,
            })

        raw_total = raw_players_total + raw_picks_total

        return {
            "raw_total": raw_total,
            "raw_players_total": raw_players_total,
            "raw_picks_total": raw_picks_total,
            "player_values": player_values,
            "breakdown": breakdown,
            "assets": assets,
            "pick_ids": [str(pk) for pk in picks_ids],
            "effective_total": raw_total,
            "adjustment": 0.0,
        }

    side_a = build_side(side_a_players, side_a_picks)
    side_b = build_side(side_b_players, side_b_picks)

    tier_thresholds = compute_tier_thresholds(value_table, league_type, league_size)
    # Only apply depth adjustment when BOTH sides have assets and the counts
    # differ. A one-sided trade (nothing on the other side) has no comparison to
    # make, so each asset should report its full value - no stack penalty.
    side_a_count = len(side_a_players) + len(side_a_picks)
    side_b_count = len(side_b_players) + len(side_b_picks)
    both_sides_filled = side_a_count > 0 and side_b_count > 0
    if both_sides_filled and side_a_count != side_b_count:
        apply_tier_stack_adjustment(side_a, side_b, tier_thresholds, is_sf=(league_type == "sf"), value_table=value_table, league_size=league_size)

    a_eff = side_a["effective_total"]
    b_eff = side_b["effective_total"]

    diff = a_eff - b_eff
    abs_diff = abs(diff)

    # Fair band: tighter % for bigger trades (large trades need less slack),
    # floored at 25 value points so tiny trades aren't hair-trigger.
    baseline = max(a_eff, b_eff, 1.0)
    if baseline >= 600:
        FAIR_PCT = 0.05
    elif baseline >= 300:
        FAIR_PCT = 0.07
    else:
        FAIR_PCT = 0.10
    fair_band = max(baseline * FAIR_PCT, 25.0)

    if abs_diff <= fair_band:
        pct = (abs_diff / baseline) * 100.0
        verdict = f"This trade looks very fair (about {pct:.1f}% apart)."
    elif diff > 0:
        verdict = f"Team 1 is favored by about {abs_diff:.1f} value."
    else:
        verdict = f"Team 2 is favored by about {abs_diff:.1f} value."

    analysis_html = ""
    depth_warnings = {}
    viewer_roster_id = payload.get("viewer_roster_id")
    viewer_team_name = payload.get("viewer_team_name")
    _user_id = session.get("viewer_username")
    _has_premium = has_premium_for_viewer(
        _user_id, session.get("viewer_user_id"), league_id, platform, season
    ) if league_id else False

    if league_id and viewer_roster_id and _has_premium:
        try:
            from dashboard_services.ai.context_builders import calculate_roster_depth_warning, build_model_value_lookup, _ctx_is_sf
            ctx = get_league_ctx_from_cache(platform=platform, league_id=league_id, season=season)
            analysis_html = get_trade_ai_analysis(
                ctx=ctx,
                viewer_roster_id=str(viewer_roster_id),
                viewer_side=viewer_side,
                side_a=side_a,
                side_b=side_b,
            )
            # Compute post-trade depth warnings for the viewer's roster
            rosters = ctx.get("rosters") or []
            viewer_roster = next((r for r in rosters if str(r.get("roster_id")) == str(viewer_roster_id)), None)
            if viewer_roster:
                model_value_lookup = build_model_value_lookup(ctx.get("model_value_table") or [], is_sf=_ctx_is_sf(ctx))
                viewer_gives = side_a if viewer_side == "b" else side_b
                viewer_gets  = side_b if viewer_side == "b" else side_a
                sending = [a for a in (viewer_gives.get("assets") or []) if str(a.get("position") or "").upper() != "PICK"]
                receiving = [a for a in (viewer_gets.get("assets") or []) if str(a.get("position") or "").upper() != "PICK"]
                depth_warnings = calculate_roster_depth_warning(
                    viewer_roster, model_value_lookup, sending, receiving,
                    roster_positions=ctx.get("roster_positions") or [],
                    num_teams=len(rosters) or 12,
                )
        except Exception as e:
            logger.info(f"[trade-ai] skipped: {e}")
            analysis_html = ""

    return jsonify({
        "side_a": side_a,
        "side_b": side_b,
        "diff": diff,
        "abs_diff": abs_diff,
        "fair_threshold": fair_band,
        "fair_pct": FAIR_PCT,
        "verdict": verdict,
        "analysis_html": analysis_html,
        "depth_warnings": depth_warnings,
        "tier_thresholds": [round(t, 1) for t in tier_thresholds],
    })


def _sanitize_for_json(obj):
    """
    Recursively walk obj and replace NaN/inf/-inf floats with None
    so that json.dumps / jsonify produce valid JSON that
    fetch().json() can parse.
    """
    if isinstance(obj, dict):
        return {k: _sanitize_for_json(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_sanitize_for_json(v) for v in obj]
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            return None
    return obj


@app.route("/api/trade-eval/playoff-impact", methods=["POST"])
@limiter.limit("20 per minute")
def api_trade_eval_playoff_impact():
    """
    Return before/after playoff odds and win projections for a proposed trade.
    Requires a league context (league_id + platform).
    """
    try:
        payload = request.get_json(force=True) or {}
    except Exception:
        return jsonify({"error": "Invalid JSON"}), 400

    league_id    = str(payload.get("league_id") or "").strip()
    platform     = str(payload.get("platform") or "sleeper").strip().lower()
    season       = int(payload.get("season") or datetime.now().year)
    roster_id    = payload.get("roster_id")
    give_ids     = [str(p) for p in (payload.get("give_ids") or [])]
    get_ids      = [str(p) for p in (payload.get("get_ids") or [])]

    if not league_id or roster_id is None:
        return jsonify({"available": False, "reason": "no_league"})

    try:
        roster_id = int(roster_id)
    except (TypeError, ValueError):
        return jsonify({"available": False, "reason": "bad_roster_id"})

    if not give_ids and not get_ids:
        return jsonify({"available": False, "reason": "empty_trade"})

    try:
        from data_building.simulate_playoff_odds import (
            build_sim_state as _build_sim_state,
            simulate_swap_impact as _simulate_swap_impact,
        )
        ctx = build_league_context(platform, league_id, season)
        sim_state = _build_sim_state(ctx, platform)
        if sim_state is None:
            return jsonify({"available": False, "reason": "season_complete"})

        result = _simulate_swap_impact(sim_state, roster_id, give_ids, get_ids)

        # Future outlook: value-weighted age + total dynasty value of the
        # players coming in vs going out. This is the counterweight to the
        # win-now playoff metrics - getting younger / banking value is the
        # upside when a deal dents this season's odds (and vice versa).
        is_sf = any(str(s).upper() in {"SUPER_FLEX", "SFLEX"}
                    for s in (ctx.get("roster_positions") or []))
        current_pids = sim_state.get("roster_pid_map", {}).get(roster_id, [])
        result["outlook"] = _trade_future_outlook(give_ids, get_ids, is_sf, current_pids)

        return jsonify(result)

    except Exception:
        logger.exception("[trade-eval/playoff-impact] error")
        return jsonify({"available": False, "reason": "error"})


def _trade_future_outlook(give_ids, get_ids, is_sf=False, current_pids=None):
    """Compute future-outlook signals for the Playoff Impact card.

    When current_pids (the viewer's full roster) is provided, the Roster Age
    signal is the roster-wide value-weighted age before vs after the swap.
    Prime Years Left is always computed from the traded players themselves.
    """
    from utils.utils import load_players_index
    players_index = load_players_index() or {}
    value_table = get_model_value_table_cached() or []
    val_key = "sf_value" if is_sf else "value"
    vmap = {str(p.get("id")): p for p in value_table}

    def _player_val_age(pid):
        mv = vmap.get(str(pid), {})
        meta = players_index.get(str(pid), {}) or {}
        val = safe_float(mv.get(val_key) or mv.get("value") or 0)
        age = age_from_bday(meta.get("bDay")) or mv.get("age") or meta.get("age")
        age = safe_float(age) if age not in (None, "") else None
        return val, age

    def _resolve(pids):
        total_val = 0.0
        age_num = 0.0
        age_den = 0.0
        prime_num = 0.0  # value-weighted prime years remaining (max 0, 30-age)
        prime_den = 0.0
        ages = []
        for pid in pids:
            val, age = _player_val_age(pid)
            total_val += val
            if age:
                ages.append(age)
                if val > 0:
                    age_num += age * val
                    age_den += val
                    prime = max(0.0, 30.0 - age)
                    prime_num += prime * val
                    prime_den += val
        avg_age = round(age_num / age_den, 1) if age_den else (
            round(sum(ages) / len(ages), 1) if ages else None)
        avg_prime = round(prime_num / prime_den, 1) if prime_den else None
        return {
            "total_value": round(total_val, 1),
            "avg_age": avg_age,
            "avg_prime_years": avg_prime,
            "n": len(pids),
        }

    def _roster_avg_age(pids):
        wage_num = 0.0
        wage_den = 0.0
        for pid in pids:
            val, age = _player_val_age(pid)
            if age and val > 0:
                wage_num += age * val
                wage_den += val
        return round(wage_num / wage_den, 1) if wage_den else None

    incoming = _resolve(get_ids)   # players the viewer receives
    outgoing = _resolve(give_ids)  # players the viewer sends away

    value_delta = round(incoming["total_value"] - outgoing["total_value"], 1)

    # Roster-wide age shift (preferred): how the whole team ages after the swap.
    roster_age_before = roster_age_after = age_delta = None
    if current_pids:
        before_set = set(str(p) for p in current_pids)
        after_set = (before_set - set(str(p) for p in give_ids)) | set(str(p) for p in get_ids)
        roster_age_before = _roster_avg_age(before_set)
        roster_age_after = _roster_avg_age(after_set)
        if roster_age_before is not None and roster_age_after is not None:
            # Negative = roster got younger.
            age_delta = round(roster_age_after - roster_age_before, 1)

    # Fallback to traded-players age delta when no roster context is available.
    if age_delta is None and incoming["avg_age"] is not None and outgoing["avg_age"] is not None:
        age_delta = round(incoming["avg_age"] - outgoing["avg_age"], 1)

    return {
        "incoming": incoming,
        "outgoing": outgoing,
        "age_delta": age_delta,                 # < 0 means younger
        "value_delta": value_delta,             # > 0 means banking value
        "roster_age_before": roster_age_before,  # value-weighted roster age pre-swap
        "roster_age_after": roster_age_after,    # value-weighted roster age post-swap
    }


@app.route("/api/players")
def api_players():
    """Compact player list for comparison search. No league context required.

    Query params:
        page  (int, default 1)   -- 1-based page number
        limit (int, default 0)   -- results per page; 0 = return all (legacy)
        q     (str, optional)    -- prefix/substring filter applied before paging
    """
    try:
        from utils.utils import load_players_index
        players_index = load_players_index() or {}
        value_table = get_model_value_table_cached() or []
        value_map = {str(p.get("id")): p for p in value_table}

        results = []
        for pid, meta in players_index.items():
            pos = meta.get("pos", "")
            if pos in ("K", "DEF"):
                continue
            v = value_map.get(str(pid), {})
            results.append({
                "player_id": pid,
                "name": meta.get("name", ""),
                "position": pos,
                "team": meta.get("team", ""),
                "value": v.get("value", 0),
                "sf_value": v.get("sf_value", 0),
                "pos_rank_label": v.get("pos_rank_label", ""),
                "rank_change_7d": v.get("rank_change_7d"),
                "espnHeadshot": meta.get("espnHeadshot", ""),
            })

        # Sort by value descending so most relevant players appear first
        results.sort(key=lambda x: x["value"] or 0, reverse=True)

        # Optional substring filter
        q = request.args.get("q", "").strip().lower()
        if q:
            results = [r for r in results if q in r["name"].lower()]

        # Pagination - limit=0 (default) returns the full list for backwards compat
        total = len(results)
        try:
            limit = max(0, int(request.args.get("limit", 0)))
            page  = max(1, int(request.args.get("page", 1)))
        except (TypeError, ValueError):
            limit, page = 0, 1

        if limit > 0:
            start   = (page - 1) * limit
            results = results[start: start + limit]
            return jsonify({
                "players": results,
                "total":   total,
                "page":    page,
                "pages":   math.ceil(total / limit),
            })

        return jsonify(results)
    except Exception as e:
        logger.exception("[api-players] Unexpected error")
        return _api_err("Request failed", e)


@app.route("/api/sparklines")
def api_sparklines():
    """7-day value history scaled to match the calibrated values shown on the rankings page.
    Joins player_value_history with player_values so each series ends at the same value
    the user sees displayed, matching the approach used by the player modal chart."""
    try:
        from dashboard_services.db import get_conn
        # DB column names in player_value_history (value_sf = base SF, 10-team)
        _db_cols = ["value", "value_sf", "value_8", "value_12", "value_14",
                    "sf_value_8", "sf_value_12", "sf_value_14"]
        with get_conn() as conn:
            rows = conn.execute(
                f"""
                SELECT pvh.player_id,
                       {', '.join('pvh.' + c for c in _db_cols)},
                       pv.calibrated_value_1qb,
                       pv.calibrated_value_sf
                FROM player_value_history pvh
                LEFT JOIN player_values pv USING (player_id)
                WHERE pvh.source = 'model'
                  AND pvh.as_of_date >= CURRENT_DATE - INTERVAL '8 days'
                ORDER BY pvh.player_id, pvh.as_of_date ASC
                """
            ).fetchall()

        by_pid: dict = {}
        for row in rows:
            pid = row["player_id"]
            if pid not in by_pid:
                entry0 = {c: [] for c in _db_cols}
                entry0["cal_1qb"] = row.get("calibrated_value_1qb")
                entry0["cal_sf"]  = row.get("calibrated_value_sf")
                by_pid[pid] = entry0
            for c in _db_cols:
                v = row.get(c)
                if v is not None:
                    by_pid[pid][c].append(float(v))

        result = {}
        for pid, data in by_pid.items():
            base = data.get("value", [])
            if len(base) < 2:
                continue

            # Scale factors: calibrated_current / last_raw so the series ends at
            # the same value the rankings page displays via COALESCE(calibrated, raw).
            last_1qb = base[-1]
            last_sf  = (data.get("value_sf") or [None])[-1]
            cal_1qb  = data["cal_1qb"]
            cal_sf   = data["cal_sf"]
            s1qb = (float(cal_1qb) / last_1qb) if cal_1qb and last_1qb else 1.0
            ssf  = (float(cal_sf)  / last_sf)  if cal_sf  and last_sf  else s1qb

            entry = {}
            for c in _db_cols:
                vals = data[c]
                if len(vals) < 2:
                    continue
                # sf_value_* cols start with "sf_"; value_sf does not - detect by suffix
                is_sf_col = c.startswith("sf_") or c == "value_sf"
                scale = ssf if is_sf_col else s1qb
                # JS expects key "sf_value" (the alias used everywhere in player data)
                out_key = "sf_value" if c == "value_sf" else c
                entry[out_key] = [round(v * scale, 1) for v in vals]

            if entry:
                result[pid] = entry

        resp = jsonify(result)
        resp.headers["Cache-Control"] = "public, max-age=3600"
        return resp
    except Exception as e:
        return _api_err("Sparklines unavailable", e)


@app.route("/api/league-players")
def api_league_players():
    try:
        model_value_table = [dict(p) for p in (get_model_value_table_cached() or [])]
    except Exception as e:
        logger.info(f"[api/league-players] Cache load failed: {e}")
        model_value_table = []

    if not isinstance(model_value_table, list):
        raise ValueError("model_value_table must be a list of player objects")

    # DB values are preferred (more accurate); WLS fills in bucket picks or any gaps.
    try:
        from dashboard_services.picks import load_pick_value_table as _lpvt
        _pick_values = _lpvt()
        _db_pick_ids: set = {
            str(p.get("id") or "") for p in model_value_table
            if str(p.get("position") or "").upper() == "PICK"
        }
        # Build pick-type sets per (year, round) - slot > bucket > generic hierarchy.
        _bucket_keywords = {"early", "mid", "late"}
        _slot_yr_rnd: set = set()
        _bucket_yr_rnd: set = set()
        for _pid in _db_pick_ids:
            _pp = _pid.split("_")
            if len(_pp) >= 3:
                _key = (_pp[0], _pp[1])
                if _pp[2].lower() in _bucket_keywords:
                    _bucket_yr_rnd.add(_key)
                else:
                    try:
                        int(_pp[2])
                        _slot_yr_rnd.add(_key)
                    except ValueError:
                        pass

        _injected_picks = []
        _seen_ids: set = set(_db_pick_ids)
        for _pk_id, _pk_val in _pick_values.items():
            if _pk_id in _seen_ids or float(_pk_val) <= 0:
                continue
            _parts = _pk_id.split("_")
            if len(_parts) >= 2:
                _key = (_parts[0], _parts[1])
                _is_generic = len(_parts) == 2
                _is_bucket = len(_parts) >= 3 and _parts[2].lower() in _bucket_keywords
                if _key in _slot_yr_rnd and (_is_generic or _is_bucket):
                    continue
                if _key in _bucket_yr_rnd and _is_generic:
                    continue
            _seen_ids.add(_pk_id)
            # Format display name: "2026_1_01" -> "2026 1.01", "2026_1_early" -> "2026 1st (Early)"
            if len(_parts) >= 3:
                _yr, _rnd_s, _third = _parts[0], _parts[1], "_".join(_parts[2:])
                try:
                    _rnd = int(_rnd_s)
                    _sfx = {1:"st",2:"nd",3:"rd"}.get(_rnd,"th")
                    _bkt = {"early":"Early","mid":"Mid","late":"Late"}.get(_third.lower())
                    if _bkt:
                        _name = f"{_yr} {_rnd}{_sfx} ({_bkt})"
                    else:
                        _name = f"{_yr} {_rnd}.{int(_third):02d}"
                except (ValueError, TypeError):
                    _name = _pk_id.replace("_", " ")
            else:
                _name = _pk_id.replace("_", " ")
            _injected_picks.append({
                "id": _pk_id, "name": _name, "position": "PICK",
                "value": round(float(_pk_val), 1), "team": "",
            })
        model_value_table.extend(_injected_picks)
        logger.info(f"[api/league-players] DB picks: {len(_db_pick_ids)}, WLS fallback picks: {len(_injected_picks)}")

        # Rebuild slot/bucket sets to include WLS-injected picks so the model
        # injection below correctly suppresses bucket picks when slots exist.
        for _p in _injected_picks:
            _pp2 = str(_p.get("id") or "").split("_")
            if len(_pp2) >= 3:
                _k2 = (_pp2[0], _pp2[1])
                if _pp2[2].lower() in _bucket_keywords:
                    _bucket_yr_rnd.add(_k2)
                else:
                    try:
                        int(_pp2[2])
                        _slot_yr_rnd.add(_k2)
                    except ValueError:
                        pass

        # Inject model_values.json bucket picks, preferring them over WLS for
        # future years (WLS bucket values are in WLS units; model values are
        # pre-calibrated to the 0-999.9 model scale).
        # Current-year slot picks (already FC-normalized in picks.py) are kept.
        try:
            _cur_year = str(date.today().year)
            # Load picks directly from model_values.json - get_model_value_table_cached()
            # returns DB players (non-empty) so never falls back to model_values.json picks.
            _raw_model = load_model_value_table(apply_calibration=False) or []
            _json_picks = [p for p in _raw_model
                           if str(p.get("position") or "").upper() == "PICK"]
            _all_seen = {str(p.get("id") or "") for p in model_value_table
                         if str(p.get("position") or "").upper() == "PICK"}
            _json_injected = 0
            for _jp in _json_picks:
                _jid = str(_jp.get("id") or "")
                if not _jid:
                    continue
                _jparts = _jid.split("_")
                _jyear = _jparts[0] if _jparts else ""
                _jis_bucket = (len(_jparts) >= 3 and
                               _jparts[2].lower() in _bucket_keywords)
                _jis_generic = len(_jparts) == 2

                # Skip if slot picks for this year+round already exist
                if len(_jparts) >= 2:
                    _jkey = (_jparts[0], _jparts[1])
                    if _jkey in _slot_yr_rnd and (_jis_generic or _jis_bucket):
                        continue
                    if _jkey in _bucket_yr_rnd and _jis_generic:
                        continue

                # For future years, model bucket picks override WLS bucket picks.
                # For the current year, only add picks not already present.
                if _jid in _all_seen:
                    if _jyear == _cur_year or not _jis_bucket:
                        continue
                    # Replace the WLS entry with the model value
                    for _i, _existing in enumerate(model_value_table):
                        if str(_existing.get("id") or "") == _jid:
                            model_value_table[_i] = _jp
                            break
                else:
                    _all_seen.add(_jid)
                    model_value_table.append(_jp)
                _json_injected += 1
            if _json_injected:
                logger.info(f"[api/league-players] model_values.json picks injected/overridden: {_json_injected}")
        except Exception as _e_json_picks:
            pass
    except Exception as _e_picks:
        logger.info(f"[api/league-players] pick injection skipped: {_e_picks}")

    # Compute rank_change_7d from player-only pool (QB/RB/WR/TE) so that picks
    # and newly-added rookies don't distort movement arrows on the rankings page.
    # Current rank = position in value-sorted player list; historical rank from DB snapshot.
    _PLAYER_POSITIONS = {"QB", "RB", "WR", "TE"}
    try:
        from data_building.update_player_values_with_rankings import _load_historical_ranks as _lhr
        from datetime import timedelta as _td

        # Cache historical ranks by date so we don't hit DB on every request
        _today = date.today()
        _hist_cache_key = f"_hist_ranks_{_today}"
        _hist_ranks = getattr(app, _hist_cache_key, None)
        if _hist_ranks is None:
            _hist_ranks = _lhr(_today - _td(days=7))
            setattr(app, _hist_cache_key, _hist_ranks)

        # Current player-only rank: sort QB/RB/WR/TE by value descending
        _player_rows = sorted(
            [p for p in model_value_table
             if isinstance(p, dict) and str(p.get("position", "")).upper() in _PLAYER_POSITIONS],
            key=lambda p: float(p.get("value") or 0),
            reverse=True,
        )
        _cur_rank_map = {str(p.get("id") or ""): idx + 1 for idx, p in enumerate(_player_rows)}

        for _p in model_value_table:
            _pid = str(_p.get("id") or "")
            _cur = _cur_rank_map.get(_pid)
            _hist = _hist_ranks.get(_pid)
            if _cur is not None and _hist:
                _p["rank_change_7d"] = _hist["overall_rank"] - _cur
            # leave rank_change_7d as-is (None or from JSON) for non-player-pos entries
    except Exception:
        # Fall back to DB-stored values if recomputation fails
        try:
            from dashboard_services.db import get_conn as _gc
            with _gc() as _rc:
                _rk_rows = _rc.execute(
                    "SELECT player_id, rank_change_7d FROM player_values WHERE rank_change_7d IS NOT NULL"
                ).fetchall()
            _rk_map = {str(r["player_id"]): r["rank_change_7d"] for r in _rk_rows}
            for _p in model_value_table:
                _pid = str(_p.get("id") or "")
                if _pid in _rk_map:
                    _p["rank_change_7d"] = _rk_map[_pid]
        except Exception:
            pass

    # Attach redraft values from the DB so the rankings/trade tools can offer a
    # Dynasty↔Redraft toggle (model_values.json only carries dynasty values).
    try:
        from dashboard_services.db import get_conn as _gc
        with _gc() as _rc:
            _rd_rows = _rc.execute(
                "SELECT player_id, redraft_value_1qb, redraft_value_sf "
                "FROM player_values "
                "WHERE redraft_value_1qb IS NOT NULL OR redraft_value_sf IS NOT NULL"
            ).fetchall()
        _rd_map = {str(r["player_id"]): r for r in _rd_rows}
        for _p in model_value_table:
            _r = _rd_map.get(str(_p.get("id") or ""))
            if _r:
                _p["redraft_value_1qb"] = _r["redraft_value_1qb"]
                _p["redraft_value_sf"] = _r["redraft_value_sf"]
    except Exception as _e_rd:
        logger.info(f"[api/league-players] redraft values skipped: {_e_rd}")

    try:
        from data_building.rookie_pipeline.pipeline import (
            get_rookie_rankings_from_db,
            get_active_rookie_class,
        )
        from utils.utils import normalize_name as _nn, load_players_index as _lpi
        draft_year = get_active_rookie_class()
        _pl_idx = _lpi() or {}

        # Build a normalized-name → index map for the model table
        name_to_idx: dict = {}
        for i, p in enumerate(model_value_table):
            norm = _nn(p.get("name") or "")
            if norm:
                name_to_idx[norm] = i

        for r in get_rookie_rankings_from_db(draft_year):
            name = r.get("name") or ""
            norm = _nn(name)
            sid  = str(r.get("sleeper_id") or "")
            # Pull NFL team from players_index (Sleeper) as the most reliable source
            _idx_team = _pl_idx.get(sid, {}).get("team", "") if sid else ""
            _team = r.get("actual_nfl_team") or _idx_team or r.get("team") or "FA"
            rookie_entry = {
                "id": sid or r.get("player_id") or f"rookie_{name}",
                "name": name,
                "team": _team,
                "position": r.get("position") or "UNK",
                "age": r.get("age"),
                "value":       float(r.get("rookie_value")       or 0),
                "sf_value":    float(r.get("rookie_sf_value")    or r.get("rookie_value") or 0),
                "value_8":     float(r.get("rookie_value_8")     or r.get("rookie_value") or 0),
                "value_12":    float(r.get("rookie_value_12")    or r.get("rookie_value") or 0),
                "value_14":    float(r.get("rookie_value_14")    or r.get("rookie_value") or 0),
                "sf_value_8":  float(r.get("rookie_sf_value_8")  or r.get("rookie_sf_value") or 0),
                "sf_value_12": float(r.get("rookie_sf_value_12") or r.get("rookie_sf_value") or 0),
                "sf_value_14": float(r.get("rookie_sf_value_14") or r.get("rookie_sf_value") or 0),
                "pos_rank": None, "pos_rank_label": None,
                "sf_pos_rank": None, "sf_pos_rank_label": None,
                "search_name": norm,
                "is_rookie": True,
                "rank_change_7d": r.get("rank_change_7d"),
            }

            if norm and norm in name_to_idx:
                # Player already in model table (drafted + linked to Sleeper).
                # Mark as rookie and update team. Preserve player_values DB values
                # when present - only fill in gaps with pipeline values.
                existing = model_value_table[name_to_idx[norm]]
                existing["is_rookie"] = True
                if _team and _team != "FA":
                    existing["team"] = _team
                if not float(existing.get("value") or 0):
                    existing["value"]    = rookie_entry["value"]
                if not float(existing.get("sf_value") or 0):
                    existing["sf_value"] = rookie_entry["sf_value"]
                if not float(existing.get("value_8") or 0):
                    existing["value_8"]    = rookie_entry["value_8"]
                if not float(existing.get("value_12") or 0):
                    existing["value_12"]   = rookie_entry["value_12"]
                if not float(existing.get("value_14") or 0):
                    existing["value_14"]   = rookie_entry["value_14"]
                if not float(existing.get("sf_value_8") or 0):
                    existing["sf_value_8"] = rookie_entry["sf_value_8"]
                if not float(existing.get("sf_value_12") or 0):
                    existing["sf_value_12"]= rookie_entry["sf_value_12"]
                if not float(existing.get("sf_value_14") or 0):
                    existing["sf_value_14"]= rookie_entry["sf_value_14"]
            else:
                model_value_table.append(rookie_entry)

    except Exception as _e:
        logger.info(f"[api/league-players] rookies skipped: {_e}")

    # --- Rank labels (no decay applied - DB values are source of truth) ---
    from collections import defaultdict as _dd_prl

    def _recompute_ranks(table, val_key, rank_key, label_key):
        _groups: dict = _dd_prl(list)
        for _i, _p in enumerate(table):
            _pos = str(_p.get("position") or "").upper()
            if _pos and _pos != "PICK":
                _groups[_pos].append(_i)
        for _pos, _idxs in _groups.items():
            _idxs.sort(key=lambda _i: float(table[_i].get(val_key) or 0), reverse=True)
            for _rank, _i in enumerate(_idxs, 1):
                table[_i][rank_key]  = _rank
                table[_i][label_key] = f"{_pos}{_rank}"

    _recompute_ranks(model_value_table, "value",    "pos_rank",    "pos_rank_label")
    _recompute_ranks(model_value_table, "sf_value", "sf_pos_rank", "sf_pos_rank_label")

    _recompute_ranks(model_value_table, "value",    "pos_rank",    "pos_rank_label")
    _recompute_ranks(model_value_table, "sf_value", "sf_pos_rank", "sf_pos_rank_label")

    # Sort players: first by value (descending), then by pos_rank (ascending for ties)
    model_value_table.sort(key=lambda p: (
        -(float(p.get("value") or 0)),
        int(p.get("pos_rank") or 9999)
    ))

    # Add birthday data and compute precise decimal age for all pages that use
    # this endpoint (trade calc, player modal, team modal, breakout, etc.).
    # The value table stores age as a Sleeper integer (23); computing from bDay
    # gives the correct decimal (23.4) that the rankings page already shows.
    try:
        from utils.utils import load_players_index
        players_index = load_players_index() or {}

        for player in model_value_table:
            player_id = str(player.get("id") or "")
            player_data = players_index.get(player_id)
            if player_data:
                bday = player_data.get("bDay")
                player["bDay"] = bday
                precise = age_from_bday(bday)
                if precise is not None:
                    player["age"] = precise
    except Exception as e:
        logger.info(f"[api/league-players] Could not add birthday data: {e}")

    # Enrich with PPG and total points from usage cache (full PPR, min 4 games)
    try:
        import os as _os_lp, json as _json_lp
        _season_lp = date.today().year
        _usage_data_lp = None
        _usage_season_lp = None
        for _s in [_season_lp, _season_lp - 1]:
            _usage_data_lp = _load_usage_rows_cached(_s)  # short-TTL cached
            if _usage_data_lp:
                _usage_season_lp = _s
                break
        if _usage_data_lp:
            _usage_map_lp = {str(p.get("id")): p for p in _usage_data_lp if p.get("id")}
            # Build positional PPG and total_pts lists for ranking
            _pos_ppg_lp: dict = {}
            _pos_total_lp: dict = {}
            for _p in _usage_data_lp:
                _u = _p.get("usage") or {}
                _g = int(_u.get("games") or 0)
                if _g < 4:
                    continue
                _ppg_v = _u.get("ppr_ppg")
                if _ppg_v is None:
                    continue
                _ppg_v = round(float(_ppg_v), 1)
                _tot_v = round(_ppg_v * _g, 1)
                _pos_lp = str(_p.get("position") or "")
                _pos_ppg_lp.setdefault(_pos_lp, []).append(_ppg_v)
                _pos_total_lp.setdefault(_pos_lp, []).append(_tot_v)
            # Sort descending for rank lookup
            _pos_ppg_sorted_lp = {pos: sorted(vals, reverse=True) for pos, vals in _pos_ppg_lp.items()}
            _pos_total_sorted_lp = {pos: sorted(vals, reverse=True) for pos, vals in _pos_total_lp.items()}
            for _player in model_value_table:
                _pid = str(_player.get("id") or "")
                _entry = _usage_map_lp.get(_pid)
                if not _entry:
                    continue
                _u = _entry.get("usage") or {}
                _g = int(_u.get("games") or 0)
                if _g < 4:
                    continue
                _ppg_v = _u.get("ppr_ppg")
                if _ppg_v is None:
                    continue
                _ppg_v = round(float(_ppg_v), 1)
                _tot_v = round(_ppg_v * _g, 1)
                _pos_lp = str(_entry.get("position") or "")
                _ppg_sorted = _pos_ppg_sorted_lp.get(_pos_lp, [])
                _tot_sorted = _pos_total_sorted_lp.get(_pos_lp, [])
                _player["ppg"] = _ppg_v
                _player["total_pts"] = _tot_v
                _player["ppg_games"] = _g
                _player["ppg_season"] = _usage_season_lp
                _player["ppg_rank"] = (_ppg_sorted.index(_ppg_v) + 1) if _ppg_v in _ppg_sorted else None
                _player["total_pts_rank"] = (_tot_sorted.index(_tot_v) + 1) if _tot_v in _tot_sorted else None
    except Exception as _e_lp:
        logger.info(f"[api/league-players] PPG enrichment skipped: {_e_lp}")

    # Compute tier thresholds for every league-type × size combination so the
    # frontend can display each player's tier badge without a second API call.
    _tier_thresholds_all = {}
    for _lt in ("1qb", "sf"):
        _tier_thresholds_all[_lt] = {}
        for _sz in (8, 10, 12, 14):
            _tier_thresholds_all[_lt][str(_sz)] = [
                round(v, 1) for v in
                compute_tier_thresholds(model_value_table, _lt, _sz)
            ]

    # Attach ADP so the rankings/draft room can sort & simulate by ADP.
    # Primary: Sleeper's own ADP from its projections API (api.sleeper.com),
    # server-reachable with no bot/CORS issues. Fallback: ADP aggregated from
    # real Sleeper drafts (our crawler). adp_sources reports which feed was used.
    _adp_sources = {"startup": "none", "rookie": "none", "redraft": "none"}
    try:
        from dashboard_services.adp_service import (
            fetch_league_adp_from_db as _fl_adp,
            fetch_sleeper_adp as _sleeper_adp,
        )
        _adp_season = int((get_nfl_state() or {}).get("season") or datetime.now().year)

        def _norm_adp(_m: dict) -> dict:
            out = {}
            for _k, _v in (_m or {}).items():
                if isinstance(_v, dict):
                    _ap = _v.get("avg_pick")
                    if _ap is None:
                        _ap = _v.get("adp_rank")
                else:
                    _ap = _v
                if _ap is not None:
                    out[str(_k)] = float(_ap)
            return out

        def _crawl_adp(is_sf: bool, draft_type: str, min_s: int) -> dict:
            return _norm_adp(_fl_adp(is_sf, _adp_season, draft_type, min_samples=min_s) or {})

        # DraftCrawl maps (fallback)
        _c_su1, _c_susf = _crawl_adp(False, "startup", 10), _crawl_adp(True, "startup", 10)
        _c_rk1, _c_rksf = _crawl_adp(False, "rookie", 5), _crawl_adp(True, "rookie", 5)

        # Sleeper projections ADP (primary). Pick the first present field per mode.
        _sa = _sleeper_adp(_adp_season) or {}

        def _sa_pick(_pid, *keys):
            _r = _sa.get(_pid) or {}
            for _k in keys:
                if _r.get(_k) is not None:
                    return _r[_k]
            return None

        _used = {"startup": False, "rookie": False, "redraft": False}
        _rookie_from_crawl = False

        def _attach(_p, field, sleeper_val, crawl_map, _pid, mode):
            if sleeper_val is not None:
                _p[field] = sleeper_val
                _used[mode] = True
            elif _pid in crawl_map:
                _p[field] = crawl_map[_pid]

        for _p in model_value_table:
            _pid = str(_p.get("id") or "")
            _attach(_p, "avg_pick", _sa_pick(_pid, "adp_dynasty_ppr", "adp_dynasty_half_ppr", "adp_dynasty_std"), _c_su1, _pid, "startup")
            _attach(_p, "sf_avg_pick", _sa_pick(_pid, "adp_dynasty_2qb", "adp_dynasty_ppr"), _c_susf, _pid, "startup")
            # Rookie ADP: prefer our draft-crawl data (reflects real league picks),
            # fall back to Sleeper community ADP when crawl has no sample.
            _rk_sa = _sa_pick(_pid, "adp_dynasty_rookie", "adp_rookie")
            if _pid in _c_rk1:
                _p["rookie_avg_pick"] = _c_rk1[_pid]; _used["rookie"] = True; _rookie_from_crawl = True
            elif _rk_sa is not None:
                _p["rookie_avg_pick"] = _rk_sa; _used["rookie"] = True
            if _pid in _c_rksf:
                _p["sf_rookie_avg_pick"] = _c_rksf[_pid]; _used["rookie"] = True; _rookie_from_crawl = True
            elif _rk_sa is not None:
                _p["sf_rookie_avg_pick"] = _rk_sa; _used["rookie"] = True
            _r1 = _sa_pick(_pid, "adp_ppr", "adp_half_ppr", "adp_std")
            if _r1 is not None:
                _p["redraft_avg_pick"] = _r1; _used["redraft"] = True
            _rsf = _sa_pick(_pid, "adp_2qb", "adp_ppr")
            if _rsf is not None:
                _p["sf_redraft_avg_pick"] = _rsf; _used["redraft"] = True

        for _mode in ("startup", "rookie", "redraft"):
            if _mode == "rookie" and _rookie_from_crawl:
                _adp_sources[_mode] = "DraftCrawl"
            elif _used[_mode]:
                _adp_sources[_mode] = "Sleeper"
            elif _mode == "startup" and (_c_su1 or _c_susf):
                _adp_sources[_mode] = "Community"
            elif _mode == "rookie" and (_c_rk1 or _c_rksf):
                _adp_sources[_mode] = "DraftCrawl"
    except Exception as _e_adp:
        logger.info("[api/league-players] ADP attach skipped: %s", _e_adp)

    # Optionally append K/DEF (draftable in redraft) when ?kdef=1. Kept out of the
    # default response so dynasty rankings stay skill-position only.
    if request.args.get("kdef"):
        try:
            from utils.utils import load_players_index as _lpi
            _seen = {str(p.get("id")) for p in model_value_table if isinstance(p, dict)}
            _kdef = []
            for _pid, _info in (_lpi() or {}).items():
                _pos = str((_info or {}).get("pos") or "").upper()
                if _pos in ("K", "DEF", "DST") and str(_pid) not in _seen:
                    _kdef.append({
                        "id": str(_pid),
                        "name": (_info.get("name") or str(_pid)),
                        "position": "DEF" if _pos in ("DEF", "DST") else "K",
                        "team": (_info.get("team") or _info.get("nfl") or ""),
                        "value": 0, "sf_value": 0,
                    })
            _kdef.sort(key=lambda x: x["name"])
            model_value_table.extend(_kdef)
        except Exception as _e_kdef:
            logger.info("[api/league-players] K/DEF append skipped: %s", _e_kdef)

    return jsonify(_sanitize_for_json({
        "players": model_value_table,
        "tier_thresholds": _tier_thresholds_all,
        "adp_sources": _adp_sources,
    }))


@app.route("/api/teams")
def api_teams():
    league_id = (request.args.get("league_id") or "").strip()
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    season = int(request.args.get("season") or datetime.now().year)

    if not league_id:
        return jsonify([])

    try:
        ctx = get_league_ctx_from_cache(platform=platform, league_id=league_id, season=season)
        users = ctx.get("users", [])
        rosters = ctx.get("rosters", [])

        teams = []
        for roster in rosters:
            roster_id = str(roster.get("roster_id", ""))
            user_id = roster.get("owner_id")

            # Find the user for this roster
            user = next((u for u in users if u.get("user_id") == user_id), None)
            if user:
                team_name = user.get("team_name") or user.get("display_name") or f"Team {roster_id}"
                username = user.get("username") or user.get("display_name") or ""
            else:
                team_name = f"Team {roster_id}"
                username = ""

            teams.append({
                "roster_id": roster_id,
                "team_name": team_name,
                "username": username,
                "user_id": user_id
            })

        # Sort by team name for consistent ordering
        teams.sort(key=lambda x: x["team_name"])
        return jsonify(teams)

    except Exception as e:
        logger.info(f"[api/teams] error: {e}")
        return jsonify([])


@app.route("/api/league-rosters")
def api_league_rosters():
    """Per-team rosters for the trade calculator's roster filter.

    Returns {teams: [{roster_id, team_name, username, player_ids, pick_rounds}],
    viewer_roster_id}. pick_rounds are "YYYY_R" keys (season + round) a team owns;
    the front end matches PICK assets by their leading "YYYY_R" so round-level pick
    ownership maps onto the slot/bucket pick assets in the value table.
    """
    league_id = (request.args.get("league_id") or "").strip()
    platform = (request.args.get("platform") or "sleeper").strip().lower()
    season = int(request.args.get("season") or datetime.now().year)

    if not league_id:
        return jsonify({"teams": [], "viewer_roster_id": ""})

    # Return cached roster payload if still fresh (pick-slot resolution is expensive).
    _roster_key = (platform, league_id, season)
    _cached = _ROSTER_API_CACHE.get(_roster_key)
    if _cached and time.time() - _cached["ts"] < _ROSTER_API_CACHE_TTL:
        return jsonify(_cached["data"])

    try:
        ctx = get_league_ctx_from_cache(platform=platform, league_id=league_id, season=season)
        users = ctx.get("users", []) or []
        rosters = ctx.get("rosters", []) or []
        picks_by_roster = ctx.get("picks_by_roster", {}) or {}

        teams = []
        for roster in rosters:
            roster_id = str(roster.get("roster_id", ""))
            user_id = roster.get("owner_id")
            user = next((u for u in users if u.get("user_id") == user_id), None)
            if user:
                team_name = user.get("team_name") or user.get("display_name") or f"Team {roster_id}"
                username = user.get("username") or user.get("display_name") or ""
            else:
                team_name = f"Team {roster_id}"
                username = ""
            player_ids = [str(pid) for pid in (roster.get("players") or [])]
            # Resolve each owned pick to its exact draft slot using whichever
            # slot maps are already in HISTORICAL_PICK_SLOT_CACHE (built during
            # normal dashboard loads). If a map isn't cached yet, fall back to
            # round-level counts - never trigger a fresh historical API fetch here.
            pick_ids: list[str] = []
            pick_round_counts: dict[str, int] = {}
            for p in (picks_by_roster.get(roster_id) or []):
                p_season = _safe_int(p.get("season"), 0)
                p_round = _safe_int(p.get("round"), 0)
                if not p_season or not p_round:
                    continue
                slot = None
                orig = p.get("original_owner")
                if orig is not None:
                    # Use cached slot map if available - no blocking fetch.
                    source_season = p_season - 1
                    cached_map = HISTORICAL_PICK_SLOT_CACHE.get(
                        (str(platform).lower(), str(league_id), int(source_season))
                    )
                    if cached_map:
                        try:
                            slot = cached_map.get(int(orig))
                        except (TypeError, ValueError):
                            slot = None
                if slot:
                    pick_ids.append(f"{p_season}_{p_round}_{int(slot):02d}")
                else:
                    k = f"{p_season}_{p_round}"
                    pick_round_counts[k] = pick_round_counts.get(k, 0) + 1
            teams.append({
                "roster_id": roster_id,
                "team_name": team_name,
                "username": username,
                "player_ids": player_ids,
                "pick_ids": sorted(pick_ids),
                "pick_round_counts": pick_round_counts,
            })

        teams.sort(key=lambda x: x["team_name"])
        viewer = get_viewer_session_for_league(users, rosters) or {}
        payload = {
            "teams": teams,
            "viewer_roster_id": str(viewer.get("viewer_roster_id") or ""),
        }
        _ROSTER_API_CACHE[_roster_key] = {"data": payload, "ts": time.time()}
        return jsonify(payload)
    except Exception as e:
        logger.info(f"[api/league-rosters] error: {e}")
        return jsonify({"teams": [], "viewer_roster_id": ""})


@app.route("/api/advanced-metrics/leaderboard")
def api_advanced_metrics_leaderboard():
    """Players ranked by a single advanced metric, for the Advanced Metrics page.

    Premium-gated. Query params: metric (required, whitelisted), position (optional),
    league_id/platform (for the premium check).
    """
    from data_building.advanced_metrics import (
        get_metric_leaderboard, get_weekly_range_leaderboard,
        get_adv_weekly_range_leaderboard, adv_weekly_metric_supported,
        get_value_leaderboard, VALUE_METRICS,
        LEADERBOARD_METRICS, _WEEKLY_METRICS,
        PREMIUM_METRICS, premium_metrics_exposed,
    )

    metric = (request.args.get("metric") or "role_score").strip()
    if metric not in LEADERBOARD_METRICS:
        return jsonify({"error": "unknown metric"}), 400
    # Premium (PFF) metrics are not displayable publicly.
    if metric in PREMIUM_METRICS and not premium_metrics_exposed():
        return jsonify({"error": "metric not available"}), 403
    position = (request.args.get("position") or "").strip().upper() or None
    season_str = (request.args.get("season") or "").strip()
    season = int(season_str) if season_str.isdigit() else None
    min_vol_str = (request.args.get("min_vol") or "").strip()
    min_vol = int(min_vol_str) if min_vol_str.isdigit() else None
    week_start_str = (request.args.get("week_start") or "").strip()
    week_end_str   = (request.args.get("week_end") or "").strip()
    week_start = int(week_start_str) if week_start_str.isdigit() else None
    week_end   = int(week_end_str)   if week_end_str.isdigit()   else None

    # A metric is week-filterable if it has a usage-table aggregation
    # (_WEEKLY_METRICS) or an NGS/FTN/EPA weekly aggregation.
    adv_weekly       = adv_weekly_metric_supported(metric)
    weekly_capable   = (metric in _WEEKLY_METRICS) or adv_weekly
    is_week_filtered = bool(week_start or week_end) and weekly_capable

    try:
        if metric in VALUE_METRICS:
            # Value metrics (VORP/WAR) are league-size aware; derive num_teams
            # from the league context when available, else standard 12-team.
            _num_teams = 12
            try:
                _league_id = (request.args.get("league_id") or "").strip()
                _platform = (request.args.get("platform") or "sleeper").strip()
                if _league_id:
                    _ctx = get_league_ctx_from_cache(_platform, _league_id, season) or {}
                    _num_teams = int(_ctx.get("total_rosters") or 0) or 12
            except Exception:
                _num_teams = 12
            players = get_value_leaderboard(
                metric, position=position, season=season, num_teams=_num_teams,
            )
        elif is_week_filtered and adv_weekly and metric not in _WEEKLY_METRICS:
            players = get_adv_weekly_range_leaderboard(
                metric, position=position, season=season,
                week_start=week_start, week_end=week_end, min_vol=min_vol,
            )
        elif is_week_filtered:
            players = get_weekly_range_leaderboard(
                metric, position=position, season=season,
                week_start=week_start, week_end=week_end, min_vol=min_vol,
            )
        else:
            players = get_metric_leaderboard(metric, position=position, season=season, min_vol=min_vol)
    except Exception as e:
        logger.exception(f"[api/advanced-metrics/leaderboard] error for metric={metric}: {e}")
        players = []

    spec = LEADERBOARD_METRICS[metric]
    vol_col = (spec.get("min_vol") or {}).get("col") or "games"
    resp = jsonify({
        "metric": metric,
        "label": spec["label"],
        "positions": spec["positions"],
        "lower_better": bool(spec.get("lower_better")),
        "vol_col": vol_col,
        "weekly_capable": weekly_capable,
        "is_week_filtered": is_week_filtered,
        "players": players,
    })
    # Leaderboard data is rebuilt at most daily, so let the browser reuse the
    # response for a few minutes — makes graph reopens / metric toggles instant
    # even across page reloads within a session.
    resp.headers["Cache-Control"] = "private, max-age=300"
    return resp


